#[derive(Debug, Default)]
struct TunnelMetrics {
    active_connections: AtomicU64,
    total_connections: AtomicU64,
    tcp_to_ssh_bytes: AtomicU64,
    ssh_to_tcp_bytes: AtomicU64,
    last_activity: Mutex<Option<String>>,
    last_error: Mutex<Option<String>>,
}

impl TunnelMetrics {
    fn connection_opened(&self) {
        self.total_connections.fetch_add(1, Ordering::SeqCst);
        self.active_connections.fetch_add(1, Ordering::SeqCst);
        self.touch();
    }

    fn connection_closed(&self) {
        let _ = self
            .active_connections
            .fetch_update(Ordering::SeqCst, Ordering::SeqCst, |value| {
                Some(value.saturating_sub(1))
            });
        self.touch();
    }

    fn add_tcp_to_ssh_bytes(&self, bytes: usize) {
        self.tcp_to_ssh_bytes
            .fetch_add(bytes as u64, Ordering::SeqCst);
        self.touch();
    }

    fn add_ssh_to_tcp_bytes(&self, bytes: usize) {
        self.ssh_to_tcp_bytes
            .fetch_add(bytes as u64, Ordering::SeqCst);
        self.touch();
    }

    fn record_error(&self, error: &str) {
        if let Ok(mut last_error) = self.last_error.lock() {
            *last_error = Some(error.to_string());
        }
        self.touch();
    }

    fn record_error_if_changed(&self, error: &str) -> bool {
        let changed = if let Ok(mut last_error) = self.last_error.lock() {
            if last_error.as_deref() == Some(error) {
                false
            } else {
                *last_error = Some(error.to_string());
                true
            }
        } else {
            false
        };
        if changed {
            self.touch();
        }
        changed
    }

    fn clear_error(&self) {
        if let Ok(mut last_error) = self.last_error.lock() {
            *last_error = None;
        }
        self.touch();
    }

    fn clear_error_with_prefix(&self, prefix: &str) -> bool {
        let cleared = if let Ok(mut last_error) = self.last_error.lock() {
            if last_error
                .as_deref()
                .is_some_and(|error| error.starts_with(prefix))
            {
                *last_error = None;
                true
            } else {
                false
            }
        } else {
            false
        };
        if cleared {
            self.touch();
        }
        cleared
    }

    fn touch(&self) {
        if let Ok(mut last_activity) = self.last_activity.lock() {
            *last_activity = Some(Utc::now().to_rfc3339());
        }
    }

    fn snapshot(&self, spec: TunnelSpec) -> TunnelStatus {
        TunnelStatus {
            spec,
            active_connections: self.active_connections.load(Ordering::SeqCst),
            total_connections: self.total_connections.load(Ordering::SeqCst),
            tcp_to_ssh_bytes: self.tcp_to_ssh_bytes.load(Ordering::SeqCst),
            ssh_to_tcp_bytes: self.ssh_to_tcp_bytes.load(Ordering::SeqCst),
            last_activity: self
                .last_activity
                .lock()
                .ok()
                .and_then(|value| value.clone()),
            last_error: self.last_error.lock().ok().and_then(|value| value.clone()),
        }
    }
}

