fn install_system_event_sink(state: &AppState) -> Result<(), String> {
    if state
        .system_event_sink
        .lock()
        .map_err(|error| error.to_string())?
        .is_some()
    {
        return Err("system event sink is already installed".to_string());
    }

    let (notifier, wakeups) = std::sync::mpsc::sync_channel(1);
    let (shutdown, shutdown_rx) = std::sync::mpsc::channel();
    let store = Arc::downgrade(&state.store);
    let store_path = state.store_path.clone();
    let app_handle = state.app_handle.clone();
    let worker_store = store.clone();
    let worker = std::thread::Builder::new()
        .name("portmate-system-event-sink".to_string())
        .spawn(move || {
            run_system_event_sink(
                &worker_store,
                &store_path,
                app_handle.as_ref(),
                wakeups,
                shutdown_rx,
            );
        })
        .map_err(|error| format!("failed to start system event sink: {error}"))?;
    let guard = SystemEventSinkGuard {
        store,
        shutdown,
        worker: Mutex::new(Some(worker)),
    };
    let install_result = state
        .store
        .lock()
        .map_err(|error| error.to_string())?
        .set_system_event_notifier(notifier);
    if let Err(error) = install_result {
        guard.shutdown();
        return Err(error);
    }
    *state
        .system_event_sink
        .lock()
        .map_err(|error| error.to_string())? = Some(guard);
    Ok(())
}

fn shutdown_system_event_sink(state: &AppState) {
    let guard = state
        .system_event_sink
        .lock()
        .ok()
        .and_then(|mut guard| guard.take());
    if let Some(guard) = guard {
        guard.shutdown();
    }
}

fn run_system_event_sink(
    store: &Weak<Mutex<SessionStore>>,
    store_path: &Path,
    app_handle: Option<&AppHandle>,
    wakeups: std::sync::mpsc::Receiver<()>,
    shutdown: std::sync::mpsc::Receiver<()>,
) {
    loop {
        if shutdown.try_recv().is_ok() {
            drain_system_event_outbox(store, store_path, app_handle);
            return;
        }
        match wakeups.recv_timeout(Duration::from_millis(100)) {
            Ok(()) => drain_system_event_outbox(store, store_path, app_handle),
            Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {}
            Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {
                drain_system_event_outbox(store, store_path, app_handle);
                return;
            }
        }
    }
}

fn drain_system_event_outbox(
    store: &Weak<Mutex<SessionStore>>,
    store_path: &Path,
    app_handle: Option<&AppHandle>,
) {
    loop {
        let events = match store.upgrade() {
            Some(store) => match store.lock() {
                Ok(mut store) => store.drain_system_event_outbox(),
                Err(error) => {
                    eprintln!("PortMate: system event outbox lock failed: {error}");
                    return;
                }
            },
            None => return,
        };
        if events.is_empty() {
            return;
        }
        for (event, profile) in events {
            publish_system_event(store, store_path, app_handle, event, profile);
        }
    }
}

#[derive(Debug)]
struct PortMateSshHandler {
    profile_id: String,
    host: String,
    port: u16,
    alias: Option<String>,
    policy: portmate_core::HostKeyPolicy,
    host_keys: HostKeyStore,
    one_time_host_key_ids: Vec<String>,
    observed_key: Arc<Mutex<Option<HostKeyObservation>>>,
    host_key_error: Arc<Mutex<Option<String>>>,
    remote_forwards: Arc<Mutex<HashMap<String, TunnelForwardTarget>>>,
}

struct HostKeyScanHandler {
    host: String,
    port: u16,
    alias: Option<String>,
    observed_key: Arc<Mutex<Option<HostKeyObservation>>>,
}

impl client::Handler for PortMateSshHandler {
    type Error = russh::Error;

    async fn check_server_key(
        &mut self,
        server_public_key: &ssh_key::PublicKey,
    ) -> Result<bool, Self::Error> {
        let observation = HostKeyObservation {
            host: self.host.clone(),
            port: self.port,
            alias: self.alias.clone(),
            algorithm: server_public_key.algorithm().to_string(),
            public_key_base64: server_public_key.public_key_base64(),
        };
        *self
            .observed_key
            .lock()
            .expect("host key observation lock poisoned") = Some(observation.clone());

        let evaluation = self
            .host_keys
            .evaluate(&self.profile_id, &self.policy, &observation);
        let accepted = match evaluation {
            Ok(HostKeyEvaluation::Trusted {
                matched_key_id,
                fingerprint_sha256,
            }) if trusted_host_key_allowed(
                &self.policy,
                &matched_key_id,
                &self.one_time_host_key_ids,
            ) =>
            {
                *self
                    .host_key_error
                    .lock()
                    .expect("host key error lock poisoned") = None;
                let _ = fingerprint_sha256;
                true
            }
            Ok(HostKeyEvaluation::Trusted {
                fingerprint_sha256, ..
            }) => {
                *self
                    .host_key_error
                    .lock()
                    .expect("host key error lock poisoned") = Some(format!(
                    "SSH host key requires confirmation for this connection: {fingerprint_sha256}"
                ));
                false
            }
            Ok(HostKeyEvaluation::Unknown {
                alias,
                fingerprint_sha256,
                ..
            }) if self.policy.mode == HostKeyMode::TrustOnFirstUse => {
                *self
                    .host_key_error
                    .lock()
                    .expect("host key error lock poisoned") = None;
                let _ = (alias, fingerprint_sha256);
                true
            }
            Ok(other) => {
                *self
                    .host_key_error
                    .lock()
                    .expect("host key error lock poisoned") =
                    Some(describe_host_key_rejection(&other));
                false
            }
            Err(error) => {
                *self
                    .host_key_error
                    .lock()
                    .expect("host key error lock poisoned") =
                    Some(format!("host key fingerprint 计算失败: {error}"));
                false
            }
        };

        Ok(accepted)
    }

    fn server_channel_open_forwarded_tcpip(
        &mut self,
        channel: Channel<client::Msg>,
        connected_address: &str,
        connected_port: u32,
        originator_address: &str,
        originator_port: u32,
        _session: &mut client::Session,
    ) -> impl std::future::Future<Output = Result<(), Self::Error>> + Send {
        let forwards = Arc::clone(&self.remote_forwards);
        let connected_address = connected_address.to_string();
        let originator_address = originator_address.to_string();
        async move {
            let target = {
                let forwards = forwards
                    .lock()
                    .expect("remote forward target map lock poisoned");
                let key = remote_forward_key(&connected_address, connected_port as u16);
                forwards
                    .get(&key)
                    .or_else(|| forwards.get(&remote_forward_port_key(connected_port as u16)))
                    .cloned()
            };
            if let Some(target) = target {
                tauri::async_runtime::spawn(async move {
                    target.metrics.connection_opened();
                    let result = handle_remote_tunnel_client(
                        channel,
                        target.spec.clone(),
                        originator_address,
                        originator_port as u16,
                        Arc::clone(&target.metrics),
                    )
                    .await;
                    match result {
                        Ok(()) => target.metrics.clear_error(),
                        Err(error) => {
                            target.metrics.record_error(&error);
                            eprintln!("PortMate: remote SSH tunnel client failed: {error}");
                        }
                    }
                    target.metrics.connection_closed();
                });
            }
            Ok(())
        }
    }
}

impl client::Handler for HostKeyScanHandler {
    type Error = russh::Error;

    async fn check_server_key(
        &mut self,
        server_public_key: &ssh_key::PublicKey,
    ) -> Result<bool, Self::Error> {
        *self
            .observed_key
            .lock()
            .expect("host key scan observation lock poisoned") = Some(HostKeyObservation {
            host: self.host.clone(),
            port: self.port,
            alias: self.alias.clone(),
            algorithm: server_public_key.algorithm().to_string(),
            public_key_base64: server_public_key.public_key_base64(),
        });
        Ok(true)
    }
}

