#[tauri::command]
fn preview_profile_secret_migration(
    state: State<'_, AppState>,
    request: ProfileSecretMigrationRequest,
) -> Result<ProfileSecretMigrationPreview, String> {
    let _credential_guard = lock_credential_operations(state.inner())?;
    let store = state.store.lock().map_err(|error| error.to_string())?;
    verify_store_snapshot_is_current(&state.store_path)?;
    ensure_no_pending_profile_secret_migration(&state.store_path)?;
    let mut plan = build_profile_secret_migration_plan(&store, &request)?;
    let plan_token = profile_secret_migration_plan_token(&plan, &request);
    plan.preview.plan_token = plan_token;
    if plan.preview.eligible_secret_count > 0 {
        ensure_portable_vault_ready_for_migration()?;
    }
    Ok(plan.preview)
}

#[tauri::command]
fn migrate_profile_secrets(
    state: State<'_, AppState>,
    request: ProfileSecretMigrationRequest,
    expected_plan_token: String,
) -> Result<ProfileSecretMigrationResponse, String> {
    let _credential_guard = lock_credential_operations(state.inner())?;
    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    verify_store_snapshot_is_current(&state.store_path)?;
    ensure_no_pending_profile_secret_migration(&state.store_path)?;
    let plan = build_profile_secret_migration_plan(&store, &request)?;
    let current_plan_token = profile_secret_migration_plan_token(&plan, &request);
    if expected_plan_token.trim().is_empty() || expected_plan_token != current_plan_token {
        return Err("凭据迁移预检已过期，请重新预检后再执行".to_string());
    }
    if plan.preview.eligible_secret_count > 0 {
        ensure_portable_vault_ready_for_migration()?;
    }
    migrate_profile_secrets_with_journal_io(
        &mut store,
        &request,
        read_secret_from_store,
        write_profile_secret_migration_batch,
        delete_profile_secret_migration_batch,
        |next_store, affected_profile_ids, target_refs, migration_id| {
            persist_profile_secret_migration(
                &state.store_path,
                next_store,
                affected_profile_ids,
                target_refs,
                migration_id,
            )
        },
        |event| persist_profile_secret_migration_journal_event(&state.store_path, event),
    )
}

#[tauri::command]
fn get_profile_secret_migration_recovery(
    state: State<'_, AppState>,
) -> Result<Option<ProfileSecretMigrationRecoverySummary>, String> {
    let _credential_guard = lock_credential_operations(state.inner())?;
    let store = state.store.lock().map_err(|error| error.to_string())?;
    verify_store_snapshot_is_current(&state.store_path)?;
    let Some(journal) = load_profile_secret_migration_journal(&state.store_path)? else {
        return Ok(None);
    };
    Ok(Some(profile_secret_migration_recovery_summary(
        &store,
        &journal,
        portable_vault_recovery_ready()?,
    )))
}

#[tauri::command]
fn export_profile_secret_migration_diagnostics(
    state: State<'_, AppState>,
) -> Result<ProfileSecretMigrationDiagnosticExportResult, String> {
    let _credential_guard = lock_credential_operations(state.inner())?;
    let snapshot_lock = lock_store_snapshot(&state.store_path)?;
    let persisted_store = read_persisted_store_for_migration(&state.store_path)?;
    let result = export_profile_secret_migration_diagnostics_with_io(
        &state.store_path,
        &persisted_store,
        probe_secret_from_store,
        profile_secret_migration_diagnostic_vault_status(),
    );
    drop(snapshot_lock);
    result
}

#[tauri::command]
fn recover_profile_secret_migration(
    state: State<'_, AppState>,
    request: ProfileSecretMigrationRecoveryRequest,
) -> Result<ProfileSecretMigrationRecoveryResponse, String> {
    let migration_id = request.migration_id.trim().to_string();
    Uuid::parse_str(&migration_id).map_err(|_| "凭据迁移恢复 ID 无效".to_string())?;
    let _credential_guard = lock_credential_operations(state.inner())?;
    let store = state.store.lock().map_err(|error| error.to_string())?;
    verify_store_snapshot_is_current(&state.store_path)?;
    let Some(journal) = load_profile_secret_migration_journal(&state.store_path)? else {
        return Ok(ProfileSecretMigrationRecoveryResponse {
            migration_id,
            resolved: true,
            action: "already-resolved".to_string(),
            warnings: Vec::new(),
            pending: None,
        });
    };
    if journal.payload.migration_id != migration_id {
        return Err(format!(
            "当前待恢复迁移为 {}，与请求 ID 不一致",
            journal.payload.migration_id
        ));
    }
    let outcome = recover_profile_secret_migration_with_io(
        &store,
        &journal,
        probe_secret_from_store,
        delete_profile_secret_migration_batch,
        |event| persist_profile_secret_migration_journal_event(&state.store_path, event),
    )?;
    let pending = load_profile_secret_migration_journal(&state.store_path)?
        .map(|journal| {
            Ok::<_, String>(profile_secret_migration_recovery_summary(
                &store,
                &journal,
                portable_vault_recovery_ready()?,
            ))
        })
        .transpose()?;
    Ok(ProfileSecretMigrationRecoveryResponse {
        migration_id,
        resolved: outcome.resolved,
        action: outcome.action,
        warnings: outcome.warnings,
        pending,
    })
}

#[tauri::command]
fn update_client_identity(
    state: State<'_, AppState>,
    request: ClientIdentityUpdateRequest,
) -> Result<ClientIdentityMutationResponse, String> {
    let _credential_guard = lock_credential_operations(state.inner())?;
    ensure_no_pending_profile_secret_migration(&state.store_path)?;
    let identity = normalize_client_identity(
        &request.identity_id,
        IdentityRef {
            id: request.identity_id.clone(),
            label: request.label,
            source: request.source,
            fingerprint_sha256: request.fingerprint_sha256,
            path: request.path,
            secret_ref: request.secret_ref,
        },
        |secret_ref| read_secret_from_store(secret_ref).map(|_| ()),
    )?;
    let new_secret_ref = identity.secret_ref.clone();
    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    let mut next_store = store.clone();
    let (summary, old_secret_ref) = replace_client_identity(
        &mut next_store,
        &request.profile_id,
        &request.identity_id,
        identity,
    )?;
    save_store(&state.store_path, &next_store)?;
    *store = next_store;
    let cleanup_secret_ref = old_secret_ref.filter(|old_secret_ref| {
        new_secret_ref.as_deref().map(str::trim) != Some(old_secret_ref.trim())
    });
    Ok(client_identity_mutation_response(
        &store,
        summary,
        cleanup_secret_ref.as_deref(),
        true,
        delete_secret_from_store,
    ))
}

#[tauri::command]
fn rotate_client_identity(
    state: State<'_, AppState>,
    request: ClientIdentityRotateRequest,
) -> Result<ClientIdentityMutationResponse, String> {
    let _credential_guard = lock_credential_operations(state.inner())?;
    ensure_no_pending_profile_secret_migration(&state.store_path)?;
    let private_key = request
        .private_key
        .trim_end_matches(['\r', '\n'])
        .to_string();
    if private_key.trim().is_empty() {
        return Err("私钥内容不能为空".to_string());
    }
    let (saved_passphrase_ref, current_secret_ref) = {
        let store = state.store.lock().map_err(|error| error.to_string())?;
        let current = find_client_identity(&store, &request.profile_id, &request.identity_id)?;
        if current.source != IdentitySource::ProfileVault {
            return Err("只有 Profile Vault identity 可以轮换私钥".to_string());
        }
        let profile = store
            .profiles
            .iter()
            .find(|profile| profile.id == request.profile_id)
            .ok_or_else(|| format!("unknown session: {}", request.profile_id))?;
        (
            ssh_connection(profile)?.passphrase_secret_ref.clone(),
            current.secret_ref,
        )
    };
    let saved_passphrase = saved_passphrase_ref
        .as_deref()
        .map(|secret_ref| read_optional_secret_ref(Some(secret_ref), "SSH private-key passphrase"))
        .transpose()?
        .flatten();
    let validation_passphrase = saved_passphrase
        .as_deref()
        .or(request.passphrase.as_deref());
    let decoded = decode_secret_key(&private_key, validation_passphrase).map_err(|error| {
        if saved_passphrase.is_some() {
            format!("新私钥无法使用 Profile 已保存的私钥口令解析: {error}")
        } else {
            format!("新私钥无法解析: {error}")
        }
    })?;
    let fingerprint_sha256 =
        compute_ssh_sha256_fingerprint(&decoded.public_key().public_key_base64())
            .map_err(|error| format!("无法计算新私钥指纹: {error}"))?;
    let storage = request.storage.or_else(|| {
        current_secret_ref
            .as_deref()
            .is_some_and(|secret_ref| secret_ref.trim().starts_with("stronghold:"))
            .then_some(SecretStorage::Portable)
    });
    let new_secret_ref = write_new_secret(storage, &private_key)?;

    let result = (|| {
        let mut store = state.store.lock().map_err(|error| error.to_string())?;
        let mut next_store = store.clone();
        let current = find_client_identity(&next_store, &request.profile_id, &request.identity_id)?;
        if current.source != IdentitySource::ProfileVault {
            return Err("只有 Profile Vault identity 可以轮换私钥".to_string());
        }
        let identity = IdentityRef {
            fingerprint_sha256: Some(fingerprint_sha256),
            secret_ref: Some(new_secret_ref.clone()),
            path: None,
            ..current
        };
        let (summary, old_secret_ref) = replace_client_identity(
            &mut next_store,
            &request.profile_id,
            &request.identity_id,
            identity,
        )?;
        save_store(&state.store_path, &next_store)?;
        *store = next_store;
        Ok(client_identity_mutation_response(
            &store,
            summary,
            old_secret_ref.as_deref(),
            true,
            delete_secret_from_store,
        ))
    })();

    if result.is_err() {
        let _ = delete_secret_from_store(&new_secret_ref);
    }
    result
}

#[tauri::command]
fn delete_client_identity(
    state: State<'_, AppState>,
    request: ClientIdentityDeleteRequest,
) -> Result<ClientIdentityMutationResponse, String> {
    let _credential_guard = lock_credential_operations(state.inner())?;
    ensure_no_pending_profile_secret_migration(&state.store_path)?;
    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    let mut next_store = store.clone();
    let (summary, old_secret_ref) =
        remove_client_identity(&mut next_store, &request.profile_id, &request.identity_id)?;
    save_store(&state.store_path, &next_store)?;
    *store = next_store;
    Ok(client_identity_mutation_response(
        &store,
        summary,
        old_secret_ref.as_deref(),
        request.delete_secret,
        delete_secret_from_store,
    ))
}

