async fn transfer_file_via_xmodem(
    state: &AppState,
    request: &StartTransferRequest,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    progress.check_cancelled()?;
    match modem_direction(request)? {
        ModemDirection::Upload {
            local_source,
            remote_destination,
        } => {
            let receiver = runtime_tap_receiver(state, &request.session_id)?;
            let mut completion_receiver = runtime_tap_receiver(state, &request.session_id)?;
            let source_size = fs::metadata(&local_source)
                .map_err(|error| format!("读取 XModem 本地文件元数据失败: {error}"))?
                .len();
            let completion_token = Uuid::new_v4().simple().to_string();
            let remote_start = maybe_start_remote_modem(
                state,
                &request.session_id,
                TransferProtocol::Xmodem,
                true,
                &remote_destination,
            )
            .await?;
            let remote_started = remote_start.is_some();
            let reader = modem_reader_after_start(
                receiver,
                remote_start.as_ref(),
                progress,
                &request.session_id,
            )
            .await?;
            let bytes = xmodem_send_file(
                state,
                &request.session_id,
                reader,
                &local_source,
                remote_started,
                progress,
            )
            .await?;
            if let Some(remote_start) = remote_start.as_ref() {
                wait_for_remote_modem_completion(
                    &mut completion_receiver,
                    remote_start,
                    progress,
                    &request.session_id,
                )
                .await?;
                let command = xmodem_remote_finalize_command(
                    &remote_destination,
                    source_size,
                    &completion_token,
                );
                let _ = send_text_inner(state.session_io(), request.session_id.clone(), command)
                    .await?;
                wait_for_xmodem_remote_completion(
                    &mut completion_receiver,
                    &completion_token,
                    progress,
                    &request.session_id,
                )
                .await?;
            }
            Ok(bytes)
        }
        ModemDirection::Download {
            remote_source,
            local_destination,
        } => {
            let receiver = runtime_tap_receiver(state, &request.session_id)?;
            let mut completion_receiver = runtime_tap_receiver(state, &request.session_id)?;
            let remote_start = maybe_start_remote_modem(
                state,
                &request.session_id,
                TransferProtocol::Xmodem,
                false,
                &remote_source,
            )
            .await?;
            let reader = modem_reader_after_start(
                receiver,
                remote_start.as_ref(),
                progress,
                &request.session_id,
            )
            .await?;
            let bytes = xmodem_receive_file(
                state,
                &request.session_id,
                reader,
                &local_destination,
                progress,
            )
            .await?;
            if let Some(remote_start) = remote_start.as_ref() {
                wait_for_remote_modem_completion(
                    &mut completion_receiver,
                    remote_start,
                    progress,
                    &request.session_id,
                )
                .await?;
            }
            Ok(bytes)
        }
    }
}

