enum ModemDirection {
    Upload {
        local_source: String,
        remote_destination: String,
    },
    Download {
        remote_source: String,
        local_destination: String,
    },
}

fn modem_direction(request: &StartTransferRequest) -> Result<ModemDirection, String> {
    let source_remote = remote_path(&request.source);
    let destination_remote = remote_path(&request.destination);

    match (source_remote, destination_remote) {
        (None, Some(remote_destination)) => Ok(ModemDirection::Upload {
            local_source: request.source.clone(),
            remote_destination: remote_destination.to_string(),
        }),
        (Some(remote_source), None) => Ok(ModemDirection::Download {
            remote_source: remote_source.to_string(),
            local_destination: request.destination.clone(),
        }),
        (None, None) if Path::new(&request.source).is_file() => Ok(ModemDirection::Upload {
            local_source: request.source.clone(),
            remote_destination: request.destination.clone(),
        }),
        _ => Err(
            "Modem transfer expects local -> remote:path upload or remote:path -> local download"
                .to_string(),
        ),
    }
}

struct RemoteModemStart {
    token: String,
    ready_marker: String,
}

impl RemoteModemStart {
    fn success_marker(&self) -> String {
        format!("__PORTMATE_MODEM_{}_DONE__", self.token)
    }

    fn failure_marker(&self) -> String {
        format!("__PORTMATE_MODEM_{}_FAIL__", self.token)
    }
}

async fn maybe_start_remote_modem(
    state: &AppState,
    session_id: &str,
    protocol: TransferProtocol,
    upload: bool,
    remote_path: &str,
) -> Result<Option<RemoteModemStart>, String> {
    if !remote_modem_auto_start_enabled(state, session_id)? {
        return Ok(None);
    }

    let readiness_token = Uuid::new_v4().simple().to_string();
    let command = modem_remote_command(protocol, upload, remote_path, &readiness_token);
    let _ = send_text_inner(state.session_io(), session_id.to_string(), command).await?;
    Ok(Some(RemoteModemStart {
        ready_marker: format!("__PORTMATE_MODEM_{readiness_token}_READY__"),
        token: readiness_token,
    }))
}

fn remote_modem_auto_start_enabled(state: &AppState, session_id: &str) -> Result<bool, String> {
    let profile = {
        let store = state.store.lock().map_err(|error| error.to_string())?;
        store.profile(session_id)
    }
    .ok_or_else(|| format!("unknown session: {session_id}"))?;
    Ok(matches!(
        profile.kind,
        SessionKind::Ssh | SessionKind::Tmux | SessionKind::Shell | SessionKind::Telnet
    ))
}

fn xmodem_remote_finalize_command(
    remote_path: &str,
    source_size: u64,
    completion_token: &str,
) -> String {
    format!(
        concat!(
            "target={}; portmate_status=0; ",
            "if command -v truncate >/dev/null 2>&1; then ",
            "truncate -s {} -- \"$target\"; portmate_status=$?; ",
            "else part=\"$target.portmate-trim\"; ",
            "dd if=\"$target\" of=\"$part\" bs=1 count={} 2>/dev/null ",
            "&& mv -f -- \"$part\" \"$target\"; portmate_status=$?; ",
            "if [ \"$portmate_status\" -ne 0 ]; then rm -f -- \"$part\"; fi; fi; ",
            "if [ \"$portmate_status\" -eq 0 ]; then ",
            "printf '\\n__PORTMATE_XMODEM_%s_DONE__\\n' {}; ",
            "else printf '\\n__PORTMATE_XMODEM_%s_FAIL__%s\\n' {} \"$portmate_status\"; fi\r"
        ),
        shell_quote(remote_path),
        source_size,
        source_size,
        shell_quote(completion_token),
        shell_quote(completion_token),
    )
}

async fn wait_for_xmodem_remote_completion(
    receiver: &mut broadcast::Receiver<Vec<u8>>,
    completion_token: &str,
    progress: &TransferProgressContext,
    session_id: &str,
) -> Result<(), String> {
    let success = format!("__PORTMATE_XMODEM_{completion_token}_DONE__");
    let failure = format!("__PORTMATE_XMODEM_{completion_token}_FAIL__");
    let started = Instant::now();
    let mut output = Vec::new();
    loop {
        progress.check_cancelled()?;
        ensure_modem_session_connected(&progress.state.store, session_id)?;
        let remaining = Duration::from_secs(15).saturating_sub(started.elapsed());
        if remaining.is_zero() {
            return Err("XModem remote finalize timed out".to_string());
        }
        match tokio::time::timeout(remaining.min(MODEM_CANCEL_POLL_INTERVAL), receiver.recv()).await
        {
            Ok(Ok(bytes)) => {
                output.extend_from_slice(&bytes);
                if output
                    .windows(success.len())
                    .any(|window| window == success.as_bytes())
                {
                    return Ok(());
                }
                if output
                    .windows(failure.len())
                    .any(|window| window == failure.as_bytes())
                {
                    return Err(format!(
                        "XModem remote finalize failed: {}",
                        String::from_utf8_lossy(&output)
                    ));
                }
                if output.len() > 64 * 1024 {
                    let keep = success.len().max(failure.len()).saturating_sub(1);
                    output.drain(..output.len().saturating_sub(keep));
                }
            }
            Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
            Ok(Err(broadcast::error::RecvError::Closed)) => {
                return Err("XModem remote finalize stream closed".to_string())
            }
            Err(_) => {}
        }
    }
}

async fn wait_for_remote_modem_completion(
    receiver: &mut broadcast::Receiver<Vec<u8>>,
    remote_start: &RemoteModemStart,
    progress: &TransferProgressContext,
    session_id: &str,
) -> Result<(), String> {
    let success = remote_start.success_marker();
    let failure = remote_start.failure_marker();
    let started = Instant::now();
    let mut output = Vec::new();
    loop {
        progress.check_cancelled()?;
        ensure_modem_session_connected(&progress.state.store, session_id)?;
        let remaining = Duration::from_secs(15).saturating_sub(started.elapsed());
        if remaining.is_zero() {
            return Err("remote modem command completion timed out".to_string());
        }
        match tokio::time::timeout(remaining.min(MODEM_CANCEL_POLL_INTERVAL), receiver.recv()).await
        {
            Ok(Ok(bytes)) => {
                output.extend_from_slice(&bytes);
                if output
                    .windows(success.len())
                    .any(|window| window == success.as_bytes())
                {
                    return Ok(());
                }
                if output
                    .windows(failure.len())
                    .any(|window| window == failure.as_bytes())
                {
                    return Err(format!(
                        "remote modem command failed: {}",
                        String::from_utf8_lossy(&output)
                    ));
                }
                if output.len() > 64 * 1024 {
                    let keep = success.len().max(failure.len()).saturating_sub(1);
                    output.drain(..output.len().saturating_sub(keep));
                }
            }
            Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
            Ok(Err(broadcast::error::RecvError::Closed)) => {
                return Err("remote modem command completion stream closed".to_string())
            }
            Err(_) => {}
        }
    }
}

fn modem_remote_command(
    protocol: TransferProtocol,
    upload: bool,
    remote_path: &str,
    readiness_token: &str,
) -> String {
    match (protocol, upload) {
        (TransferProtocol::Xmodem, true) => format!(
            "{}\r",
            modem_raw_tty_shell_command(
                &format!("rx {}", shell_quote(remote_path)),
                readiness_token,
            )
        ),
        (TransferProtocol::Xmodem, false) => format!(
            "{}\r",
            modem_raw_tty_shell_command(
                &format!("sx {}", shell_quote(remote_path)),
                readiness_token,
            )
        ),
        (TransferProtocol::Ymodem, true) => {
            let (parent, _) = remote_parent_and_file_name(remote_path);
            if parent.is_empty() {
                format!(
                    "{}\r",
                    modem_raw_tty_shell_command("rb -y", readiness_token)
                )
            } else {
                format!(
                    "mkdir -p {} && cd {} && {}\r",
                    shell_quote(&parent),
                    shell_quote(&parent),
                    modem_raw_tty_shell_command("rb -y", readiness_token)
                )
            }
        }
        (TransferProtocol::Ymodem, false) => format!(
            "{}\r",
            modem_raw_tty_shell_command(
                &format!("sb {}", shell_quote(remote_path)),
                readiness_token,
            )
        ),
        (TransferProtocol::Zmodem, true) => {
            let (parent, _) = remote_parent_and_file_name(remote_path);
            if parent.is_empty() {
                format!(
                    "{}\r",
                    modem_raw_tty_shell_command("rz -y", readiness_token)
                )
            } else {
                format!(
                    "mkdir -p {} && cd {} && {}\r",
                    shell_quote(&parent),
                    shell_quote(&parent),
                    modem_raw_tty_shell_command("rz -y", readiness_token)
                )
            }
        }
        (TransferProtocol::Zmodem, false) => format!(
            "{}\r",
            modem_raw_tty_shell_command(
                &format!("sz {}", shell_quote(remote_path)),
                readiness_token,
            )
        ),
        _ => String::new(),
    }
}

fn modem_raw_tty_shell_command(command: &str, readiness_token: &str) -> String {
    format!(
        concat!(
            "{{ portmate_stty=0; ",
            "if command -v stty >/dev/null 2>&1; then ",
            "stty raw -echo; portmate_stty=1; fi; ",
            "printf '__PORTMATE_MODEM_%s_READY__' {}; ",
            "{}; portmate_modem_status=$?; ",
            "if [ \"$portmate_stty\" -eq 1 ]; then stty sane; fi; ",
            "if [ \"$portmate_modem_status\" -eq 0 ]; then ",
            "printf '\\n__PORTMATE_MODEM_%s_DONE__\\n' {}; ",
            "else printf '\\n__PORTMATE_MODEM_%s_FAIL__%s\\n' {} ",
            "\"$portmate_modem_status\"; fi; ",
            "(exit \"$portmate_modem_status\"); }}"
        ),
        shell_quote(readiness_token),
        command,
        shell_quote(readiness_token),
        shell_quote(readiness_token),
    )
}

fn runtime_tap_receiver(
    state: &AppState,
    session_id: &str,
) -> Result<broadcast::Receiver<Vec<u8>>, String> {
    if let Some(tap) = {
        let connections = state.ssh.lock().map_err(|error| error.to_string())?;
        connections
            .get(session_id)
            .map(|runtime| runtime.tap.clone())
    } {
        return Ok(tap.subscribe());
    }
    if let Some(tap) = {
        let connections = state.shell.lock().map_err(|error| error.to_string())?;
        connections
            .get(session_id)
            .map(|runtime| runtime.tap.clone())
    } {
        return Ok(tap.subscribe());
    }
    if let Some(tap) = {
        let connections = state.tcp.lock().map_err(|error| error.to_string())?;
        connections
            .get(session_id)
            .map(|runtime| runtime.tap.clone())
    } {
        return Ok(tap.subscribe());
    }
    if let Some(tap) = {
        let connections = state.serial.lock().map_err(|error| error.to_string())?;
        connections
            .get(session_id)
            .map(|runtime| runtime.tap.clone())
    } {
        return Ok(tap.subscribe());
    }
    Err("需要先连接会话才能执行 X/Y/ZModem 传输".to_string())
}

async fn write_runtime_bytes(
    state: &AppState,
    session_id: &str,
    bytes: &[u8],
) -> Result<(), String> {
    let io = state.session_io();
    let lane = outbound_lane(&io.store_path, session_id)?;
    let _lane_guard = lane.lock().await;
    let wire_bytes = outbound_bytes_for_session(&io.store, session_id, bytes)?;
    let ssh_writer = {
        let connections = state.ssh.lock().map_err(|error| error.to_string())?;
        connections
            .get(session_id)
            .map(|runtime| Arc::clone(&runtime.writer))
    };
    if let Some(writer) = ssh_writer {
        let writer = writer.lock().await;
        writer
            .data(wire_bytes.as_slice())
            .await
            .map_err(|error| format!("SSH modem 写入失败: {error}"))?;
        record_outbound_control_event(&io, session_id, &wire_bytes, "modem", None, false);
        return Ok(());
    }

    let shell_writer = {
        let connections = state.shell.lock().map_err(|error| error.to_string())?;
        connections
            .get(session_id)
            .map(|runtime| Arc::clone(&runtime.writer))
    };
    if let Some(writer) = shell_writer {
        let mut writer = writer.lock().map_err(|error| error.to_string())?;
        writer
            .write_all(&wire_bytes)
            .map_err(|error| format!("Shell modem 写入失败: {error}"))?;
        writer
            .flush()
            .map_err(|error| format!("Shell modem 刷新失败: {error}"))?;
        record_outbound_control_event(&io, session_id, &wire_bytes, "modem", None, false);
        return Ok(());
    }

    let tcp_writer = {
        let connections = state.tcp.lock().map_err(|error| error.to_string())?;
        connections
            .get(session_id)
            .map(|runtime| Arc::clone(&runtime.writer))
    };
    if let Some(writer) = tcp_writer {
        let mut writer = writer.lock().await;
        writer
            .write_all(&wire_bytes)
            .await
            .map_err(|error| format!("TCP/Telnet modem 写入失败: {error}"))?;
        record_outbound_control_event(&io, session_id, &wire_bytes, "modem", None, false);
        return Ok(());
    }

    let serial_writer = {
        let connections = state.serial.lock().map_err(|error| error.to_string())?;
        connections.get(session_id).map(|runtime| {
            (
                runtime.writer.as_ref().map(Arc::clone),
                Arc::clone(&runtime.capture),
            )
        })
    };
    match serial_writer {
        Some((Some(writer), capture)) => {
            let mut writer = writer.lock().map_err(|error| error.to_string())?;
            writer
                .write_all(&wire_bytes)
                .map_err(|error| format!("串口 modem 写入失败: {error}"))?;
            writer
                .flush()
                .map_err(|error| format!("串口 modem 刷新失败: {error}"))?;
            record_serial_capture(&capture, EventDirection::Outbound, &wire_bytes);
            record_outbound_control_event(&io, session_id, &wire_bytes, "modem", None, false);
            return Ok(());
        }
        Some((None, _)) => return Err("串口正在重连，无法执行 modem 写入".to_string()),
        None => {}
    }

    Err("会话尚未连接，无法执行 modem 写入".to_string())
}

async fn check_modem_cancelled(
    state: &AppState,
    session_id: &str,
    progress: &TransferProgressContext,
) -> Result<(), String> {
    if progress.cancel.load(Ordering::SeqCst) {
        let _ = write_runtime_bytes(state, session_id, &[MODEM_CAN, MODEM_CAN, MODEM_CAN]).await;
        Err(TRANSFER_CANCELLED_MESSAGE.to_string())
    } else {
        Ok(())
    }
}

struct ModemByteReader {
    receiver: broadcast::Receiver<Vec<u8>>,
    pending: VecDeque<u8>,
    cancel: Arc<AtomicBool>,
    connection: Option<(Arc<Mutex<SessionStore>>, String)>,
}

impl ModemByteReader {
    fn new(receiver: broadcast::Receiver<Vec<u8>>, cancel: Arc<AtomicBool>) -> Self {
        Self {
            receiver,
            pending: VecDeque::new(),
            cancel,
            connection: None,
        }
    }

    fn watch_connection(mut self, store: Arc<Mutex<SessionStore>>, session_id: String) -> Self {
        self.connection = Some((store, session_id));
        self
    }

    fn check_interrupted(&self) -> Result<(), String> {
        if self.cancel.load(Ordering::SeqCst) {
            return Err(TRANSFER_CANCELLED_MESSAGE.to_string());
        }
        if let Some((store, session_id)) = &self.connection {
            ensure_modem_session_connected(store, session_id)?;
        }
        Ok(())
    }

    async fn after_marker(
        mut receiver: broadcast::Receiver<Vec<u8>>,
        marker: &str,
        cancel: Arc<AtomicBool>,
        connection: Option<(Arc<Mutex<SessionStore>>, String)>,
    ) -> Result<Self, String> {
        let started = Instant::now();
        let marker = marker.as_bytes();
        let mut buffered = Vec::new();
        loop {
            if cancel.load(Ordering::SeqCst) {
                return Err(TRANSFER_CANCELLED_MESSAGE.to_string());
            }
            if let Some((store, session_id)) = &connection {
                ensure_modem_session_connected(store, session_id)?;
            }
            let remaining = Duration::from_secs(15).saturating_sub(started.elapsed());
            if remaining.is_zero() {
                return Err("remote modem readiness marker timed out".to_string());
            }
            match tokio::time::timeout(remaining.min(MODEM_CANCEL_POLL_INTERVAL), receiver.recv())
                .await
            {
                Ok(Ok(bytes)) => {
                    buffered.extend_from_slice(&bytes);
                    if let Some(offset) = buffered
                        .windows(marker.len())
                        .position(|window| window == marker)
                    {
                        return Ok(Self {
                            receiver,
                            pending: buffered[offset + marker.len()..].iter().copied().collect(),
                            cancel,
                            connection,
                        });
                    }
                    if buffered.len() > 64 * 1024 {
                        let keep = marker.len().saturating_sub(1);
                        buffered.drain(..buffered.len().saturating_sub(keep));
                    }
                }
                Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
                Ok(Err(broadcast::error::RecvError::Closed)) => {
                    return Err("remote modem readiness stream closed".to_string())
                }
                Err(_) => {}
            }
        }
    }

    async fn next_byte(&mut self, timeout: Duration) -> Result<u8, String> {
        let started = Instant::now();
        loop {
            self.check_interrupted()?;
            if let Some(byte) = self.pending.pop_front() {
                return Ok(byte);
            }
            let remaining = timeout.saturating_sub(started.elapsed());
            if remaining.is_zero() {
                return Err("modem byte timeout".to_string());
            }
            match tokio::time::timeout(
                remaining.min(MODEM_CANCEL_POLL_INTERVAL),
                self.receiver.recv(),
            )
            .await
            {
                Ok(Ok(bytes)) => self.pending.extend(bytes),
                Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
                Ok(Err(broadcast::error::RecvError::Closed)) => {
                    return Err("modem byte stream closed".to_string())
                }
                Err(_) => {}
            }
        }
    }

    async fn read_exact(&mut self, len: usize, timeout: Duration) -> Result<Vec<u8>, String> {
        let mut bytes = Vec::with_capacity(len);
        while bytes.len() < len {
            bytes.push(self.next_byte(timeout).await?);
        }
        Ok(bytes)
    }

    async fn next_chunk(&mut self, timeout: Duration, max_len: usize) -> Result<Vec<u8>, String> {
        self.check_interrupted()?;
        if !self.pending.is_empty() {
            let take = self.pending.len().min(max_len);
            return Ok(self.pending.drain(..take).collect());
        }

        let started = Instant::now();
        loop {
            self.check_interrupted()?;
            let remaining = timeout.saturating_sub(started.elapsed());
            if remaining.is_zero() {
                return Err("modem byte timeout".to_string());
            }
            match tokio::time::timeout(
                remaining.min(MODEM_CANCEL_POLL_INTERVAL),
                self.receiver.recv(),
            )
            .await
            {
                Ok(Ok(bytes)) => {
                    if bytes.len() <= max_len {
                        return Ok(bytes);
                    }
                    self.pending.extend(bytes[max_len..].iter().copied());
                    return Ok(bytes[..max_len].to_vec());
                }
                Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
                Ok(Err(broadcast::error::RecvError::Closed)) => {
                    return Err("modem byte stream closed".to_string())
                }
                Err(_) => {}
            }
        }
    }
}

async fn modem_reader_after_start(
    receiver: broadcast::Receiver<Vec<u8>>,
    remote_start: Option<&RemoteModemStart>,
    progress: &TransferProgressContext,
    session_id: &str,
) -> Result<ModemByteReader, String> {
    let connection = Some((Arc::clone(&progress.state.store), session_id.to_string()));
    match remote_start {
        Some(start) => {
            ModemByteReader::after_marker(
                receiver,
                &start.ready_marker,
                Arc::clone(&progress.cancel),
                connection,
            )
            .await
        }
        None => Ok(ModemByteReader::new(receiver, Arc::clone(&progress.cancel))
            .watch_connection(Arc::clone(&progress.state.store), session_id.to_string())),
    }
}

fn ensure_modem_session_connected(
    store: &Arc<Mutex<SessionStore>>,
    session_id: &str,
) -> Result<(), String> {
    let store = store.lock().map_err(|error| error.to_string())?;
    let status = store
        .runtimes
        .iter()
        .find(|runtime| runtime.session_id == session_id)
        .map(|runtime| runtime.status)
        .ok_or_else(|| format!("modem session runtime missing: {session_id}"))?;
    if status == SessionStatus::Connected {
        Ok(())
    } else {
        Err(format!("modem session disconnected ({status:?})"))
    }
}

async fn zmodem_send_file(
    state: &AppState,
    session_id: &str,
    mut reader: ModemByteReader,
    local_source: &str,
    remote_destination: Option<&str>,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    let metadata = fs::metadata(local_source)
        .map_err(|error| format!("读取 ZModem 本地文件元数据失败: {error}"))?;
    if !metadata.is_file() {
        return Err("ZModem upload only supports regular local files".to_string());
    }
    let size = u32::try_from(metadata.len())
        .map_err(|_| "ZModem 当前状态机只支持 4 GiB 以内的单文件".to_string())?;
    let mut file = fs::File::open(local_source)
        .map_err(|error| format!("打开 ZModem 本地文件失败: {error}"))?;
    let (_, remote_name) = remote_destination
        .map(remote_parent_and_file_name)
        .unwrap_or_else(|| ("".to_string(), local_file_name(local_source)));
    let file_name = if remote_name.is_empty() {
        local_file_name(local_source)
    } else {
        remote_name
    };

    let mut sender =
        zmodem2::Sender::new().map_err(|error| format!("ZModem sender 初始化失败: {error}"))?;
    sender
        .start_file(file_name.as_bytes(), size)
        .map_err(|error| format!("ZModem 文件发送启动失败: {error}"))?;

    let mut input_buf = Vec::<u8>::new();
    let mut input_offset = 0_usize;
    let mut file_buf = vec![0_u8; 1024];
    let mut session_done = false;
    let mut last_progress = Instant::now();
    let mut bytes_done = 0_u64;

    while !session_done || !sender.drain_outgoing().is_empty() {
        check_modem_cancelled(state, session_id, progress).await?;
        let mut progressed = false;

        let outgoing = sender.drain_outgoing().to_vec();
        if !outgoing.is_empty() {
            write_runtime_bytes(state, session_id, &outgoing).await?;
            sender.advance_outgoing(outgoing.len());
            progressed = true;
        }

        if let Some(request) = sender.poll_file() {
            file.seek(std::io::SeekFrom::Start(u64::from(request.offset)))
                .map_err(|error| format!("ZModem 本地文件 seek 失败: {error}"))?;
            let read_len = request.len.min(file_buf.len());
            let read = file
                .read(&mut file_buf[..read_len])
                .map_err(|error| format!("ZModem 读取本地文件失败: {error}"))?;
            if read == 0 && request.len > 0 {
                return Err("ZModem 本地文件提前结束".to_string());
            }
            sender
                .feed_file(&file_buf[..read])
                .map_err(|error| format!("ZModem 发送文件块失败: {error}"))?;
            bytes_done = bytes_done.max(u64::from(request.offset) + read as u64);
            progress
                .update(bytes_done.min(u64::from(size)), u64::from(size))
                .await?;
            progressed = true;
        }

        match reader.next_chunk(Duration::from_millis(30), 4096).await {
            Ok(bytes) if !bytes.is_empty() => {
                input_buf.extend_from_slice(&bytes);
                progressed = true;
            }
            Ok(_) => {}
            Err(error) if is_modem_timeout(&error) => {}
            Err(error) => return Err(error),
        }

        if sender.drain_outgoing().is_empty() && input_offset < input_buf.len() {
            let consumed = sender
                .feed_incoming(&input_buf[input_offset..])
                .map_err(|error| format!("ZModem 接收远端响应失败: {error}"))?;
            if consumed > 0 {
                input_offset += consumed;
                progressed = true;
                if input_offset == input_buf.len() {
                    input_buf.clear();
                    input_offset = 0;
                } else if input_offset > 4096 {
                    input_buf.drain(..input_offset);
                    input_offset = 0;
                }
            }
        }

        if let Some(event) = sender.poll_event() {
            match event {
                zmodem2::SenderEvent::FileComplete => {
                    sender
                        .finish_session()
                        .map_err(|error| format!("ZModem 结束会话失败: {error}"))?;
                }
                zmodem2::SenderEvent::SessionComplete => {
                    session_done = true;
                }
            }
            progressed = true;
        }

        if progressed {
            last_progress = Instant::now();
        } else if last_progress.elapsed() > Duration::from_secs(90) {
            return Err("ZModem upload idle timeout".to_string());
        } else {
            tokio::time::sleep(Duration::from_millis(5)).await;
        }
    }

    Ok(u64::from(size))
}

async fn zmodem_receive_files(
    state: &AppState,
    session_id: &str,
    mut reader: ModemByteReader,
    local_destination: &str,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    let mut modem_receiver =
        zmodem2::Receiver::new().map_err(|error| format!("ZModem receiver 初始化失败: {error}"))?;
    let mut input_buf = Vec::<u8>::new();
    let mut input_offset = 0_usize;
    let mut current_file: Option<(fs::File, PathBuf)> = None;
    let mut received_files = 0_usize;
    let mut bytes_done = 0_u64;
    let mut session_done = false;
    let mut last_progress = Instant::now();

    while !session_done || !modem_receiver.drain_outgoing().is_empty() {
        check_modem_cancelled(state, session_id, progress).await?;
        let mut progressed = false;

        let outgoing = modem_receiver.drain_outgoing().to_vec();
        if !outgoing.is_empty() {
            write_runtime_bytes(state, session_id, &outgoing).await?;
            modem_receiver.advance_outgoing(outgoing.len());
            progressed = true;
        }

        while let Some(event) = modem_receiver.poll_event() {
            match event {
                zmodem2::ReceiverEvent::FileStart => {
                    let incoming = String::from_utf8_lossy(modem_receiver.file_name()).to_string();
                    let target =
                        zmodem_local_target_path(local_destination, &incoming, received_files)?;
                    if let Some(parent) = target.parent() {
                        fs::create_dir_all(parent).map_err(|error| {
                            format!("创建 ZModem 本地目录失败 {}: {error}", parent.display())
                        })?;
                    }
                    let file = fs::File::create(&target).map_err(|error| {
                        format!("创建 ZModem 本地文件失败 {}: {error}", target.display())
                    })?;
                    current_file = Some((file, target));
                }
                zmodem2::ReceiverEvent::FileComplete => {
                    if let Some((mut file, _)) = current_file.take() {
                        file.flush()
                            .map_err(|error| format!("刷新 ZModem 本地文件失败: {error}"))?;
                    }
                    received_files += 1;
                }
                zmodem2::ReceiverEvent::SessionComplete => {
                    session_done = true;
                }
            }
            progressed = true;
        }

        let file_data = modem_receiver.drain_file().to_vec();
        if !file_data.is_empty() {
            let Some((file, path)) = current_file.as_mut() else {
                return Err("ZModem 收到文件数据但还没有文件头".to_string());
            };
            file.write_all(&file_data)
                .map_err(|error| format!("写入 ZModem 本地文件失败 {}: {error}", path.display()))?;
            modem_receiver
                .advance_file(file_data.len())
                .map_err(|error| format!("ZModem 文件写入确认失败: {error}"))?;
            bytes_done += file_data.len() as u64;
            progress.update(bytes_done, 0).await?;
            progressed = true;
        }

        match reader.next_chunk(Duration::from_millis(30), 4096).await {
            Ok(bytes) if !bytes.is_empty() => {
                input_buf.extend_from_slice(&bytes);
                progressed = true;
            }
            Ok(_) => {}
            Err(error) if is_modem_timeout(&error) => {}
            Err(error) => return Err(error),
        }

        if modem_receiver.drain_outgoing().is_empty()
            && modem_receiver.drain_file().is_empty()
            && input_offset < input_buf.len()
        {
            let consumed = modem_receiver
                .feed_incoming(&input_buf[input_offset..])
                .map_err(|error| format!("ZModem 接收远端数据失败: {error}"))?;
            if consumed > 0 {
                input_offset += consumed;
                progressed = true;
                if input_offset == input_buf.len() {
                    input_buf.clear();
                    input_offset = 0;
                } else if input_offset > 4096 {
                    input_buf.drain(..input_offset);
                    input_offset = 0;
                }
            }
        }

        if progressed {
            last_progress = Instant::now();
        } else if last_progress.elapsed() > Duration::from_secs(90) {
            return Err("ZModem download idle timeout".to_string());
        } else {
            tokio::time::sleep(Duration::from_millis(5)).await;
        }
    }

    if let Some((mut file, _)) = current_file.take() {
        file.flush()
            .map_err(|error| format!("刷新 ZModem 本地文件失败: {error}"))?;
    }

    Ok(bytes_done)
}

fn zmodem_local_target_path(
    local_destination: &str,
    incoming_name: &str,
    received_files: usize,
) -> Result<PathBuf, String> {
    let destination = local_destination.trim();
    if destination.is_empty() {
        return Err("ZModem 本地目标路径不能为空".to_string());
    }
    let incoming = Path::new(incoming_name)
        .file_name()
        .and_then(|value| value.to_str())
        .filter(|value| !value.is_empty())
        .unwrap_or("zmodem-file.bin");
    let base = expand_identity_path(destination);
    let ends_with_separator = destination.ends_with('/') || destination.ends_with('\\');

    if base.is_dir() || ends_with_separator {
        return Ok(base.join(incoming));
    }
    if received_files == 0 {
        return Ok(base);
    }
    Ok(base
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."))
        .join(incoming))
}

async fn xmodem_send_file(
    state: &AppState,
    session_id: &str,
    mut reader: ModemByteReader,
    local_source: &str,
    auto_remote_receiver: bool,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    let data =
        fs::read(local_source).map_err(|error| format!("读取 XModem 本地文件失败: {error}"))?;
    let crc = modem_wait_for_receiver(&mut reader).await?;
    let mut block_no = 1_u8;
    let total = data.len() as u64;
    let mut bytes_done = 0_u64;

    for chunk in data.chunks(XMODEM_BLOCK_SIZE) {
        check_modem_cancelled(state, session_id, progress).await?;
        modem_send_packet_with_retries(
            state,
            session_id,
            &mut reader,
            MODEM_SOH,
            block_no,
            chunk,
            crc,
        )
        .await
        .map_err(|error| format!("XModem data block {block_no} failed: {error}"))?;
        bytes_done += chunk.len() as u64;
        progress.update(bytes_done, total).await?;
        block_no = block_no.wrapping_add(1);
    }
    if auto_remote_receiver {
        modem_finish_auto_remote_xmodem(state, session_id, &mut reader)
            .await
            .map_err(|error| format!("XModem EOT handshake failed: {error}"))?;
    } else {
        modem_finish_eot(state, session_id, &mut reader)
            .await
            .map_err(|error| format!("XModem EOT handshake failed: {error}"))?;
    }
    Ok(data.len() as u64)
}

async fn modem_finish_auto_remote_xmodem(
    state: &AppState,
    session_id: &str,
    reader: &mut ModemByteReader,
) -> Result<(), String> {
    for _ in 0..3 {
        write_runtime_bytes(state, session_id, &[MODEM_EOT]).await?;
        match modem_wait_for_ack(reader, Duration::from_secs(2)).await {
            Ok(ModemAck::Ack) => return Ok(()),
            Ok(ModemAck::Nak) => {}
            Err(error) if is_modem_timeout(&error) => return Ok(()),
            Err(error) => return Err(error),
        }
    }
    Err("remote did not ACK modem EOT".to_string())
}

async fn xmodem_receive_file(
    state: &AppState,
    session_id: &str,
    mut reader: ModemByteReader,
    local_destination: &str,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    let mut expected = 1_u8;
    let mut output = Vec::new();
    let mut first_packet = true;

    loop {
        check_modem_cancelled(state, session_id, progress).await?;
        let marker = if first_packet {
            first_packet = false;
            modem_wait_for_packet_marker(state, session_id, &mut reader).await?
        } else {
            modem_wait_for_next_marker(&mut reader, Duration::from_secs(15)).await?
        };
        if marker == MODEM_EOT {
            write_runtime_bytes(state, session_id, &[MODEM_ACK]).await?;
            break;
        }
        let packet = match modem_read_packet(&mut reader, marker).await {
            Ok(packet) => packet,
            Err(error) => {
                write_runtime_bytes(state, session_id, &[MODEM_NAK]).await?;
                return Err(error);
            }
        };
        if packet.block_no == expected {
            output.extend_from_slice(&packet.data);
            progress.update(output.len() as u64, 0).await?;
            expected = expected.wrapping_add(1);
        }
        write_runtime_bytes(state, session_id, &[MODEM_ACK]).await?;
    }

    while output.last().copied() == Some(MODEM_EOF) {
        output.pop();
    }
    write_local_transfer_file(local_destination, &output)?;
    Ok(output.len() as u64)
}

async fn ymodem_send_file(
    state: &AppState,
    session_id: &str,
    mut reader: ModemByteReader,
    local_source: &str,
    remote_destination: Option<&str>,
    auto_remote_receiver: bool,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    let data =
        fs::read(local_source).map_err(|error| format!("读取 YModem 本地文件失败: {error}"))?;
    if !modem_wait_for_receiver(&mut reader).await? {
        return Err("YModem receiver did not request CRC mode".to_string());
    }

    let (_, remote_name) = remote_destination
        .map(remote_parent_and_file_name)
        .unwrap_or_else(|| ("".to_string(), local_file_name(local_source)));
    let name = if remote_name.is_empty() {
        local_file_name(local_source)
    } else {
        remote_name
    };
    let mut metadata = vec![0_u8; XMODEM_BLOCK_SIZE];
    let metadata_text = format!("{}\0{} ", name, data.len());
    let metadata_bytes = metadata_text.as_bytes();
    let metadata_len = metadata_bytes.len().min(metadata.len());
    metadata[..metadata_len].copy_from_slice(&metadata_bytes[..metadata_len]);
    modem_send_packet_with_retries(
        state,
        session_id,
        &mut reader,
        MODEM_SOH,
        0,
        &metadata,
        true,
    )
    .await
    .map_err(|error| format!("YModem metadata block failed: {error}"))?;
    let _ = modem_wait_for_crc_request(&mut reader, Duration::from_secs(10)).await;

    let mut block_no = 1_u8;
    let total = data.len() as u64;
    let mut bytes_done = 0_u64;
    for chunk in data.chunks(YMODEM_BLOCK_SIZE) {
        check_modem_cancelled(state, session_id, progress).await?;
        modem_send_packet_with_retries(
            state,
            session_id,
            &mut reader,
            MODEM_STX,
            block_no,
            chunk,
            true,
        )
        .await
        .map_err(|error| format!("YModem data block {block_no} failed: {error}"))?;
        bytes_done += chunk.len() as u64;
        progress.update(bytes_done, total).await?;
        block_no = block_no.wrapping_add(1);
    }
    modem_finish_eot(state, session_id, &mut reader)
        .await
        .map_err(|error| format!("YModem EOT handshake failed: {error}"))?;
    let _ = modem_wait_for_crc_request(&mut reader, Duration::from_secs(10)).await;
    if auto_remote_receiver {
        modem_finish_auto_remote_ymodem_batch(state, session_id, &mut reader)
            .await
            .map_err(|error| format!("YModem final empty block failed: {error}"))?;
    } else {
        let empty = vec![0_u8; XMODEM_BLOCK_SIZE];
        modem_send_packet_with_retries(state, session_id, &mut reader, MODEM_SOH, 0, &empty, true)
            .await
            .map_err(|error| format!("YModem final empty block failed: {error}"))?;
    }
    Ok(data.len() as u64)
}

async fn modem_finish_auto_remote_ymodem_batch(
    state: &AppState,
    session_id: &str,
    reader: &mut ModemByteReader,
) -> Result<(), String> {
    let empty = vec![0_u8; XMODEM_BLOCK_SIZE];
    let packet = modem_packet_bytes(MODEM_SOH, 0, &empty, XMODEM_BLOCK_SIZE, true);
    for _ in 0..3 {
        write_runtime_bytes(state, session_id, &packet).await?;
        match modem_wait_for_ack(reader, Duration::from_secs(2)).await {
            Ok(ModemAck::Ack) => return Ok(()),
            Ok(ModemAck::Nak) => {}
            Err(error) if is_modem_timeout(&error) => return Ok(()),
            Err(error) => return Err(error),
        }
    }
    Err("remote rejected final YModem empty block".to_string())
}

async fn ymodem_receive_file(
    state: &AppState,
    session_id: &str,
    mut reader: ModemByteReader,
    local_destination: &str,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    let marker = modem_wait_for_packet_marker(state, session_id, &mut reader).await?;
    if marker == MODEM_EOT {
        return Err("YModem sender ended before metadata block".to_string());
    }
    let metadata = modem_read_packet(&mut reader, marker).await?;
    if metadata.block_no != 0 {
        return Err("YModem metadata block missing".to_string());
    }
    let (name, expected_size) = parse_ymodem_metadata(&metadata.data);
    if name.is_empty() {
        write_runtime_bytes(state, session_id, &[MODEM_ACK]).await?;
        return Err("YModem sender sent empty batch".to_string());
    }
    write_runtime_bytes(state, session_id, &[MODEM_ACK, MODEM_CRC_REQUEST]).await?;

    let mut expected = 1_u8;
    let mut output = Vec::new();
    let total = expected_size.unwrap_or(0) as u64;
    loop {
        check_modem_cancelled(state, session_id, progress).await?;
        let marker = modem_wait_for_next_marker(&mut reader, Duration::from_secs(15)).await?;
        if marker == MODEM_EOT {
            write_runtime_bytes(state, session_id, &[MODEM_ACK, MODEM_CRC_REQUEST]).await?;
            if let Ok(final_marker) =
                modem_wait_for_next_marker(&mut reader, Duration::from_secs(5)).await
            {
                if final_marker != MODEM_EOT {
                    let final_packet = modem_read_packet(&mut reader, final_marker).await?;
                    if final_packet.block_no == 0 {
                        write_runtime_bytes(state, session_id, &[MODEM_ACK]).await?;
                    }
                }
            }
            break;
        }
        let packet = modem_read_packet(&mut reader, marker).await?;
        if packet.block_no == expected {
            output.extend_from_slice(&packet.data);
            progress.update(output.len() as u64, total).await?;
            expected = expected.wrapping_add(1);
        }
        write_runtime_bytes(state, session_id, &[MODEM_ACK]).await?;
    }

    if let Some(size) = expected_size {
        output.truncate(size.min(output.len()));
    } else {
        while output.last().copied() == Some(MODEM_EOF) {
            output.pop();
        }
    }
    let destination = if Path::new(local_destination).is_dir() {
        let safe_name = Path::new(&name)
            .file_name()
            .and_then(|value| value.to_str())
            .filter(|value| !value.is_empty())
            .unwrap_or("ymodem-file.bin");
        Path::new(local_destination)
            .join(safe_name)
            .display()
            .to_string()
    } else {
        local_destination.to_string()
    };
    write_local_transfer_file(&destination, &output)?;
    Ok(output.len() as u64)
}

struct ModemPacket {
    block_no: u8,
    data: Vec<u8>,
}

async fn modem_wait_for_receiver(reader: &mut ModemByteReader) -> Result<bool, String> {
    let started = Instant::now();
    loop {
        let remaining = Duration::from_secs(45).saturating_sub(started.elapsed());
        if remaining.is_zero() {
            return Err("modem receiver did not send NAK/C within 45s".to_string());
        }
        match reader
            .next_byte(remaining.min(Duration::from_secs(3)))
            .await
        {
            Ok(MODEM_CRC_REQUEST) => return Ok(true),
            Ok(MODEM_NAK) => return Ok(false),
            Ok(MODEM_CAN) => return Err("modem transfer cancelled by remote".to_string()),
            Ok(_) => {}
            Err(error) if is_modem_timeout(&error) => {}
            Err(error) => return Err(error),
        }
    }
}

async fn modem_wait_for_crc_request(
    reader: &mut ModemByteReader,
    timeout: Duration,
) -> Result<(), String> {
    let started = Instant::now();
    loop {
        let remaining = timeout.saturating_sub(started.elapsed());
        if remaining.is_zero() {
            return Err("timed out waiting for YModem CRC request".to_string());
        }
        match reader
            .next_byte(remaining.min(Duration::from_secs(2)))
            .await
        {
            Ok(MODEM_CRC_REQUEST) => return Ok(()),
            Ok(MODEM_CAN) => return Err("modem transfer cancelled by remote".to_string()),
            Ok(_) => {}
            Err(error) if is_modem_timeout(&error) => {}
            Err(error) => return Err(error),
        }
    }
}

async fn modem_send_packet_with_retries(
    state: &AppState,
    session_id: &str,
    reader: &mut ModemByteReader,
    marker: u8,
    block_no: u8,
    payload: &[u8],
    crc: bool,
) -> Result<(), String> {
    let size = if marker == MODEM_STX {
        YMODEM_BLOCK_SIZE
    } else {
        XMODEM_BLOCK_SIZE
    };
    let packet = modem_packet_bytes(marker, block_no, payload, size, crc);
    modem_send_packet_bytes_with_retries(
        state,
        session_id,
        reader,
        block_no,
        &packet,
        MODEM_ACK_TIMEOUT,
    )
    .await
}

async fn modem_send_packet_bytes_with_retries(
    state: &AppState,
    session_id: &str,
    reader: &mut ModemByteReader,
    block_no: u8,
    packet: &[u8],
    ack_timeout: Duration,
) -> Result<(), String> {
    for _ in 0..MODEM_MAX_RETRIES {
        write_runtime_bytes(state, session_id, packet).await?;
        match modem_wait_for_ack(reader, ack_timeout).await {
            Ok(ModemAck::Ack) => return Ok(()),
            Ok(ModemAck::Nak) => {}
            Err(error) if is_modem_timeout(&error) => {}
            Err(error) => return Err(error),
        }
    }
    Err(format!(
        "modem block {block_no} was not acknowledged after {MODEM_MAX_RETRIES} attempts"
    ))
}

fn modem_packet_bytes(marker: u8, block_no: u8, payload: &[u8], size: usize, crc: bool) -> Vec<u8> {
    let mut data = vec![MODEM_EOF; size];
    data[..payload.len().min(size)].copy_from_slice(&payload[..payload.len().min(size)]);
    let mut packet = Vec::with_capacity(3 + size + if crc { 2 } else { 1 });
    packet.push(marker);
    packet.push(block_no);
    packet.push(255_u8.wrapping_sub(block_no));
    packet.extend_from_slice(&data);
    if crc {
        let crc = crc16_xmodem(&data);
        packet.extend_from_slice(&crc.to_be_bytes());
    } else {
        packet.push(data.iter().fold(0_u8, |sum, byte| sum.wrapping_add(*byte)));
    }
    packet
}

enum ModemAck {
    Ack,
    Nak,
}

async fn modem_wait_for_ack(
    reader: &mut ModemByteReader,
    timeout: Duration,
) -> Result<ModemAck, String> {
    let started = Instant::now();
    loop {
        let remaining = timeout.saturating_sub(started.elapsed());
        if remaining.is_zero() {
            return Err("timed out waiting for modem ACK".to_string());
        }
        match reader
            .next_byte(remaining.min(Duration::from_secs(2)))
            .await
        {
            Ok(MODEM_ACK) => return Ok(ModemAck::Ack),
            Ok(MODEM_NAK) => return Ok(ModemAck::Nak),
            Ok(MODEM_CAN) => return Err("modem transfer cancelled by remote".to_string()),
            Ok(_) => {}
            Err(error) if is_modem_timeout(&error) => {}
            Err(error) => return Err(error),
        }
    }
}

async fn modem_finish_eot(
    state: &AppState,
    session_id: &str,
    reader: &mut ModemByteReader,
) -> Result<(), String> {
    modem_finish_eot_with_timeout(state, session_id, reader, MODEM_ACK_TIMEOUT).await
}

async fn modem_finish_eot_with_timeout(
    state: &AppState,
    session_id: &str,
    reader: &mut ModemByteReader,
    ack_timeout: Duration,
) -> Result<(), String> {
    for _ in 0..MODEM_MAX_RETRIES {
        write_runtime_bytes(state, session_id, &[MODEM_EOT]).await?;
        match modem_wait_for_ack(reader, ack_timeout).await {
            Ok(ModemAck::Ack) => return Ok(()),
            Ok(ModemAck::Nak) => {}
            Err(error) if is_modem_timeout(&error) => {}
            Err(error) => return Err(error),
        }
    }
    Err(format!(
        "remote did not ACK modem EOT after {MODEM_MAX_RETRIES} attempts"
    ))
}

async fn modem_wait_for_packet_marker(
    state: &AppState,
    session_id: &str,
    reader: &mut ModemByteReader,
) -> Result<u8, String> {
    for _ in 0..24 {
        write_runtime_bytes(state, session_id, &[MODEM_CRC_REQUEST]).await?;
        match modem_wait_for_next_marker(reader, Duration::from_secs(3)).await {
            Ok(marker) => return Ok(marker),
            Err(error) if is_modem_timeout(&error) => {}
            Err(error) => return Err(error),
        }
    }
    Err("timed out waiting for modem packet".to_string())
}

async fn modem_wait_for_next_marker(
    reader: &mut ModemByteReader,
    timeout: Duration,
) -> Result<u8, String> {
    loop {
        match reader.next_byte(timeout).await? {
            MODEM_SOH => return Ok(MODEM_SOH),
            MODEM_STX => return Ok(MODEM_STX),
            MODEM_EOT => return Ok(MODEM_EOT),
            MODEM_CAN => return Err("modem transfer cancelled by remote".to_string()),
            _ => {}
        }
    }
}

async fn modem_read_packet(
    reader: &mut ModemByteReader,
    marker: u8,
) -> Result<ModemPacket, String> {
    let size = match marker {
        MODEM_SOH => XMODEM_BLOCK_SIZE,
        MODEM_STX => YMODEM_BLOCK_SIZE,
        _ => return Err(format!("unexpected modem packet marker: {marker}")),
    };
    let header = reader.read_exact(2, Duration::from_secs(5)).await?;
    let block_no = header[0];
    let inverse = header[1];
    if block_no != 255_u8.wrapping_sub(inverse) {
        return Err("modem packet block number check failed".to_string());
    }
    let mut data = reader.read_exact(size + 2, Duration::from_secs(8)).await?;
    let received_crc = u16::from_be_bytes([data[size], data[size + 1]]);
    data.truncate(size);
    let actual_crc = crc16_xmodem(&data);
    if received_crc != actual_crc {
        return Err(format!(
            "modem packet CRC mismatch: received={received_crc:04x} actual={actual_crc:04x}"
        ));
    }
    Ok(ModemPacket { block_no, data })
}

fn crc16_xmodem(data: &[u8]) -> u16 {
    let mut crc = 0_u16;
    for byte in data {
        crc ^= u16::from(*byte) << 8;
        for _ in 0..8 {
            crc = if crc & 0x8000 != 0 {
                (crc << 1) ^ 0x1021
            } else {
                crc << 1
            };
        }
    }
    crc
}

fn write_local_transfer_file(path: &str, data: &[u8]) -> Result<(), String> {
    let destination = Path::new(path);
    if let Some(parent) = destination
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        fs::create_dir_all(parent).map_err(|error| format!("创建本地目录失败: {error}"))?;
    }
    fs::write(destination, data).map_err(|error| format!("写入本地文件失败: {error}"))
}

fn parse_ymodem_metadata(data: &[u8]) -> (String, Option<usize>) {
    let name_end = data
        .iter()
        .position(|byte| *byte == 0)
        .unwrap_or(data.len());
    let name = String::from_utf8_lossy(&data[..name_end])
        .trim()
        .to_string();
    let rest = if name_end < data.len() {
        &data[name_end + 1..]
    } else {
        &[]
    };
    let rest = String::from_utf8_lossy(rest);
    let size = rest
        .split_whitespace()
        .next()
        .and_then(|value| value.parse::<usize>().ok());
    (name, size)
}

fn local_file_name(path: &str) -> String {
    Path::new(path)
        .file_name()
        .and_then(|value| value.to_str())
        .filter(|value| !value.is_empty())
        .unwrap_or("portmate-transfer.bin")
        .to_string()
}

fn remote_parent_and_file_name(path: &str) -> (String, String) {
    let normalized = path.trim_end_matches('/');
    let Some((parent, name)) = normalized.rsplit_once('/') else {
        return (String::new(), normalized.to_string());
    };
    (parent.to_string(), name.to_string())
}

fn is_modem_timeout(error: &str) -> bool {
    error.contains("timeout") || error.contains("timed out")
}

fn remote_path(value: &str) -> Option<&str> {
    value
        .strip_prefix("remote:")
        .or_else(|| value.strip_prefix("ssh:"))
        .filter(|path| !path.trim().is_empty())
}

fn ssh_handle_for_transfer(
    state: &AppState,
    session_id: &str,
) -> Result<Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>, String> {
    let connections = state.ssh.lock().map_err(|error| error.to_string())?;
    connections
        .get(session_id)
        .map(|runtime| Arc::clone(&runtime.handle))
        .ok_or_else(|| "需要先连接 SSH/Tmux 会话才能执行 remote: 传输".to_string())
}

async fn copy_local_file_for_transfer(
    source: &str,
    destination: &str,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    let source = PathBuf::from(source);
    let destination = PathBuf::from(destination);
    if !source.is_file() {
        return Err(
            "only local file copy is available for this protocol path right now".to_string(),
        );
    }
    let total = fs::metadata(&source)
        .map_err(|error| format!("failed to read transfer source metadata: {error}"))?
        .len();
    if let Some(parent) = destination.parent() {
        fs::create_dir_all(parent)
            .map_err(|error| format!("failed to create transfer destination: {error}"))?;
    }
    let temp_destination = local_resume_part_path(&destination);
    let mut input =
        fs::File::open(&source).map_err(|error| format!("local transfer open failed: {error}"))?;
    let mut copied = local_resume_offset(&temp_destination, total)?;
    progress.set_rate_baseline(copied);
    if copied > 0 {
        input
            .seek(std::io::SeekFrom::Start(copied))
            .map_err(|error| format!("local transfer seek failed: {error}"))?;
        progress.update(copied, total).await?;
    }
    if copied == total {
        finalize_local_resume_file(&temp_destination, &destination)?;
        return Ok(copied);
    }
    let mut output = open_local_resume_writer(&temp_destination, copied)
        .map_err(|error| format!("local transfer create failed: {error}"))?;
    let mut buffer = vec![0_u8; 64 * 1024];
    loop {
        progress.check_cancelled()?;
        let read = input
            .read(&mut buffer)
            .map_err(|error| format!("local transfer read failed: {error}"))?;
        if read == 0 {
            break;
        }
        output
            .write_all(&buffer[..read])
            .map_err(|error| format!("local transfer write failed: {error}"))?;
        copied += read as u64;
        progress.update(copied, total).await?;
    }
    output
        .flush()
        .map_err(|error| format!("local transfer flush failed: {error}"))?;
    drop(output);
    finalize_local_resume_file(&temp_destination, &destination)?;
    Ok(copied)
}

async fn open_sftp_session(
    handle: Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>,
) -> Result<SftpSession, String> {
    let channel = {
        let handle = handle.lock().await;
        handle
            .channel_open_session()
            .await
            .map_err(|error| format!("SFTP 打开 SSH channel 失败: {error}"))?
    };
    channel
        .request_subsystem(true, "sftp")
        .await
        .map_err(|error| format!("SFTP subsystem 启动失败: {error}"))?;
    let sftp = SftpSession::new(channel.into_stream())
        .await
        .map_err(|error| format!("SFTP 初始化失败: {error}"))?;
    sftp.set_timeout(20);
    Ok(sftp)
}

/// A transfer writes to a temp sibling of the real destination and is only
/// renamed onto it after a full success; on any error the temp is best-effort
/// removed. Otherwise a mid-transfer failure leaves a partial file at the real
/// destination path with nothing distinguishing it from a complete one.
fn local_resume_part_path(target: &Path) -> PathBuf {
    let name = target
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("portmate-transfer");
    target.with_file_name(format!("{name}.portmate-part"))
}

fn local_resume_offset(path: &Path, total: u64) -> Result<u64, String> {
    let Ok(metadata) = fs::metadata(path) else {
        return Ok(0);
    };
    let size = metadata.len();
    if size <= total {
        Ok(size)
    } else {
        fs::remove_file(path)
            .map_err(|error| format!("删除过大的断点文件失败 {}: {error}", path.display()))?;
        Ok(0)
    }
}

fn open_local_resume_writer(path: &Path, offset: u64) -> std::io::Result<fs::File> {
    if offset == 0 {
        OpenOptions::new()
            .create(true)
            .truncate(true)
            .write(true)
            .open(path)
    } else {
        OpenOptions::new().create(true).append(true).open(path)
    }
}

fn finalize_local_resume_file(temp: &Path, target: &Path) -> Result<(), String> {
    if target.exists() && target.is_file() {
        fs::remove_file(target)
            .map_err(|error| format!("删除旧目标文件失败 {}: {error}", target.display()))?;
    }
    fs::rename(temp, target).map_err(|error| {
        format!(
            "重命名本地目标文件失败 {} -> {}: {error}",
            temp.display(),
            target.display()
        )
    })
}

fn remote_resume_part_path(target: &str) -> String {
    match target.rsplit_once('/') {
        Some((dir, name)) => format!("{dir}/{name}.portmate-part"),
        None => format!("{target}.portmate-part"),
    }
}

async fn sftp_resume_offset(sftp: &SftpSession, path: &str, total: u64) -> Result<u64, String> {
    let Some(size) = sftp
        .metadata(path.to_string())
        .await
        .ok()
        .and_then(|metadata| metadata.size)
    else {
        return Ok(0);
    };
    if size <= total {
        Ok(size)
    } else {
        sftp.remove_file(path.to_string())
            .await
            .map_err(|error| format!("SFTP 删除过大的断点文件失败 {path}: {error}"))?;
        Ok(0)
    }
}

async fn sftp_open_resume_writer(
    sftp: &SftpSession,
    path: &str,
    offset: u64,
) -> Result<russh_sftp::client::fs::File, String> {
    let flags = if offset == 0 {
        OpenFlags::CREATE | OpenFlags::TRUNCATE | OpenFlags::WRITE
    } else {
        OpenFlags::CREATE | OpenFlags::WRITE
    };
    let mut file = sftp
        .open_with_flags(path.to_string(), flags)
        .await
        .map_err(|error| format!("SFTP 打开断点文件失败 {path}: {error}"))?;
    if offset > 0 {
        file.seek(std::io::SeekFrom::Start(offset))
            .await
            .map_err(|error| format!("SFTP 断点文件 seek 失败 {path}: {error}"))?;
    }
    Ok(file)
}

async fn sftp_finalize_resume_file(
    sftp: &SftpSession,
    temp: &str,
    target: &str,
) -> Result<(), String> {
    let _ = sftp.remove_file(target.to_string()).await;
    sftp.rename(temp.to_string(), target.to_string())
        .await
        .map_err(|error| format!("SFTP 重命名断点文件失败 {temp} -> {target}: {error}"))
}

async fn sftp_upload(
    sftp: &SftpSession,
    local_source: &str,
    remote_destination: &str,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    let metadata = fs::metadata(local_source)
        .map_err(|error| format!("读取本地文件元数据失败 {local_source}: {error}"))?;
    if !metadata.is_file() {
        return Err("SFTP upload only supports regular local files".to_string());
    }
    let mut local_file = fs::File::open(local_source)
        .map_err(|error| format!("打开本地文件失败 {local_source}: {error}"))?;
    let file_name = Path::new(local_source)
        .file_name()
        .and_then(|value| value.to_str())
        .filter(|value| !value.is_empty())
        .unwrap_or("portmate-upload.bin");
    let target = sftp_destination_file_path(sftp, remote_destination, file_name).await?;
    let temp_target = remote_resume_part_path(&target);
    let mut copied = sftp_resume_offset(sftp, &temp_target, metadata.len()).await?;
    progress.set_rate_baseline(copied);
    if copied > 0 {
        local_file
            .seek(std::io::SeekFrom::Start(copied))
            .map_err(|error| format!("SFTP 本地文件 seek 失败 {local_source}: {error}"))?;
        progress.update(copied, metadata.len()).await?;
    }
    if copied == metadata.len() {
        sftp_finalize_resume_file(sftp, &temp_target, &target).await?;
        return Ok(copied);
    }
    let mut remote_file = sftp_open_resume_writer(sftp, &temp_target, copied).await?;

    let copy_result: Result<u64, String> = async {
        let mut buffer = vec![0_u8; 64 * 1024];
        loop {
            progress.check_cancelled()?;
            let read = local_file
                .read(&mut buffer)
                .map_err(|error| format!("读取本地文件失败 {local_source}: {error}"))?;
            if read == 0 {
                break;
            }
            remote_file
                .write_all(&buffer[..read])
                .await
                .map_err(|error| format!("SFTP 写入远端文件失败 {temp_target}: {error}"))?;
            copied += read as u64;
            progress.update(copied, metadata.len()).await?;
        }
        remote_file
            .flush()
            .await
            .map_err(|error| format!("SFTP 刷新远端文件失败 {temp_target}: {error}"))?;
        remote_file
            .shutdown()
            .await
            .map_err(|error| format!("SFTP 关闭远端文件失败 {temp_target}: {error}"))?;
        Ok(copied)
    }
    .await;

    match copy_result {
        Ok(copied) => {
            sftp_finalize_resume_file(sftp, &temp_target, &target).await?;
            Ok(copied)
        }
        Err(error) => Err(error),
    }
}

async fn sftp_download(
    sftp: &SftpSession,
    remote_source: &str,
    local_destination: &str,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    let mut remote_file = sftp
        .open(remote_source.to_string())
        .await
        .map_err(|error| format!("SFTP 打开远端文件失败 {remote_source}: {error}"))?;
    let total = sftp
        .metadata(remote_source.to_string())
        .await
        .ok()
        .and_then(|metadata| metadata.size)
        .unwrap_or(0);
    let target = local_destination_file_path(local_destination, remote_source)?;
    if let Some(parent) = target.parent() {
        fs::create_dir_all(parent)
            .map_err(|error| format!("创建本地目录失败 {}: {error}", parent.display()))?;
    }
    let temp_target = local_resume_part_path(&target);
    let mut copied = local_resume_offset(&temp_target, total)?;
    progress.set_rate_baseline(copied);
    if copied > 0 {
        remote_file
            .seek(std::io::SeekFrom::Start(copied))
            .await
            .map_err(|error| format!("SFTP 远端文件 seek 失败 {remote_source}: {error}"))?;
        progress.update(copied, total).await?;
    }
    if total > 0 && copied == total {
        finalize_local_resume_file(&temp_target, &target)?;
        let _ = remote_file.shutdown().await;
        return Ok(copied);
    }
    let mut local_file = open_local_resume_writer(&temp_target, copied)
        .map_err(|error| format!("创建本地目标文件失败 {}: {error}", temp_target.display()))?;
    let mut buffer = vec![0_u8; 64 * 1024];
    loop {
        progress.check_cancelled()?;
        let read = remote_file
            .read(&mut buffer)
            .await
            .map_err(|error| format!("SFTP 读取远端文件失败 {remote_source}: {error}"))?;
        if read == 0 {
            break;
        }
        local_file
            .write_all(&buffer[..read])
            .map_err(|error| format!("写入本地目标文件失败 {}: {error}", temp_target.display()))?;
        copied += read as u64;
        progress.update(copied, total).await?;
    }
    local_file
        .flush()
        .map_err(|error| format!("刷新本地目标文件失败 {}: {error}", temp_target.display()))?;
    drop(local_file);
    finalize_local_resume_file(&temp_target, &target)?;
    let _ = remote_file.shutdown().await;
    Ok(copied)
}

async fn sftp_remote_copy(
    sftp: &SftpSession,
    remote_source: &str,
    remote_destination: &str,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    let mut source_file = sftp
        .open(remote_source.to_string())
        .await
        .map_err(|error| format!("SFTP 打开远端源文件失败 {remote_source}: {error}"))?;
    let total = sftp
        .metadata(remote_source.to_string())
        .await
        .ok()
        .and_then(|metadata| metadata.size)
        .unwrap_or(0);
    let file_name = remote_file_name(remote_source);
    let target = sftp_destination_file_path(sftp, remote_destination, &file_name).await?;
    let temp_target = remote_resume_part_path(&target);
    let mut copied = sftp_resume_offset(sftp, &temp_target, total).await?;
    progress.set_rate_baseline(copied);
    if copied > 0 {
        source_file
            .seek(std::io::SeekFrom::Start(copied))
            .await
            .map_err(|error| format!("SFTP 远端源文件 seek 失败 {remote_source}: {error}"))?;
        progress.update(copied, total).await?;
    }
    if total > 0 && copied == total {
        sftp_finalize_resume_file(sftp, &temp_target, &target).await?;
        let _ = source_file.shutdown().await;
        return Ok(copied);
    }
    let mut target_file = sftp_open_resume_writer(sftp, &temp_target, copied).await?;

    let copy_result: Result<u64, String> = async {
        let mut buffer = vec![0_u8; 64 * 1024];
        loop {
            progress.check_cancelled()?;
            let read = source_file
                .read(&mut buffer)
                .await
                .map_err(|error| format!("SFTP 读取远端源文件失败 {remote_source}: {error}"))?;
            if read == 0 {
                break;
            }
            target_file
                .write_all(&buffer[..read])
                .await
                .map_err(|error| format!("SFTP 写入远端目标文件失败 {temp_target}: {error}"))?;
            copied += read as u64;
            progress.update(copied, total).await?;
        }
        target_file
            .flush()
            .await
            .map_err(|error| format!("SFTP 刷新远端目标文件失败 {temp_target}: {error}"))?;
        target_file
            .shutdown()
            .await
            .map_err(|error| format!("SFTP 关闭远端目标文件失败 {temp_target}: {error}"))?;
        Ok(copied)
    }
    .await;
    let _ = source_file.shutdown().await;

    match copy_result {
        Ok(copied) => {
            sftp_finalize_resume_file(sftp, &temp_target, &target).await?;
            Ok(copied)
        }
        Err(error) => Err(error),
    }
}

async fn sftp_destination_file_path(
    sftp: &SftpSession,
    remote_destination: &str,
    source_name: &str,
) -> Result<String, String> {
    let destination = remote_destination.trim();
    if destination.is_empty() {
        return Err("SFTP 远端目标路径不能为空".to_string());
    }

    if destination.ends_with('/') {
        sftp_create_dir_all(sftp, destination).await?;
        return Ok(remote_join_path(destination, source_name));
    }

    if let Ok(metadata) = sftp.metadata(destination.to_string()).await {
        if metadata.is_dir() {
            return Ok(remote_join_path(destination, source_name));
        }
    }

    if let Some(parent) = remote_parent_path(destination) {
        if parent != "." && parent != "/" {
            sftp_create_dir_all(sftp, &parent).await?;
        }
    }
    Ok(destination.to_string())
}

fn local_destination_file_path(
    local_destination: &str,
    remote_source: &str,
) -> Result<PathBuf, String> {
    let destination = expand_identity_path(local_destination.trim());
    if local_destination.trim().is_empty() {
        return Err("本地目标路径不能为空".to_string());
    }
    let source_name = remote_file_name(remote_source);
    let ends_with_separator = local_destination.ends_with('/') || local_destination.ends_with('\\');
    if destination.is_dir() || ends_with_separator {
        Ok(destination.join(source_name))
    } else {
        Ok(destination)
    }
}

async fn sftp_create_dir_all(sftp: &SftpSession, path: &str) -> Result<(), String> {
    let path = path.trim().trim_end_matches('/');
    if path.is_empty() || path == "." || path == "/" {
        return Ok(());
    }

    let mut current = if path.starts_with('/') {
        "/".to_string()
    } else {
        String::new()
    };
    for part in path
        .split('/')
        .filter(|part| !part.is_empty() && *part != ".")
    {
        current = remote_join_path(&current, part);
        match sftp.create_dir(current.clone()).await {
            Ok(()) => {}
            Err(error) => match sftp.metadata(current.clone()).await {
                Ok(metadata) if metadata.is_dir() => {}
                _ => return Err(format!("SFTP 创建远端目录失败 {current}: {error}")),
            },
        }
    }
    Ok(())
}

fn remote_parent_path(path: &str) -> Option<String> {
    let path = path.trim().trim_end_matches('/');
    let index = path.rfind('/')?;
    if index == 0 {
        Some("/".to_string())
    } else {
        Some(path[..index].to_string())
    }
}

fn remote_file_name(path: &str) -> String {
    path.trim()
        .trim_end_matches('/')
        .rsplit('/')
        .next()
        .filter(|value| !value.is_empty())
        .unwrap_or("portmate-file.bin")
        .to_string()
}

fn remote_join_path(parent: &str, name: &str) -> String {
    let name = name.trim_matches('/');
    if parent.is_empty() || parent == "." {
        name.to_string()
    } else if parent == "/" {
        format!("/{name}")
    } else {
        format!("{}/{}", parent.trim_end_matches('/'), name)
    }
}

async fn remote_copy(
    handle: Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>,
    remote_source: &str,
    remote_destination: &str,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    let command = remote_copy_command(remote_source, remote_destination);
    let mut channel = {
        let handle = handle.lock().await;
        handle
            .channel_open_session()
            .await
            .map_err(|error| format!("SSH remote copy 打开 channel 失败: {error}"))?
    };
    channel
        .exec(true, command)
        .await
        .map_err(|error| format!("SSH remote copy 启动失败: {error}"))?;

    let mut output = Vec::new();
    let mut stderr = Vec::new();
    let mut exit_status = None;
    let mut reported_total = None;
    let mut reported_resume = None;
    let mut reported_progress = None;
    let mut reported_done = None;
    let started = Instant::now();

    loop {
        if progress.cancel.load(Ordering::SeqCst) {
            let _ = channel.eof().await;
            let _ = channel.close().await;
            return Err(TRANSFER_CANCELLED_MESSAGE.to_string());
        }
        if started.elapsed() > Duration::from_secs(300) {
            let _ = channel.close().await;
            return Err("SSH remote copy 超时".to_string());
        }

        match tokio::time::timeout(Duration::from_millis(250), channel.wait()).await {
            Ok(Some(ChannelMsg::Data { data })) => {
                output.extend_from_slice(&data);
                let markers = remote_copy_markers(&output);
                if markers.total.is_some() && markers.total != reported_total {
                    let total = markers.total.unwrap_or_default();
                    progress.update(0, total).await?;
                    reported_total = Some(total);
                }
                if markers.resume.is_some() && markers.resume != reported_resume {
                    let mut resume_bytes = markers.resume.unwrap_or_default();
                    if let Some(total) = markers.total.or(reported_total) {
                        resume_bytes = resume_bytes.min(total);
                    }
                    progress.set_rate_baseline(resume_bytes);
                    progress
                        .update(resume_bytes, markers.total.or(reported_total).unwrap_or(0))
                        .await?;
                    reported_resume = Some(markers.resume.unwrap_or_default());
                }
                if markers.progress.is_some() && markers.progress != reported_progress {
                    let mut progress_bytes = markers.progress.unwrap_or_default();
                    if let Some(total) = markers.total.or(reported_total) {
                        progress_bytes = progress_bytes.min(total);
                    }
                    progress
                        .update(
                            progress_bytes,
                            markers.total.or(reported_total).unwrap_or(0),
                        )
                        .await?;
                    reported_progress = Some(markers.progress.unwrap_or_default());
                }
                if markers.done.is_some() && markers.done != reported_done {
                    let done = markers.done.unwrap_or_default();
                    progress
                        .update(done, reported_total.unwrap_or(done))
                        .await?;
                    reported_done = Some(done);
                }
            }
            Ok(Some(ChannelMsg::ExtendedData { data, .. })) => stderr.extend_from_slice(&data),
            Ok(Some(ChannelMsg::ExitStatus { exit_status: code })) => exit_status = Some(code),
            Ok(Some(ChannelMsg::Eof | ChannelMsg::Close)) | Ok(None) => break,
            Ok(Some(_)) => {}
            Err(_) => {}
        }
    }

    if exit_status.is_some_and(|code| code != 0) {
        return Err(format!(
            "SSH remote copy 返回非零状态 {:?}: {}",
            exit_status,
            String::from_utf8_lossy(&stderr)
        ));
    }

    let markers = remote_copy_markers(&output);
    let bytes = markers.done.ok_or_else(|| {
        format!(
            "remote copy completed but done marker was missing: {}",
            String::from_utf8_lossy(&output)
        )
    })?;
    progress
        .update(bytes, reported_total.unwrap_or(bytes))
        .await?;
    Ok(bytes)
}

fn remote_copy_command(remote_source: &str, remote_destination: &str) -> String {
    format!(
        concat!(
            "src={}; dst={}; target=; part=; pid=; ",
            "remote_name=${{src##*/}}; if [ -z \"$remote_name\" ]; then remote_name=portmate-file.bin; fi; ",
            "case \"$dst\" in */) target=\"${{dst%/}}/$remote_name\" ;; ",
            "*) if [ -d \"$dst\" ]; then target=\"${{dst%/}}/$remote_name\"; else target=\"$dst\"; fi ;; esac; ",
            "case \"$target\" in */*) part=\"${{target%/*}}/${{target##*/}}.portmate-part\" ;; ",
            "*) part=\"$target.portmate-part\" ;; esac; ",
            "cleanup() {{ if [ -n \"$pid\" ]; then kill \"$pid\" 2>/dev/null || :; fi; }}; ",
            "trap cleanup INT TERM HUP EXIT; ",
            "if ! total=$(stat -c %s -- \"$src\"); then exit 1; fi; ",
            "printf '__PORTMATE_SIZE__%s\\n' \"$total\"; ",
            "offset=0; ",
            "if [ -e \"$part\" ]; then ",
            "if current=$(stat -c %s -- \"$part\" 2>/dev/null); then ",
            "if [ \"$current\" -le \"$total\" ]; then offset=$current; else : > \"$part\" || exit 1; fi; ",
            "else : > \"$part\" || exit 1; fi; ",
            "else : > \"$part\" || exit 1; fi; ",
            "printf '__PORTMATE_RESUME__%s\\n' \"$offset\"; ",
            "printf '__PORTMATE_PROGRESS__%s\\n' \"$offset\"; ",
            "if [ \"$offset\" -lt \"$total\" ]; then ",
            "tail -c +$((offset + 1)) -- \"$src\" >> \"$part\" & pid=$!; ",
            "while kill -0 \"$pid\" 2>/dev/null; do ",
            "if current=$(stat -c %s -- \"$part\" 2>/dev/null); then ",
            "printf '__PORTMATE_PROGRESS__%s\\n' \"$current\"; ",
            "fi; sleep 0.25; done; ",
            "wait \"$pid\"; status=$?; pid=; ",
            "if [ \"$status\" -ne 0 ]; then exit \"$status\"; fi; ",
            "fi; ",
            "final=$(stat -c %s -- \"$part\") || exit 1; ",
            "if [ \"$final\" -ne \"$total\" ]; then ",
            "printf 'PortMate remote copy size mismatch: %s of %s\\n' \"$final\" \"$total\" >&2; exit 1; ",
            "fi; ",
            "mv -f -- \"$part\" \"$target\" || exit 1; ",
            "stat -c '__PORTMATE_DONE__%s' -- \"$target\""
        ),
        shell_quote(remote_source),
        shell_quote(remote_destination)
    )
}

#[derive(Debug, Default, PartialEq, Eq)]
struct RemoteCopyMarkers {
    total: Option<u64>,
    resume: Option<u64>,
    progress: Option<u64>,
    done: Option<u64>,
}

fn remote_copy_markers(output: &[u8]) -> RemoteCopyMarkers {
    let text = String::from_utf8_lossy(output);
    let mut markers = RemoteCopyMarkers::default();
    for line in text.lines() {
        if let Some(value) = line.trim().strip_prefix("__PORTMATE_SIZE__") {
            markers.total = value.trim().parse::<u64>().ok();
        } else if let Some(value) = line.trim().strip_prefix("__PORTMATE_RESUME__") {
            markers.resume = value.trim().parse::<u64>().ok();
        } else if let Some(value) = line.trim().strip_prefix("__PORTMATE_PROGRESS__") {
            markers.progress = value.trim().parse::<u64>().ok();
        } else if let Some(value) = line.trim().strip_prefix("__PORTMATE_DONE__") {
            markers.done = value.trim().parse::<u64>().ok();
        }
    }
    markers
}

enum FileOperation {
    CreateDirectory,
    Delete,
}

const MAX_EXTERNAL_DROP_ROOTS: usize = 512;
const MAX_EXTERNAL_DROP_ENTRIES: usize = 20_000;
const MAX_EXTERNAL_DROP_FILES: usize = 5_000;

#[derive(Debug)]
struct ExternalDropRoot {
    path: PathBuf,
    is_dir: bool,
}

#[derive(Debug)]
struct ExternalDropFile {
    source: PathBuf,
    relative: PathBuf,
}

#[derive(Debug, Default)]
struct ExternalDropPlan {
    directories: Vec<PathBuf>,
    files: Vec<ExternalDropFile>,
    skipped: Vec<String>,
    total_bytes: u64,
}

#[derive(Debug)]
struct FileBatchPlanFile {
    source: String,
    relative: String,
    size: u64,
}

#[derive(Debug, Default)]
struct FileBatchPlan {
    directories: Vec<String>,
    files: Vec<FileBatchPlanFile>,
    skipped: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BatchTargetKind {
    Missing,
    File,
    Directory,
    Other,
}

async fn start_file_batch_inner(
    state: &AppState,
    request: StartFileBatchRequest,
) -> Result<ExternalDropResult, String> {
    if request.source_remote == request.destination_remote {
        return Err("文件批次必须在本地与远端面板之间传输".to_string());
    }
    {
        let store = state.store.lock().map_err(|error| error.to_string())?;
        if store.profile(&request.session_id).is_none() {
            return Err(format!("unknown session: {}", request.session_id));
        }
    }
    if request.paths.is_empty() {
        return Err("文件批次没有源路径".to_string());
    }
    if request.paths.len() > MAX_EXTERNAL_DROP_ROOTS {
        return Err(format!(
            "一次最多选择 {MAX_EXTERNAL_DROP_ROOTS} 个顶层路径，当前为 {} 个",
            request.paths.len()
        ));
    }

    let handle = ssh_handle_for_transfer(state, &request.session_id)?;
    let sftp = open_sftp_session(handle).await?;
    let result = async {
        let mut plan = if request.source_remote {
            plan_remote_file_batch(&sftp, &request.paths).await?
        } else {
            plan_local_file_batch(&request.paths)?
        };
        let local_destination = if request.destination_remote {
            validate_remote_batch_destination(&sftp, &request.destination).await?;
            None
        } else {
            Some(validate_local_drop_destination(&request.destination)?)
        };

        let mut directory_targets = Vec::with_capacity(plan.directories.len());
        for relative in &plan.directories {
            validate_batch_relative_path(relative)?;
            let target = batch_destination_path(
                request.destination.trim(),
                local_destination.as_deref(),
                relative,
                request.destination_remote,
            )?;
            match batch_target_kind(Some(&sftp), &target, request.destination_remote).await? {
                BatchTargetKind::Missing => directory_targets.push(target),
                BatchTargetKind::Directory => {}
                BatchTargetKind::File | BatchTargetKind::Other => {
                    return Err(format!("目标目录路径已被非目录占用: {target}"));
                }
            }
        }

        let mut reserved_targets = HashSet::new();
        let mut prepared_files = Vec::with_capacity(plan.files.len());
        let mut total_bytes = 0_u64;
        for file in plan.files {
            validate_batch_relative_path(&file.relative)?;
            let mut relative = file.relative.clone();
            let mut target = batch_destination_path(
                request.destination.trim(),
                local_destination.as_deref(),
                &relative,
                request.destination_remote,
            )?;
            let kind = batch_target_kind(Some(&sftp), &target, request.destination_remote).await?;
            let conflict =
                kind != BatchTargetKind::Missing || !reserved_targets.insert(target.clone());
            if conflict {
                match request.conflict_policy {
                    TransferConflictPolicy::Fail => {
                        return Err(format!("目标文件已存在或批次内冲突: {target}"));
                    }
                    TransferConflictPolicy::Skip => {
                        plan.skipped
                            .push(format!("{} (destination exists: {target})", file.source));
                        continue;
                    }
                    TransferConflictPolicy::Overwrite => {
                        if !matches!(kind, BatchTargetKind::File | BatchTargetKind::Missing) {
                            return Err(format!("拒绝用文件覆盖非普通文件目标: {target}"));
                        }
                        reserved_targets.insert(target.clone());
                    }
                    TransferConflictPolicy::Rename => {
                        let mut renamed = None;
                        for suffix in 1..=10_000_u32 {
                            let candidate_relative =
                                numbered_batch_relative_path(&file.relative, suffix)?;
                            let candidate = batch_destination_path(
                                request.destination.trim(),
                                local_destination.as_deref(),
                                &candidate_relative,
                                request.destination_remote,
                            )?;
                            if !reserved_targets.contains(&candidate)
                                && batch_target_kind(
                                    Some(&sftp),
                                    &candidate,
                                    request.destination_remote,
                                )
                                .await?
                                    == BatchTargetKind::Missing
                            {
                                renamed = Some((candidate_relative, candidate));
                                break;
                            }
                        }
                        let (candidate_relative, candidate) = renamed
                            .ok_or_else(|| format!("无法为冲突目标生成可用名称: {target}"))?;
                        relative = candidate_relative;
                        target = candidate;
                        reserved_targets.insert(target.clone());
                    }
                }
            }
            total_bytes = total_bytes
                .checked_add(file.size)
                .ok_or_else(|| "文件批次总大小溢出".to_string())?;
            prepared_files.push((file.source, relative, target));
        }

        directory_targets.sort_by_key(|path| batch_path_depth(path));
        for target in &directory_targets {
            if request.destination_remote {
                sftp_create_dir_all(&sftp, target).await?;
            } else {
                fs::create_dir_all(target)
                    .map_err(|error| format!("创建本地批次目录失败 {target}: {error}"))?;
            }
        }

        Ok::<_, String>((
            prepared_files,
            directory_targets.len(),
            plan.skipped,
            total_bytes,
        ))
    }
    .await;
    let _ = sftp.close().await;
    let (prepared_files, directories_prepared, mut skipped, total_bytes) = result?;

    let mut tasks = Vec::with_capacity(prepared_files.len());
    for (source, _relative, target) in prepared_files {
        let source = if request.source_remote {
            format!("remote:{source}")
        } else {
            source
        };
        let destination = if request.destination_remote {
            format!("remote:{target}")
        } else {
            target
        };
        tasks.push(
            start_transfer_inner(
                state,
                StartTransferRequest {
                    session_id: request.session_id.clone(),
                    protocol: TransferProtocol::Sftp,
                    source,
                    destination,
                },
            )
            .await?,
        );
    }
    skipped.sort();
    skipped.dedup();
    Ok(ExternalDropResult {
        tasks,
        directories_prepared,
        skipped,
        total_bytes,
    })
}

fn plan_local_file_batch(paths: &[String]) -> Result<FileBatchPlan, String> {
    let plan = plan_external_drop(paths, None)?;
    Ok(FileBatchPlan {
        directories: plan
            .directories
            .iter()
            .map(|path| external_relative_remote_path(path))
            .collect::<Result<Vec<_>, _>>()?,
        files: plan
            .files
            .into_iter()
            .map(|file| {
                let source = file.source.to_str().ok_or_else(|| {
                    format!("批次源路径不是有效 Unicode: {}", file.source.display())
                })?;
                Ok(FileBatchPlanFile {
                    source: source.to_string(),
                    relative: external_relative_remote_path(&file.relative)?,
                    size: fs::metadata(&file.source)
                        .map_err(|error| {
                            format!("读取批次源文件失败 {}: {error}", file.source.display())
                        })?
                        .len(),
                })
            })
            .collect::<Result<Vec<_>, String>>()?,
        skipped: plan.skipped,
    })
}

async fn plan_remote_file_batch(
    sftp: &SftpSession,
    paths: &[String],
) -> Result<FileBatchPlan, String> {
    let mut roots = Vec::new();
    let mut skipped = Vec::new();
    for raw in paths {
        let path = normalize_remote_batch_source(raw)?;
        if roots.iter().any(|existing: &(String, bool)| {
            path == existing.0 || (existing.1 && remote_path_is_within(&path, &existing.0))
        }) {
            skipped.push(format!("{path} (already included)"));
            continue;
        }
        let metadata = sftp
            .symlink_metadata(path.clone())
            .await
            .map_err(|error| format!("SFTP 读取批次源路径失败 {path}: {error}"))?;
        if metadata.is_symlink() {
            skipped.push(format!("{path} (symbolic link)"));
            continue;
        }
        if !metadata.is_dir() && !metadata.is_regular() {
            skipped.push(format!("{path} (not a regular file or directory)"));
            continue;
        }
        roots.push((path, metadata.is_dir()));
    }

    let mut plan = FileBatchPlan {
        skipped,
        ..FileBatchPlan::default()
    };
    let mut visited = 0_usize;
    for (root, _) in roots {
        let root_name = remote_file_name(&root);
        validate_batch_relative_path(&root_name)?;
        let mut stack = vec![(root, root_name)];
        while let Some((source, relative)) = stack.pop() {
            visited += 1;
            if visited > MAX_EXTERNAL_DROP_ENTRIES {
                return Err(format!(
                    "远端目录超过 {MAX_EXTERNAL_DROP_ENTRIES} 个条目，请缩小批次"
                ));
            }
            let metadata = sftp
                .symlink_metadata(source.clone())
                .await
                .map_err(|error| format!("SFTP 读取远端目录项失败 {source}: {error}"))?;
            if metadata.is_symlink() {
                plan.skipped.push(format!("{source} (symbolic link)"));
                continue;
            }
            if metadata.is_dir() {
                plan.directories.push(relative.clone());
                let mut children = sftp
                    .read_dir(source.clone())
                    .await
                    .map_err(|error| format!("SFTP 读取远端目录失败 {source}: {error}"))?
                    .collect::<Vec<_>>();
                children.sort_by_key(|entry| entry.file_name());
                for child in children.into_iter().rev() {
                    let name = child.file_name();
                    if matches!(name.as_str(), "." | "..") {
                        continue;
                    }
                    validate_batch_relative_path(&name)?;
                    stack.push((
                        remote_join_path(&source, &name),
                        remote_join_path(&relative, &name),
                    ));
                }
            } else if metadata.is_regular() {
                if plan.files.len() >= MAX_EXTERNAL_DROP_FILES {
                    return Err(format!(
                        "一次最多传输 {MAX_EXTERNAL_DROP_FILES} 个文件，请缩小批次"
                    ));
                }
                plan.files.push(FileBatchPlanFile {
                    source,
                    relative,
                    size: metadata.len(),
                });
            } else {
                plan.skipped
                    .push(format!("{source} (not a regular file or directory)"));
            }
        }
    }
    validate_file_batch_plan(&mut plan)?;
    Ok(plan)
}

fn validate_file_batch_plan(plan: &mut FileBatchPlan) -> Result<(), String> {
    plan.directories.sort_by(|left, right| {
        batch_path_depth(left)
            .cmp(&batch_path_depth(right))
            .then_with(|| left.cmp(right))
    });
    if let Some(conflict) = plan
        .directories
        .windows(2)
        .find(|pair| pair[0] == pair[1])
        .map(|pair| &pair[0])
    {
        return Err(format!("文件批次包含冲突的目标目录: {conflict}"));
    }
    plan.files
        .sort_by(|left, right| left.relative.cmp(&right.relative));
    let directories = plan.directories.iter().collect::<HashSet<_>>();
    let mut files = HashSet::new();
    for file in &plan.files {
        if directories.contains(&file.relative) || !files.insert(file.relative.as_str()) {
            return Err(format!("文件批次包含冲突的目标路径: {}", file.relative));
        }
    }
    plan.skipped.sort();
    plan.skipped.dedup();
    Ok(())
}

fn normalize_remote_batch_source(path: &str) -> Result<String, String> {
    let path = path.trim().trim_end_matches('/');
    if path.is_empty() || matches!(path, "." | ".." | "~") || path.contains('\0') || path == "/" {
        return Err("拒绝传输空路径、当前目录或远端根目录".to_string());
    }
    Ok(path.to_string())
}

fn remote_path_is_within(path: &str, parent: &str) -> bool {
    path == parent
        || path
            .strip_prefix(parent)
            .is_some_and(|suffix| suffix.starts_with('/'))
}

fn validate_batch_relative_path(path: &str) -> Result<(), String> {
    if path.is_empty()
        || path.contains('\0')
        || path
            .chars()
            .any(|character| matches!(character, '\\' | ':'))
        || path
            .split('/')
            .any(|part| part.is_empty() || matches!(part, "." | ".."))
    {
        return Err(format!("批次相对路径无效: {path}"));
    }
    Ok(())
}

async fn validate_remote_batch_destination(sftp: &SftpSession, path: &str) -> Result<(), String> {
    validate_remote_drop_destination(path)?;
    let metadata = sftp
        .symlink_metadata(path.trim().to_string())
        .await
        .map_err(|error| format!("SFTP 读取远端目标目录失败 {}: {error}", path.trim()))?;
    if !metadata.is_dir() || metadata.is_symlink() {
        return Err(format!("远端批次目标不是普通目录: {}", path.trim()));
    }
    Ok(())
}

fn batch_destination_path(
    remote_destination: &str,
    local_destination: Option<&Path>,
    relative: &str,
    destination_remote: bool,
) -> Result<String, String> {
    if destination_remote {
        Ok(remote_join_path(remote_destination, relative))
    } else {
        let destination = local_destination.ok_or_else(|| "本地批次目标目录不可用".to_string())?;
        Ok(destination.join(Path::new(relative)).display().to_string())
    }
}

async fn batch_target_kind(
    sftp: Option<&SftpSession>,
    path: &str,
    remote: bool,
) -> Result<BatchTargetKind, String> {
    if remote {
        let sftp = sftp.ok_or_else(|| "远端目标检查缺少 SFTP session".to_string())?;
        let Ok(metadata) = sftp.symlink_metadata(path.to_string()).await else {
            return Ok(BatchTargetKind::Missing);
        };
        Ok(if metadata.is_symlink() {
            BatchTargetKind::Other
        } else if metadata.is_dir() {
            BatchTargetKind::Directory
        } else if metadata.is_regular() {
            BatchTargetKind::File
        } else {
            BatchTargetKind::Other
        })
    } else {
        match fs::symlink_metadata(path) {
            Ok(metadata) if metadata.file_type().is_symlink() => Ok(BatchTargetKind::Other),
            Ok(metadata) if metadata.is_dir() => Ok(BatchTargetKind::Directory),
            Ok(metadata) if metadata.is_file() => Ok(BatchTargetKind::File),
            Ok(_) => Ok(BatchTargetKind::Other),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                Ok(BatchTargetKind::Missing)
            }
            Err(error) => Err(format!("读取本地批次目标失败 {path}: {error}")),
        }
    }
}

fn numbered_batch_relative_path(path: &str, suffix: u32) -> Result<String, String> {
    validate_batch_relative_path(path)?;
    let (parent, name) = path.rsplit_once('/').unwrap_or(("", path));
    let (stem, extension) = name
        .rsplit_once('.')
        .filter(|(stem, extension)| !stem.is_empty() && !extension.is_empty())
        .map_or((name, ""), |parts| parts);
    let renamed = if extension.is_empty() {
        format!("{stem} ({suffix})")
    } else {
        format!("{stem} ({suffix}).{extension}")
    };
    Ok(if parent.is_empty() {
        renamed
    } else {
        format!("{parent}/{renamed}")
    })
}

fn batch_path_depth(path: &str) -> usize {
    path.split(['/', '\\'])
        .filter(|part| !part.is_empty())
        .count()
}

async fn apply_external_drop_conflicts(
    plan: &mut ExternalDropPlan,
    sftp: Option<&SftpSession>,
    destination: &str,
    local_destination: Option<&Path>,
    remote: bool,
    policy: TransferConflictPolicy,
) -> Result<(), String> {
    for relative in &plan.directories {
        let relative = external_relative_remote_path(relative)?;
        let target = batch_destination_path(destination, local_destination, &relative, remote)?;
        match batch_target_kind(sftp, &target, remote).await? {
            BatchTargetKind::Missing | BatchTargetKind::Directory => {}
            BatchTargetKind::File | BatchTargetKind::Other => {
                return Err(format!("目标目录路径已被非目录占用: {target}"));
            }
        }
    }

    let mut prepared = Vec::with_capacity(plan.files.len());
    let mut reserved = HashSet::new();
    let mut total_bytes = 0_u64;
    for mut file in std::mem::take(&mut plan.files) {
        let original_relative = external_relative_remote_path(&file.relative)?;
        let mut relative = original_relative.clone();
        let mut target = batch_destination_path(destination, local_destination, &relative, remote)?;
        let kind = batch_target_kind(sftp, &target, remote).await?;
        let conflict = kind != BatchTargetKind::Missing || !reserved.insert(target.clone());
        if conflict {
            match policy {
                TransferConflictPolicy::Fail => {
                    return Err(format!("目标文件已存在或批次内冲突: {target}"));
                }
                TransferConflictPolicy::Skip => {
                    plan.skipped.push(format!(
                        "{} (destination exists: {target})",
                        file.source.display()
                    ));
                    continue;
                }
                TransferConflictPolicy::Overwrite => {
                    if !matches!(kind, BatchTargetKind::File | BatchTargetKind::Missing) {
                        return Err(format!("拒绝用文件覆盖非普通文件目标: {target}"));
                    }
                    reserved.insert(target.clone());
                }
                TransferConflictPolicy::Rename => {
                    let mut renamed = None;
                    for suffix in 1..=10_000_u32 {
                        let candidate_relative =
                            numbered_batch_relative_path(&original_relative, suffix)?;
                        let candidate = batch_destination_path(
                            destination,
                            local_destination,
                            &candidate_relative,
                            remote,
                        )?;
                        if !reserved.contains(&candidate)
                            && batch_target_kind(sftp, &candidate, remote).await?
                                == BatchTargetKind::Missing
                        {
                            renamed = Some((candidate_relative, candidate));
                            break;
                        }
                    }
                    let (candidate_relative, candidate) =
                        renamed.ok_or_else(|| format!("无法为冲突目标生成可用名称: {target}"))?;
                    relative = candidate_relative;
                    target = candidate;
                    reserved.insert(target);
                    file.relative = PathBuf::from(relative);
                }
            }
        }
        let size = fs::metadata(&file.source)
            .map_err(|error| format!("读取拖放源文件失败 {}: {error}", file.source.display()))?
            .len();
        total_bytes = total_bytes
            .checked_add(size)
            .ok_or_else(|| "拖放批次总大小溢出".to_string())?;
        prepared.push(file);
    }
    plan.files = prepared;
    plan.total_bytes = total_bytes;
    Ok(())
}

async fn start_external_drop_inner(
    state: &AppState,
    request: StartExternalDropRequest,
) -> Result<ExternalDropResult, String> {
    {
        let store = state.store.lock().map_err(|error| error.to_string())?;
        if store.profile(&request.session_id).is_none() {
            return Err(format!("unknown session: {}", request.session_id));
        }
    }

    let local_destination = if request.remote {
        validate_remote_drop_destination(&request.destination)?;
        None
    } else {
        Some(validate_local_drop_destination(&request.destination)?)
    };
    let mut plan = plan_external_drop(&request.paths, local_destination.as_deref())?;

    if request.remote {
        if !plan.directories.is_empty() || !plan.files.is_empty() {
            let handle = ssh_handle_for_transfer(state, &request.session_id)?;
            let sftp = open_sftp_session(handle).await?;
            let result = async {
                apply_external_drop_conflicts(
                    &mut plan,
                    Some(&sftp),
                    request.destination.trim(),
                    None,
                    true,
                    request.conflict_policy,
                )
                .await?;
                sftp_create_dir_all(&sftp, request.destination.trim()).await?;
                for relative in &plan.directories {
                    let target = remote_join_path(
                        request.destination.trim(),
                        &external_relative_remote_path(relative)?,
                    );
                    sftp_create_dir_all(&sftp, &target).await?;
                }
                Ok::<(), String>(())
            }
            .await;
            let _ = sftp.close().await;
            result?;
        }
    } else if let Some(destination) = &local_destination {
        apply_external_drop_conflicts(
            &mut plan,
            None,
            &destination.display().to_string(),
            Some(destination),
            false,
            request.conflict_policy,
        )
        .await?;
        for relative in &plan.directories {
            let target = destination.join(relative);
            fs::create_dir_all(&target)
                .map_err(|error| format!("创建拖放目标目录失败 {}: {error}", target.display()))?;
        }
    }

    let directories_prepared = plan.directories.len();
    let total_bytes = plan.total_bytes;
    let skipped = plan.skipped;
    let mut tasks = Vec::with_capacity(plan.files.len());
    for file in plan.files {
        let source = file
            .source
            .to_str()
            .ok_or_else(|| format!("拖放源路径不是有效 Unicode: {}", file.source.display()))?
            .to_string();
        let destination = if request.remote {
            format!(
                "remote:{}",
                remote_join_path(
                    request.destination.trim(),
                    &external_relative_remote_path(&file.relative)?,
                )
            )
        } else {
            local_destination
                .as_ref()
                .expect("local drop destination must be available")
                .join(&file.relative)
                .display()
                .to_string()
        };
        tasks.push(
            start_transfer_inner(
                state,
                StartTransferRequest {
                    session_id: request.session_id.clone(),
                    protocol: TransferProtocol::Sftp,
                    source,
                    destination,
                },
            )
            .await?,
        );
    }

    Ok(ExternalDropResult {
        tasks,
        directories_prepared,
        skipped,
        total_bytes,
    })
}

fn validate_remote_drop_destination(path: &str) -> Result<(), String> {
    let path = path.trim();
    if path.is_empty() || path.contains('\0') {
        return Err("远端拖放目标路径不能为空或包含 NUL".to_string());
    }
    Ok(())
}

fn validate_local_drop_destination(path: &str) -> Result<PathBuf, String> {
    if path.trim().is_empty() || path.contains('\0') {
        return Err("本地拖放目标路径不能为空或包含 NUL".to_string());
    }
    let destination = expand_identity_path(path.trim());
    let metadata = fs::metadata(&destination).map_err(|error| {
        format!(
            "读取本地拖放目标目录失败 {}: {error}",
            destination.display()
        )
    })?;
    if !metadata.is_dir() {
        return Err(format!("本地拖放目标不是目录: {}", destination.display()));
    }
    destination
        .canonicalize()
        .map_err(|error| format!("解析本地拖放目标失败 {}: {error}", destination.display()))
}

fn plan_external_drop(
    paths: &[String],
    local_destination: Option<&Path>,
) -> Result<ExternalDropPlan, String> {
    if paths.is_empty() {
        return Err("拖放批次没有源路径".to_string());
    }
    if paths.len() > MAX_EXTERNAL_DROP_ROOTS {
        return Err(format!(
            "一次最多拖放 {MAX_EXTERNAL_DROP_ROOTS} 个顶层路径，当前为 {} 个",
            paths.len()
        ));
    }

    let mut candidates = Vec::with_capacity(paths.len());
    let mut skipped = Vec::new();
    for raw_path in paths {
        let trimmed = raw_path.trim();
        if trimmed.is_empty() || trimmed.contains('\0') {
            return Err("拖放源路径不能为空或包含 NUL".to_string());
        }
        let source = expand_identity_path(trimmed);
        let metadata = fs::symlink_metadata(&source)
            .map_err(|error| format!("读取拖放源路径失败 {}: {error}", source.display()))?;
        if metadata.file_type().is_symlink() {
            skipped.push(format!("{} (symbolic link)", source.display()));
            continue;
        }
        if !metadata.is_dir() && !metadata.is_file() {
            skipped.push(format!(
                "{} (not a regular file or directory)",
                source.display()
            ));
            continue;
        }
        let source = source
            .canonicalize()
            .map_err(|error| format!("解析拖放源路径失败 {}: {error}", source.display()))?;
        candidates.push(ExternalDropRoot {
            path: source,
            is_dir: metadata.is_dir(),
        });
    }
    candidates.sort_by(|left, right| {
        left.path
            .components()
            .count()
            .cmp(&right.path.components().count())
            .then_with(|| left.path.cmp(&right.path))
    });

    let mut roots: Vec<ExternalDropRoot> = Vec::with_capacity(candidates.len());
    for candidate in candidates {
        if roots.iter().any(|root| {
            candidate.path == root.path || (root.is_dir && candidate.path.starts_with(&root.path))
        }) {
            skipped.push(format!("{} (already included)", candidate.path.display()));
            continue;
        }
        if candidate.is_dir
            && local_destination.is_some_and(|destination| destination.starts_with(&candidate.path))
        {
            return Err(format!(
                "拒绝把目录复制到自身或其子目录: {}",
                candidate.path.display()
            ));
        }
        if let Some(destination) = local_destination {
            if let Some(name) = candidate.path.file_name() {
                let target = destination.join(name);
                if target.exists()
                    && target
                        .canonicalize()
                        .is_ok_and(|target| target == candidate.path)
                {
                    return Err(format!(
                        "拒绝把路径复制到自身: {}",
                        candidate.path.display()
                    ));
                }
            }
        }
        roots.push(candidate);
    }

    let mut plan = ExternalDropPlan {
        skipped,
        ..ExternalDropPlan::default()
    };
    let mut visited = 0_usize;
    for root in roots {
        let Some(root_name) = root.path.file_name().map(|name| name.to_os_string()) else {
            return Err(format!("拒绝拖放文件系统根路径: {}", root.path.display()));
        };
        if root_name.to_str().is_none() {
            plan.skipped.push(format!(
                "{} (path is not valid Unicode)",
                root.path.display()
            ));
            continue;
        }
        let mut stack = vec![(root.path, PathBuf::from(root_name))];
        while let Some((source, relative)) = stack.pop() {
            visited += 1;
            if visited > MAX_EXTERNAL_DROP_ENTRIES {
                return Err(format!(
                    "拖放目录超过 {MAX_EXTERNAL_DROP_ENTRIES} 个条目，请缩小批次"
                ));
            }
            if external_relative_remote_path(&relative).is_err() {
                plan.skipped
                    .push(format!("{} (path is not valid Unicode)", source.display()));
                continue;
            }
            let metadata = fs::symlink_metadata(&source)
                .map_err(|error| format!("读取拖放目录项失败 {}: {error}", source.display()))?;
            if metadata.file_type().is_symlink() {
                plan.skipped
                    .push(format!("{} (symbolic link)", source.display()));
                continue;
            }
            if metadata.is_dir() {
                plan.directories.push(relative.clone());
                let mut children = fs::read_dir(&source)
                    .map_err(|error| format!("读取拖放目录失败 {}: {error}", source.display()))?
                    .collect::<Result<Vec<_>, _>>()
                    .map_err(|error| format!("读取拖放目录项失败 {}: {error}", source.display()))?;
                children.sort_by_key(|entry| entry.file_name());
                for child in children.into_iter().rev() {
                    stack.push((child.path(), relative.join(child.file_name())));
                }
            } else if metadata.is_file() {
                if let Some(destination) = local_destination {
                    let target = destination.join(&relative);
                    if target.exists() && target.canonicalize().is_ok_and(|target| target == source)
                    {
                        return Err(format!("拒绝把文件复制到自身: {}", source.display()));
                    }
                }
                plan.total_bytes = plan
                    .total_bytes
                    .checked_add(metadata.len())
                    .ok_or_else(|| "拖放批次总大小溢出".to_string())?;
                if plan.files.len() >= MAX_EXTERNAL_DROP_FILES {
                    return Err(format!(
                        "一次最多拖放 {MAX_EXTERNAL_DROP_FILES} 个文件，请缩小批次"
                    ));
                }
                plan.files.push(ExternalDropFile { source, relative });
            } else {
                plan.skipped.push(format!(
                    "{} (not a regular file or directory)",
                    source.display()
                ));
            }
        }
    }

    plan.directories.sort_by(|left, right| {
        left.components()
            .count()
            .cmp(&right.components().count())
            .then_with(|| left.cmp(right))
    });
    if let Some(conflict) = plan
        .directories
        .windows(2)
        .find(|pair| pair[0] == pair[1])
        .map(|pair| &pair[0])
    {
        return Err(format!(
            "拖放批次包含冲突的目标目录: {}",
            conflict.display()
        ));
    }
    plan.files
        .sort_by(|left, right| left.relative.cmp(&right.relative));
    let directory_targets = plan.directories.iter().cloned().collect::<HashSet<_>>();
    let mut file_targets = HashSet::new();
    for file in &plan.files {
        if directory_targets.contains(&file.relative) || !file_targets.insert(file.relative.clone())
        {
            return Err(format!(
                "拖放批次包含冲突的目标路径: {}",
                file.relative.display()
            ));
        }
    }
    plan.skipped.sort();
    plan.skipped.dedup();
    Ok(plan)
}

fn external_relative_remote_path(path: &Path) -> Result<String, String> {
    let mut remote = String::new();
    for component in path.components() {
        let std::path::Component::Normal(part) = component else {
            return Err(format!("拖放相对路径无效: {}", path.display()));
        };
        let part = part
            .to_str()
            .ok_or_else(|| format!("拖放路径不是有效 Unicode: {}", path.display()))?;
        remote = remote_join_path(&remote, part);
    }
    if remote.is_empty() {
        Err("拖放相对路径不能为空".to_string())
    } else {
        Ok(remote)
    }
}

async fn list_files_inner(
    state: &AppState,
    request: ListFilesRequest,
) -> Result<Vec<FileEntry>, String> {
    if request.remote {
        let session_id = request
            .session_id
            .as_deref()
            .ok_or_else(|| "remote file list requires sessionId".to_string())?;
        let handle = ssh_handle_for_transfer(state, session_id)?;
        list_remote_files(handle, &request.path).await
    } else {
        list_local_files(&request.path)
    }
}

async fn file_properties_inner(
    state: &AppState,
    request: FilePropertiesRequest,
) -> Result<FileProperties, String> {
    if request.path.trim().is_empty() {
        return Err("属性路径不能为空".to_string());
    }
    if request.remote {
        let session_id = request
            .session_id
            .as_deref()
            .ok_or_else(|| "remote file properties require sessionId".to_string())?;
        let handle = ssh_handle_for_transfer(state, session_id)?;
        let sftp = open_sftp_session(handle).await?;
        let result = remote_file_properties(&sftp, request.path.trim()).await;
        let _ = sftp.close().await;
        result
    } else {
        local_file_properties(request.path.trim())
    }
}

async fn file_operation_inner(
    state: &AppState,
    request: FileOperationRequest,
    operation: FileOperation,
) -> Result<(), String> {
    if request.remote {
        let session_id = request
            .session_id
            .as_deref()
            .ok_or_else(|| "remote file operation requires sessionId".to_string())?;
        let handle = ssh_handle_for_transfer(state, session_id)?;
        let sftp = open_sftp_session(handle).await?;
        let result = match operation {
            FileOperation::CreateDirectory => sftp_create_dir_all(&sftp, &request.path).await,
            FileOperation::Delete => sftp_remove_recursive(&sftp, &request.path).await,
        };
        let _ = sftp.close().await;
        result
    } else {
        match operation {
            FileOperation::CreateDirectory => {
                let path = PathBuf::from(&request.path);
                fs::create_dir_all(&path)
                    .map_err(|error| format!("创建本地目录失败 {}: {error}", path.display()))
            }
            FileOperation::Delete => {
                let path = validate_local_mutating_path(&request.path)?;
                let metadata = fs::symlink_metadata(&path)
                    .map_err(|error| format!("读取本地路径失败 {}: {error}", path.display()))?;
                if metadata.is_dir() {
                    fs::remove_dir_all(&path)
                        .map_err(|error| format!("删除本地目录失败 {}: {error}", path.display()))
                } else {
                    fs::remove_file(&path)
                        .map_err(|error| format!("删除本地文件失败 {}: {error}", path.display()))
                }
            }
        }
    }
}

async fn rename_path_inner(state: &AppState, request: RenamePathRequest) -> Result<(), String> {
    if request.old_path.trim().is_empty() || request.new_path.trim().is_empty() {
        return Err("重命名路径不能为空".to_string());
    }
    if request.remote {
        let session_id = request
            .session_id
            .as_deref()
            .ok_or_else(|| "remote rename requires sessionId".to_string())?;
        let handle = ssh_handle_for_transfer(state, session_id)?;
        let sftp = open_sftp_session(handle).await?;
        let result = sftp
            .rename(request.old_path.clone(), request.new_path.clone())
            .await
            .map_err(|error| {
                format!(
                    "SFTP 重命名失败 {} -> {}: {error}",
                    request.old_path, request.new_path
                )
            });
        let _ = sftp.close().await;
        result
    } else {
        let old_path = validate_local_mutating_path(&request.old_path)?;
        let new_path = validate_local_mutating_path(&request.new_path)?;
        fs::rename(&old_path, &new_path).map_err(|error| {
            format!(
                "本地重命名失败 {} -> {}: {error}",
                old_path.display(),
                new_path.display()
            )
        })
    }
}

async fn chmod_path_inner(state: &AppState, request: ChmodPathRequest) -> Result<(), String> {
    if request.path.trim().is_empty() {
        return Err("权限路径不能为空".to_string());
    }
    if request.mode > 0o7777 {
        return Err("权限模式必须是 0000-7777 八进制范围".to_string());
    }
    if request.remote {
        let session_id = request
            .session_id
            .as_deref()
            .ok_or_else(|| "remote chmod requires sessionId".to_string())?;
        let handle = ssh_handle_for_transfer(state, session_id)?;
        let sftp = open_sftp_session(handle).await?;
        let mut metadata = sftp
            .symlink_metadata(request.path.clone())
            .await
            .map_err(|error| format!("SFTP 读取权限失败 {}: {error}", request.path))?;
        let file_type_bits = metadata.permissions.unwrap_or(0) & 0o170000;
        metadata.permissions = Some(file_type_bits | request.mode);
        let result = sftp
            .set_metadata(request.path.clone(), metadata)
            .await
            .map_err(|error| format!("SFTP 设置权限失败 {}: {error}", request.path));
        let _ = sftp.close().await;
        result
    } else {
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let path = PathBuf::from(&request.path);
            let mut permissions = fs::metadata(&path)
                .map_err(|error| format!("读取本地权限失败 {}: {error}", path.display()))?
                .permissions();
            permissions.set_mode(request.mode);
            fs::set_permissions(&path, permissions)
                .map_err(|error| format!("设置本地权限失败 {}: {error}", path.display()))
        }
        #[cfg(not(unix))]
        {
            let _ = state;
            Err("当前平台不支持本地 chmod".to_string())
        }
    }
}

async fn list_tmux_state_inner(state: &AppState, session_id: &str) -> Result<TmuxState, String> {
    let handle = ssh_handle_for_transfer(state, session_id)?;
    let sessions_output = exec_ssh_command_capture(
        Arc::clone(&handle),
        "tmux list-sessions -F '#{session_name}\t#{session_windows}\t#{session_attached}\t#{session_created}' 2>/dev/null || true",
        Duration::from_secs(8),
    )
    .await?;
    let windows_output = exec_ssh_command_capture(
        Arc::clone(&handle),
        "tmux list-windows -a -F '#{session_name}\t#{window_index}\t#{window_id}\t#{window_name}\t#{window_panes}\t#{window_active}' 2>/dev/null || true",
        Duration::from_secs(8),
    )
    .await?;
    let panes_output = exec_ssh_command_capture(
        handle,
        "tmux list-panes -a -F '#{session_name}\t#{window_index}\t#{pane_index}\t#{pane_id}\t#{pane_active}\t#{pane_current_command}\t#{pane_title}\t#{pane_synchronized}' 2>/dev/null || true",
        Duration::from_secs(8),
    )
    .await?;

    let sessions = sessions_output
        .lines()
        .filter_map(parse_tmux_session)
        .collect::<Vec<_>>();
    let mut windows = windows_output
        .lines()
        .filter_map(parse_tmux_window)
        .collect::<Vec<_>>();
    let panes = panes_output
        .lines()
        .filter_map(parse_tmux_pane)
        .collect::<Vec<_>>();
    for window in &mut windows {
        let matching = panes
            .iter()
            .filter(|pane| {
                pane.session == window.session && pane.window_index == window.window_index
            })
            .collect::<Vec<_>>();
        window.synchronized = !matching.is_empty() && matching.iter().all(|pane| pane.synchronized);
    }
    Ok(TmuxState {
        sessions,
        windows,
        panes,
    })
}

async fn set_tmux_pane_sync_inner(
    state: &AppState,
    session_id: &str,
    target: &str,
    enabled: bool,
) -> Result<TmuxState, String> {
    let handle = ssh_handle_for_transfer(state, session_id)?;
    let command = tmux_pane_sync_command(target, enabled)?;
    exec_ssh_command_capture(handle, &command, Duration::from_secs(8)).await?;
    if let Ok(mut store) = state.store.lock() {
        store.record_system_event(
            session_id,
            format!(
                "PortMate: tmux pane synchronization {} ({})",
                if enabled { "enabled" } else { "disabled" },
                normalize_tmux_target(target)?
            ),
        );
    }
    list_tmux_state_inner(state, session_id).await
}

async fn mutate_tmux_inner(
    state: &AppState,
    request: TmuxMutationRequest,
) -> Result<TmuxState, String> {
    let command = tmux_mutation_command(&request)?;
    let handle = ssh_handle_for_transfer(state, &request.session_id)?;
    exec_ssh_command_capture(handle, &command, Duration::from_secs(8)).await?;
    if let Ok(mut store) = state.store.lock() {
        store.record_system_event(
            &request.session_id,
            format!(
                "PortMate: tmux {} ({})",
                tmux_mutation_label(request.action),
                tmux_mutation_event_scope(&request)?
            ),
        );
    }
    list_tmux_state_inner(state, &request.session_id).await
}

fn normalize_tmux_target(target: &str) -> Result<&str, String> {
    let target = target.trim();
    if target.is_empty() {
        return Err("Tmux target 不能为空".to_string());
    }
    if target.chars().count() > 256 {
        return Err("Tmux target 不能超过 256 个字符".to_string());
    }
    if target.chars().any(char::is_control) {
        return Err("Tmux target 不能包含控制字符".to_string());
    }
    Ok(target)
}

fn normalize_tmux_name(name: &str) -> Result<&str, String> {
    let name = name.trim();
    if name.is_empty() {
        return Err("Tmux 名称不能为空".to_string());
    }
    if name.chars().count() > 128 {
        return Err("Tmux 名称不能超过 128 个字符".to_string());
    }
    if name.chars().any(char::is_control) {
        return Err("Tmux 名称不能包含控制字符".to_string());
    }
    Ok(name)
}

fn tmux_attach_command(target: &str) -> Result<String, String> {
    let target = normalize_tmux_target(target)?;
    let target = shell_quote(target);
    Ok(format!(
        "tmux switch-client -t {target} || tmux attach -t {target} || tmux new-session -A -s {target}\r"
    ))
}

fn tmux_pane_sync_command(target: &str, enabled: bool) -> Result<String, String> {
    let target = normalize_tmux_target(target)?;
    Ok(format!(
        "tmux set-option -w -t {} synchronize-panes {}",
        shell_quote(target),
        if enabled { "on" } else { "off" }
    ))
}

fn tmux_mutation_command(request: &TmuxMutationRequest) -> Result<String, String> {
    let target = shell_quote(normalize_tmux_target(&request.target)?);
    let name = request
        .name
        .as_deref()
        .map(normalize_tmux_name)
        .transpose()?;
    match request.action {
        TmuxMutationAction::RenameSession => Ok(format!(
            "tmux rename-session -t {target} {}",
            shell_quote(name.ok_or_else(|| "重命名 session 需要新名称".to_string())?)
        )),
        TmuxMutationAction::KillSession => Ok(format!("tmux kill-session -t {target}")),
        TmuxMutationAction::NewWindow => Ok(match name {
            Some(name) => format!("tmux new-window -t {target} -n {}", shell_quote(name)),
            None => format!("tmux new-window -t {target}"),
        }),
        TmuxMutationAction::RenameWindow => Ok(format!(
            "tmux rename-window -t {target} {}",
            shell_quote(name.ok_or_else(|| "重命名 window 需要新名称".to_string())?)
        )),
        TmuxMutationAction::KillWindow => Ok(format!("tmux kill-window -t {target}")),
        TmuxMutationAction::KillPane => Ok(format!("tmux kill-pane -t {target}")),
        TmuxMutationAction::SelectPane => Ok(format!("tmux select-pane -t {target}")),
        TmuxMutationAction::BreakPane => Ok(format!("tmux break-pane -d -s {target}")),
        TmuxMutationAction::MovePaneHorizontal | TmuxMutationAction::MovePaneVertical => {
            let destination = shell_quote(normalize_tmux_target(
                request
                    .destination
                    .as_deref()
                    .ok_or_else(|| "跨 window 移动 pane 需要目标 window".to_string())?,
            )?);
            Ok(format!(
                "tmux move-pane -d {} -s {target} -t {destination}",
                if request.action == TmuxMutationAction::MovePaneHorizontal {
                    "-h"
                } else {
                    "-v"
                }
            ))
        }
        TmuxMutationAction::SplitPaneHorizontal => Ok(format!("tmux split-window -h -t {target}")),
        TmuxMutationAction::SplitPaneVertical => Ok(format!("tmux split-window -v -t {target}")),
        TmuxMutationAction::SwapPanePrevious => Ok(format!("tmux swap-pane -t {target} -U")),
        TmuxMutationAction::SwapPaneNext => Ok(format!("tmux swap-pane -t {target} -D")),
        TmuxMutationAction::ResizePaneLeft => Ok(format!(
            "tmux resize-pane -t {target} -L {}",
            normalize_tmux_resize_amount(request.amount)?
        )),
        TmuxMutationAction::ResizePaneRight => Ok(format!(
            "tmux resize-pane -t {target} -R {}",
            normalize_tmux_resize_amount(request.amount)?
        )),
        TmuxMutationAction::ResizePaneUp => Ok(format!(
            "tmux resize-pane -t {target} -U {}",
            normalize_tmux_resize_amount(request.amount)?
        )),
        TmuxMutationAction::ResizePaneDown => Ok(format!(
            "tmux resize-pane -t {target} -D {}",
            normalize_tmux_resize_amount(request.amount)?
        )),
        TmuxMutationAction::SelectLayout => Ok(format!(
            "tmux select-layout -t {target} {}",
            tmux_window_layout_argument(
                request
                    .layout
                    .ok_or_else(|| "切换 window 布局需要 layout".to_string())?
            )
        )),
    }
}

fn tmux_mutation_event_scope(request: &TmuxMutationRequest) -> Result<String, String> {
    let target = normalize_tmux_target(&request.target)?;
    match request.action {
        TmuxMutationAction::MovePaneHorizontal | TmuxMutationAction::MovePaneVertical => {
            Ok(format!(
                "{target} -> {}",
                normalize_tmux_target(
                    request
                        .destination
                        .as_deref()
                        .ok_or_else(|| "跨 window 移动 pane 需要目标 window".to_string())?
                )?
            ))
        }
        _ => Ok(target.to_string()),
    }
}

fn normalize_tmux_resize_amount(amount: Option<u16>) -> Result<u16, String> {
    let amount = amount.unwrap_or(5);
    if !(1..=100).contains(&amount) {
        return Err("Tmux pane 调整步长必须在 1..=100 之间".to_string());
    }
    Ok(amount)
}

fn tmux_window_layout_argument(layout: TmuxWindowLayout) -> &'static str {
    match layout {
        TmuxWindowLayout::EvenHorizontal => "even-horizontal",
        TmuxWindowLayout::EvenVertical => "even-vertical",
        TmuxWindowLayout::MainHorizontal => "main-horizontal",
        TmuxWindowLayout::MainVertical => "main-vertical",
        TmuxWindowLayout::Tiled => "tiled",
    }
}

fn tmux_mutation_label(action: TmuxMutationAction) -> &'static str {
    match action {
        TmuxMutationAction::RenameSession => "session renamed",
        TmuxMutationAction::KillSession => "session closed",
        TmuxMutationAction::NewWindow => "window created",
        TmuxMutationAction::RenameWindow => "window renamed",
        TmuxMutationAction::KillWindow => "window closed",
        TmuxMutationAction::KillPane => "pane closed",
        TmuxMutationAction::SelectPane => "pane selected",
        TmuxMutationAction::BreakPane => "pane broken into window",
        TmuxMutationAction::MovePaneHorizontal => "pane moved horizontally",
        TmuxMutationAction::MovePaneVertical => "pane moved vertically",
        TmuxMutationAction::SplitPaneHorizontal => "pane split horizontally",
        TmuxMutationAction::SplitPaneVertical => "pane split vertically",
        TmuxMutationAction::SwapPanePrevious => "pane swapped with previous",
        TmuxMutationAction::SwapPaneNext => "pane swapped with next",
        TmuxMutationAction::ResizePaneLeft => "pane resized left",
        TmuxMutationAction::ResizePaneRight => "pane resized right",
        TmuxMutationAction::ResizePaneUp => "pane resized up",
        TmuxMutationAction::ResizePaneDown => "pane resized down",
        TmuxMutationAction::SelectLayout => "window layout selected",
    }
}

fn parse_tmux_session(line: &str) -> Option<TmuxSessionInfo> {
    let mut parts = line.split('\t');
    let name = parts.next()?.to_string();
    if name.is_empty() {
        return None;
    }
    let windows = parts
        .next()
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or_default();
    let attached = parts
        .next()
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or_default();
    let created = parts
        .next()
        .and_then(|value| value.parse::<i64>().ok())
        .and_then(|timestamp| chrono::DateTime::<Utc>::from_timestamp(timestamp, 0))
        .map(|value| value.to_rfc3339());
    Some(TmuxSessionInfo {
        name,
        windows,
        attached,
        created,
    })
}

fn parse_tmux_window(line: &str) -> Option<TmuxWindowInfo> {
    let mut parts = line.split('\t');
    let session = parts.next()?.to_string();
    if session.is_empty() {
        return None;
    }
    Some(TmuxWindowInfo {
        session,
        window_index: parts
            .next()
            .and_then(|value| value.parse::<u32>().ok())
            .unwrap_or_default(),
        window_id: parts.next().unwrap_or_default().to_string(),
        name: parts.next().unwrap_or_default().to_string(),
        panes: parts
            .next()
            .and_then(|value| value.parse::<u32>().ok())
            .unwrap_or_default(),
        active: parts.next().unwrap_or_default() == "1",
        synchronized: false,
    })
}

fn parse_tmux_pane(line: &str) -> Option<TmuxPaneInfo> {
    let mut parts = line.split('\t');
    let session = parts.next()?.to_string();
    if session.is_empty() {
        return None;
    }
    Some(TmuxPaneInfo {
        session,
        window_index: parts
            .next()
            .and_then(|value| value.parse::<u32>().ok())
            .unwrap_or_default(),
        pane_index: parts
            .next()
            .and_then(|value| value.parse::<u32>().ok())
            .unwrap_or_default(),
        pane_id: parts.next().unwrap_or_default().to_string(),
        active: parts.next().unwrap_or_default() == "1",
        command: parts.next().unwrap_or_default().to_string(),
        title: parts.next().unwrap_or_default().to_string(),
        synchronized: parts.next().unwrap_or_default() == "1",
    })
}

fn list_local_files(path: &str) -> Result<Vec<FileEntry>, String> {
    let path = expand_identity_path(if path.trim().is_empty() {
        "."
    } else {
        path.trim()
    });
    let mut entries = Vec::new();
    for entry in fs::read_dir(&path)
        .map_err(|error| format!("读取本地目录失败 {}: {error}", path.display()))?
    {
        let entry = entry.map_err(|error| format!("读取本地目录项失败: {error}"))?;
        let metadata = entry
            .metadata()
            .map_err(|error| format!("读取本地文件元数据失败: {error}"))?;
        let modified = metadata
            .modified()
            .ok()
            .and_then(|time| time.duration_since(std::time::UNIX_EPOCH).ok())
            .map(|duration| {
                chrono::DateTime::<Utc>::from(std::time::UNIX_EPOCH + duration).to_rfc3339()
            });
        entries.push(FileEntry {
            name: entry.file_name().to_string_lossy().to_string(),
            path: entry.path().display().to_string(),
            is_dir: metadata.is_dir(),
            size: if metadata.is_file() {
                metadata.len()
            } else {
                0
            },
            modified,
        });
    }
    sort_file_entries(&mut entries);
    Ok(entries)
}

fn local_file_properties(path: &str) -> Result<FileProperties, String> {
    let path = expand_identity_path(path);
    let metadata = fs::symlink_metadata(&path)
        .map_err(|error| format!("读取本地路径属性失败 {}: {error}", path.display()))?;
    let file_type = metadata.file_type();
    #[cfg(unix)]
    let permissions = {
        use std::os::unix::fs::PermissionsExt;
        Some(metadata.permissions().mode())
    };
    #[cfg(not(unix))]
    let permissions = None;
    Ok(FileProperties {
        name: path
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or_else(|| path.to_str().unwrap_or(""))
            .to_string(),
        path: path.display().to_string(),
        remote: false,
        kind: file_kind_label(
            metadata.is_dir(),
            metadata.is_file(),
            file_type.is_symlink(),
        ),
        is_dir: metadata.is_dir(),
        is_file: metadata.is_file(),
        is_symlink: file_type.is_symlink(),
        size: if metadata.is_file() {
            metadata.len()
        } else {
            0
        },
        permissions,
        modified: metadata.modified().ok().and_then(system_time_to_rfc3339),
        accessed: metadata.accessed().ok().and_then(system_time_to_rfc3339),
        created: metadata.created().ok().and_then(system_time_to_rfc3339),
    })
}

async fn list_remote_files(
    handle: Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>,
    path: &str,
) -> Result<Vec<FileEntry>, String> {
    let path = if path.trim().is_empty() {
        "."
    } else {
        path.trim()
    };
    let sftp = open_sftp_session(handle).await?;
    let result = list_remote_files_via_sftp(&sftp, path).await;
    let _ = sftp.close().await;
    result
}

async fn list_remote_files_via_sftp(
    sftp: &SftpSession,
    path: &str,
) -> Result<Vec<FileEntry>, String> {
    let mut entries = Vec::new();
    for entry in sftp
        .read_dir(path.to_string())
        .await
        .map_err(|error| format!("SFTP 读取远端目录失败 {path}: {error}"))?
    {
        let metadata = entry.metadata();
        let name = entry.file_name();
        let modified = metadata
            .mtime
            .and_then(|timestamp| chrono::DateTime::<Utc>::from_timestamp(timestamp.into(), 0))
            .map(|value| value.to_rfc3339());
        entries.push(FileEntry {
            path: remote_join_path(path, &name),
            name,
            is_dir: metadata.is_dir(),
            size: if metadata.is_regular() {
                metadata.len()
            } else {
                0
            },
            modified,
        });
    }
    sort_file_entries(&mut entries);
    Ok(entries)
}

async fn remote_file_properties(sftp: &SftpSession, path: &str) -> Result<FileProperties, String> {
    let metadata = sftp
        .symlink_metadata(path.to_string())
        .await
        .map_err(|error| format!("SFTP 读取远端属性失败 {path}: {error}"))?;
    let is_dir = metadata.is_dir();
    let is_file = metadata.is_regular();
    let is_symlink = metadata.is_symlink();
    Ok(FileProperties {
        name: remote_file_name(path),
        path: path.to_string(),
        remote: true,
        kind: file_kind_label(is_dir, is_file, is_symlink),
        is_dir,
        is_file,
        is_symlink,
        size: if is_file { metadata.len() } else { 0 },
        permissions: metadata.permissions,
        modified: metadata
            .mtime
            .and_then(|timestamp| chrono::DateTime::<Utc>::from_timestamp(timestamp.into(), 0))
            .map(|value| value.to_rfc3339()),
        accessed: None,
        created: None,
    })
}

fn file_kind_label(is_dir: bool, is_file: bool, is_symlink: bool) -> String {
    if is_symlink {
        "symlink"
    } else if is_dir {
        "directory"
    } else if is_file {
        "file"
    } else {
        "other"
    }
    .to_string()
}

fn system_time_to_rfc3339(time: std::time::SystemTime) -> Option<String> {
    time.duration_since(std::time::UNIX_EPOCH)
        .ok()
        .map(|duration| {
            chrono::DateTime::<Utc>::from(std::time::UNIX_EPOCH + duration).to_rfc3339()
        })
}

async fn sftp_remove_recursive(sftp: &SftpSession, path: &str) -> Result<(), String> {
    let path = validate_remote_delete_path(path)?;
    let mut stack = vec![(path.to_string(), false)];

    while let Some((current, visited)) = stack.pop() {
        let metadata = sftp
            .symlink_metadata(current.clone())
            .await
            .map_err(|error| format!("SFTP 读取远端路径失败 {current}: {error}"))?;
        let is_directory = metadata.is_dir() && !metadata.is_symlink();
        if is_directory && !visited {
            stack.push((current.clone(), true));
            let entries = sftp
                .read_dir(current.clone())
                .await
                .map_err(|error| format!("SFTP 读取远端目录失败 {current}: {error}"))?;
            for entry in entries {
                stack.push((remote_join_path(&current, &entry.file_name()), false));
            }
            continue;
        }

        if is_directory {
            sftp.remove_dir(current.clone())
                .await
                .map_err(|error| format!("SFTP 删除远端目录失败 {current}: {error}"))?;
        } else {
            sftp.remove_file(current.clone())
                .await
                .map_err(|error| format!("SFTP 删除远端文件失败 {current}: {error}"))?;
        }
    }

    Ok(())
}

fn validate_remote_delete_path(path: &str) -> Result<&str, String> {
    let path = path.trim();
    let trimmed = path.trim_end_matches('/');
    if path.is_empty()
        || trimmed.is_empty()
        || matches!(trimmed, "." | "~" | "/" | "//")
        || path.contains('\0')
    {
        return Err("拒绝删除空路径、根目录或当前目录".to_string());
    }
    Ok(path)
}

/// Guards local delete/rename endpoints against the two most catastrophic
/// fat-finger paths: an empty/`.`/`~` path, and a path that resolves to a
/// filesystem root or to the user's home directory itself.
fn validate_local_mutating_path(path: &str) -> Result<PathBuf, String> {
    let trimmed = path.trim();
    let trimmed_slashes = trimmed.trim_end_matches(['/', '\\']);
    if trimmed.is_empty()
        || trimmed_slashes.is_empty()
        || matches!(trimmed_slashes, "." | ".." | "~")
        || trimmed.contains('\0')
    {
        return Err("拒绝操作空路径、根目录或当前目录".to_string());
    }

    let candidate = expand_identity_path(trimmed);
    if candidate.parent().is_none() {
        return Err("拒绝操作文件系统根目录".to_string());
    }
    if let Some(home) = std::env::var_os("HOME").or_else(|| std::env::var_os("USERPROFILE")) {
        let home = PathBuf::from(home);
        let candidate_check = candidate
            .canonicalize()
            .unwrap_or_else(|_| candidate.clone());
        let home_check = home.canonicalize().unwrap_or(home);
        if candidate_check == home_check {
            return Err("拒绝操作用户主目录".to_string());
        }
    }
    Ok(candidate)
}

fn sort_file_entries(entries: &mut [FileEntry]) {
    entries.sort_by(|a, b| {
        b.is_dir
            .cmp(&a.is_dir)
            .then_with(|| a.name.to_lowercase().cmp(&b.name.to_lowercase()))
    });
}

async fn scp_upload(
    handle: Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>,
    local_source: &str,
    remote_destination: &str,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    let mut file =
        fs::File::open(local_source).map_err(|error| format!("读取本地文件失败: {error}"))?;
    let size = file
        .metadata()
        .map_err(|error| format!("读取本地文件元数据失败: {error}"))?
        .len();
    let file_name = Path::new(local_source)
        .file_name()
        .and_then(|value| value.to_str())
        .filter(|value| !value.is_empty())
        .unwrap_or("portmate-upload.bin");
    let command = scp_upload_command(remote_destination, file_name, size);
    let mut channel = {
        let handle = handle.lock().await;
        handle
            .channel_open_session()
            .await
            .map_err(|error| format!("SCP 打开 SSH channel 失败: {error}"))?
    };
    channel
        .exec(true, command)
        .await
        .map_err(|error| format!("SCP 启动远端接收失败: {error}"))?;

    let mut output = Vec::new();
    let mut stderr = Vec::new();
    let mut exit_status = None;
    let mut reported_total = None;
    let started = Instant::now();
    let mut copied = loop {
        if progress.cancel.load(Ordering::SeqCst) {
            let _ = channel.eof().await;
            let _ = channel.close().await;
            return Err(TRANSFER_CANCELLED_MESSAGE.to_string());
        }
        if started.elapsed() > Duration::from_secs(30) {
            let _ = channel.close().await;
            return Err("SCP upload 等待远端续传状态超时".to_string());
        }
        match tokio::time::timeout(Duration::from_millis(250), channel.wait()).await {
            Ok(Some(ChannelMsg::Data { data })) => {
                output.extend_from_slice(&data);
                let markers = remote_copy_markers(&output);
                if markers.total.is_some() && markers.total != reported_total {
                    let total = markers.total.unwrap_or_default();
                    progress.update(0, total).await?;
                    reported_total = Some(total);
                }
                if let Some(resume) = markers.resume {
                    let resume = resume.min(size);
                    progress.set_rate_baseline(resume);
                    if resume > 0 {
                        progress.update(resume, size).await?;
                    }
                    break resume;
                }
            }
            Ok(Some(ChannelMsg::ExtendedData { data, .. })) => stderr.extend_from_slice(&data),
            Ok(Some(ChannelMsg::ExitStatus { exit_status: code })) => exit_status = Some(code),
            Ok(Some(ChannelMsg::Eof | ChannelMsg::Close)) | Ok(None) => {
                return Err(format!(
                    "SCP upload remote closed before resume marker: {}{}",
                    String::from_utf8_lossy(&output),
                    String::from_utf8_lossy(&stderr)
                ));
            }
            Ok(Some(_)) => {}
            Err(_) => {}
        }
        if exit_status.is_some_and(|code| code != 0) {
            return Err(format!(
                "SCP upload remote returned non-zero before upload {:?}: {}",
                exit_status,
                String::from_utf8_lossy(&stderr)
            ));
        }
    };

    if copied < size {
        file.seek(std::io::SeekFrom::Start(copied))
            .map_err(|error| format!("SCP 定位本地续传偏移失败: {error}"))?;
    }
    let mut buffer = vec![0_u8; 64 * 1024];
    while copied < size {
        if progress.cancel.load(Ordering::SeqCst) {
            let _ = channel.eof().await;
            let _ = channel.close().await;
            return Err(TRANSFER_CANCELLED_MESSAGE.to_string());
        }
        let read = file
            .read(&mut buffer)
            .map_err(|error| format!("读取本地文件失败: {error}"))?;
        if read == 0 {
            break;
        }
        channel
            .data(&buffer[..read])
            .await
            .map_err(|error| format!("SCP 写入文件内容失败: {error}"))?;
        copied += read as u64;
        progress.update(copied, size).await?;
    }
    let _ = channel.eof().await;

    let started = Instant::now();
    loop {
        if progress.cancel.load(Ordering::SeqCst) {
            let _ = channel.eof().await;
            let _ = channel.close().await;
            return Err(TRANSFER_CANCELLED_MESSAGE.to_string());
        }
        if started.elapsed() > Duration::from_secs(300) {
            let _ = channel.close().await;
            return Err("SCP upload 等待远端完成超时".to_string());
        }
        match tokio::time::timeout(Duration::from_millis(250), channel.wait()).await {
            Ok(Some(ChannelMsg::Data { data })) => output.extend_from_slice(&data),
            Ok(Some(ChannelMsg::ExtendedData { data, .. })) => stderr.extend_from_slice(&data),
            Ok(Some(ChannelMsg::ExitStatus { exit_status: code })) => exit_status = Some(code),
            Ok(Some(ChannelMsg::Eof | ChannelMsg::Close)) | Ok(None) => break,
            Ok(Some(_)) => {}
            Err(_) => {}
        }
    }

    if exit_status.is_some_and(|code| code != 0) {
        return Err(format!(
            "SCP upload remote returned non-zero {:?}: {}",
            exit_status,
            String::from_utf8_lossy(&stderr)
        ));
    }
    let markers = remote_copy_markers(&output);
    let done = markers.done.ok_or_else(|| {
        format!(
            "SCP upload completed but done marker was missing: {}",
            String::from_utf8_lossy(&output)
        )
    })?;
    if done != size {
        return Err(format!(
            "SCP upload size mismatch: remote done {done}, expected {size}"
        ));
    }
    progress.update(done, size).await?;
    Ok(done)
}

fn scp_upload_command(remote_destination: &str, file_name: &str, total: u64) -> String {
    format!(
        concat!(
            "dst={}; source_name={}; total={}; target=; part=; ",
            "if [ -z \"$source_name\" ]; then source_name=portmate-upload.bin; fi; ",
            "case \"$dst\" in */) target=\"${{dst%/}}/$source_name\" ;; ",
            "*) if [ -d \"$dst\" ]; then target=\"${{dst%/}}/$source_name\"; else target=\"$dst\"; fi ;; esac; ",
            "case \"$target\" in */*) part=\"${{target%/*}}/${{target##*/}}.portmate-part\" ;; ",
            "*) part=\"$target.portmate-part\" ;; esac; ",
            "printf '__PORTMATE_SIZE__%s\\n' \"$total\"; ",
            "offset=0; ",
            "if [ -e \"$part\" ]; then ",
            "if current=$(stat -c %s -- \"$part\" 2>/dev/null); then ",
            "if [ \"$current\" -le \"$total\" ]; then offset=$current; else : > \"$part\" || exit 1; fi; ",
            "else : > \"$part\" || exit 1; fi; ",
            "else : > \"$part\" || exit 1; fi; ",
            "printf '__PORTMATE_RESUME__%s\\n' \"$offset\"; ",
            "printf '__PORTMATE_PROGRESS__%s\\n' \"$offset\"; ",
            "if [ \"$offset\" -lt \"$total\" ]; then ",
            "cat >> \"$part\" || exit 1; ",
            "if current=$(stat -c %s -- \"$part\" 2>/dev/null); then ",
            "printf '__PORTMATE_PROGRESS__%s\\n' \"$current\"; ",
            "fi; ",
            "fi; ",
            "final=$(stat -c %s -- \"$part\") || exit 1; ",
            "if [ \"$final\" -ne \"$total\" ]; then ",
            "printf 'PortMate SCP upload size mismatch: %s of %s\\n' \"$final\" \"$total\" >&2; exit 1; ",
            "fi; ",
            "mv -f -- \"$part\" \"$target\" || exit 1; ",
            "stat -c '__PORTMATE_DONE__%s' -- \"$target\""
        ),
        shell_quote(remote_destination),
        shell_quote(file_name),
        total
    )
}

async fn scp_download(
    handle: Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>,
    remote_source: &str,
    local_destination: &str,
    progress: &TransferProgressContext,
) -> Result<u64, String> {
    let mut channel = {
        let handle = handle.lock().await;
        handle
            .channel_open_session()
            .await
            .map_err(|error| format!("SCP 打开 SSH channel 失败: {error}"))?
    };
    channel
        .exec(true, format!("scp -f {}", shell_quote(remote_source)))
        .await
        .map_err(|error| format!("SCP 启动远端发送失败: {error}"))?;
    let mut pending = VecDeque::new();
    channel
        .data(&[0_u8][..])
        .await
        .map_err(|error| format!("SCP 写入初始确认失败: {error}"))?;

    let first = scp_next_byte(&mut channel, &mut pending)
        .await?
        .ok_or_else(|| "SCP remote closed before header".to_string())?;
    if first == 1 || first == 2 {
        let message = scp_read_line(&mut channel, &mut pending).await?;
        return Err(format!("SCP remote error: {message}"));
    }
    if first != b'C' {
        return Err(format!("SCP unexpected header byte: {first}"));
    }

    let header = scp_read_line(&mut channel, &mut pending).await?;
    let parts = header.split_whitespace().collect::<Vec<_>>();
    if parts.len() < 2 {
        return Err(format!("SCP invalid file header: C{header}"));
    }
    let size = parts[1]
        .parse::<u64>()
        .map_err(|error| format!("SCP invalid file size: {error}"))?;

    if let Some(parent) = Path::new(local_destination).parent() {
        fs::create_dir_all(parent).map_err(|error| format!("创建本地目录失败: {error}"))?;
    }
    let target = Path::new(local_destination);
    let temp_target = local_resume_part_path(target);
    let copied = local_resume_offset(&temp_target, size)?;
    progress.set_rate_baseline(copied);
    if copied > 0 {
        progress.update(copied, size).await?;
    }
    if copied == size {
        finalize_local_resume_file(&temp_target, target)?;
        let _ = channel.close().await;
        return Ok(size);
    }
    let mut file = open_local_resume_writer(&temp_target, copied)
        .map_err(|error| format!("创建本地目标文件失败: {error}"))?;
    channel
        .data(&[0_u8][..])
        .await
        .map_err(|error| format!("SCP 写入文件头确认失败: {error}"))?;

    let mut received = 0_u64;
    while received < size {
        progress.check_cancelled()?;
        if pending.is_empty() {
            match channel.wait().await {
                Some(ChannelMsg::Data { data }) | Some(ChannelMsg::ExtendedData { data, .. }) => {
                    pending.extend(data.iter().copied());
                }
                Some(ChannelMsg::Eof) | Some(ChannelMsg::Close) | None => {
                    return Err("SCP remote closed during file body".to_string());
                }
                _ => {}
            }
            continue;
        }
        let take = pending.len().min((size - received) as usize);
        let chunk = pending.drain(..take).collect::<Vec<_>>();
        let chunk_start = received;
        received += take as u64;
        if received <= copied {
            continue;
        }
        let write_from = copied.saturating_sub(chunk_start) as usize;
        file.write_all(&chunk[write_from..])
            .map_err(|error| format!("写入本地目标文件失败: {error}"))?;
        progress.update(received, size).await?;
    }
    file.flush()
        .map_err(|error| format!("刷新本地目标文件失败: {error}"))?;
    drop(file);
    scp_wait_ack(&mut channel, &mut pending).await?;
    channel
        .data(&[0_u8][..])
        .await
        .map_err(|error| format!("SCP 写入完成确认失败: {error}"))?;
    finalize_local_resume_file(&temp_target, target)?;
    let _ = channel.close().await;
    Ok(size)
}

async fn scp_wait_ack(
    channel: &mut Channel<client::Msg>,
    pending: &mut VecDeque<u8>,
) -> Result<(), String> {
    match scp_next_byte(channel, pending).await? {
        Some(0) => Ok(()),
        Some(1) | Some(2) => {
            let message = scp_read_line(channel, pending).await?;
            Err(format!("SCP remote error: {message}"))
        }
        Some(byte) => Err(format!("SCP unexpected ack byte: {byte}")),
        None => Err("SCP remote closed while waiting for ack".to_string()),
    }
}

async fn scp_read_line(
    channel: &mut Channel<client::Msg>,
    pending: &mut VecDeque<u8>,
) -> Result<String, String> {
    let mut bytes = Vec::new();
    while let Some(byte) = scp_next_byte(channel, pending).await? {
        if byte == b'\n' {
            break;
        }
        bytes.push(byte);
    }
    Ok(String::from_utf8_lossy(&bytes).to_string())
}

async fn scp_next_byte(
    channel: &mut Channel<client::Msg>,
    pending: &mut VecDeque<u8>,
) -> Result<Option<u8>, String> {
    loop {
        if let Some(byte) = pending.pop_front() {
            return Ok(Some(byte));
        }
        match channel.wait().await {
            Some(ChannelMsg::Data { data }) | Some(ChannelMsg::ExtendedData { data, .. }) => {
                pending.extend(data.iter().copied());
            }
            Some(ChannelMsg::Eof) | Some(ChannelMsg::Close) | None => return Ok(None),
            _ => {}
        }
    }
}

fn shell_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\\''"))
}

async fn create_tunnel_inner(
    state: &AppState,
    request: CreateTunnelRequest,
) -> Result<TunnelSpec, String> {
    let request = normalize_tunnel_request(request)?;
    let tunnel = TunnelSpec {
        id: Uuid::new_v4().to_string(),
        label: request.label.clone().unwrap_or_else(|| {
            tunnel_label(
                request.mode,
                &request.bind_host,
                request.bind_port,
                &request.target_host,
                request.target_port,
            )
        }),
        mode: request.mode,
        bind_host: request.bind_host.clone(),
        bind_port: request.bind_port,
        target_host: request.target_host.clone(),
        target_port: request.target_port,
        enabled: true,
    };
    let (tunnel, local_addr) = start_tunnel_runtime(
        state,
        &request.session_id,
        tunnel,
        request.label.is_none(),
        None,
    )
    .await?;
    persist_tunnel_to_profile_and_log(state, &request.session_id, &tunnel, local_addr)?;
    Ok(tunnel)
}

async fn start_tunnel_runtime(
    state: &AppState,
    session_id: &str,
    mut tunnel: TunnelSpec,
    relabel_assigned_port: bool,
    expected_runtime_id: Option<&str>,
) -> Result<(TunnelSpec, Option<std::net::SocketAddr>), String> {
    let (handle, remote_forwards, ssh_runtime_id) = {
        let connections = state.ssh.lock().map_err(|error| error.to_string())?;
        let runtime = connections
            .get(session_id)
            .filter(|runtime| {
                expected_runtime_id.is_none_or(|expected| runtime.runtime_id == expected)
            })
            .ok_or_else(|| "需要先连接 SSH/Tmux 会话才能创建 tunnel".to_string())?;
        let store = state.store.lock().map_err(|error| error.to_string())?;
        if !store.runtimes.iter().any(|summary| {
            summary.session_id == session_id && summary.status == SessionStatus::Connected
        }) {
            return Err("需要先连接 SSH/Tmux 会话才能创建 tunnel".to_string());
        }
        (
            Arc::clone(&runtime.handle),
            Arc::clone(&runtime.remote_forwards),
            runtime.runtime_id.clone(),
        )
    };

    if tunnel.id.trim().is_empty() {
        return Err("tunnel requires an id".to_string());
    }
    if state
        .tunnels
        .lock()
        .map_err(|error| error.to_string())?
        .contains_key(&tunnel.id)
    {
        return Err(format!("tunnel already running: {}", tunnel.id));
    }

    if tunnel.mode == TunnelMode::Remote {
        if tunnel.target_host.trim().is_empty() || tunnel.target_port == 0 {
            return Err("remote tunnel requires a local target host and port".to_string());
        }
        let returned_port = {
            let handle = handle.lock().await;
            handle
                .tcpip_forward(tunnel.bind_host.clone(), u32::from(tunnel.bind_port))
                .await
                .map_err(|error| {
                    format!(
                        "remote SSH tunnel request failed {}:{}: {error}",
                        tunnel.bind_host, tunnel.bind_port
                    )
                })?
        };
        if tunnel.bind_port == 0 && returned_port > 0 {
            tunnel.bind_port = returned_port as u16;
            if relabel_assigned_port {
                tunnel.label = tunnel_label(
                    tunnel.mode,
                    &tunnel.bind_host,
                    tunnel.bind_port,
                    &tunnel.target_host,
                    tunnel.target_port,
                );
            }
        }
        let metrics = Arc::new(TunnelMetrics::default());
        let closed = Arc::new(AtomicBool::new(false));
        {
            let connections = state.ssh.lock().map_err(|error| error.to_string())?;
            if connections
                .get(session_id)
                .is_none_or(|runtime| runtime.runtime_id != ssh_runtime_id)
            {
                return Err("SSH runtime changed while creating tunnel".to_string());
            }
            let store = state.store.lock().map_err(|error| error.to_string())?;
            if !store.runtimes.iter().any(|runtime| {
                runtime.session_id == session_id && runtime.status == SessionStatus::Connected
            }) {
                return Err("SSH session disconnected while creating tunnel".to_string());
            }
            let mut tunnels = state.tunnels.lock().map_err(|error| error.to_string())?;
            if tunnels.contains_key(&tunnel.id) {
                return Err(format!("tunnel already running: {}", tunnel.id));
            }
            let mut forwards = remote_forwards.lock().map_err(|error| error.to_string())?;
            let target = TunnelForwardTarget {
                spec: tunnel.clone(),
                metrics: Arc::clone(&metrics),
            };
            forwards.insert(
                remote_forward_key(&tunnel.bind_host, tunnel.bind_port),
                target.clone(),
            );
            forwards.insert(remote_forward_port_key(tunnel.bind_port), target);
            tunnels.insert(
                tunnel.id.clone(),
                TunnelRuntime {
                    session_id: session_id.to_string(),
                    ssh_runtime_id: ssh_runtime_id.clone(),
                    spec: tunnel.clone(),
                    metrics: Arc::clone(&metrics),
                    closed: Arc::clone(&closed),
                },
            );
        }
        spawn_remote_tunnel_health_monitor(state.clone(), tunnel.id.clone(), Arc::clone(&closed));
        return Ok((tunnel, None));
    }

    let listener = TcpListener::bind((tunnel.bind_host.clone(), tunnel.bind_port))
        .await
        .map_err(|error| {
            format!(
                "SSH tunnel bind failed {}:{}: {error}",
                tunnel.bind_host, tunnel.bind_port
            )
        })?;
    let local_addr = listener
        .local_addr()
        .map_err(|error| format!("SSH tunnel local addr failed: {error}"))?;
    if tunnel.bind_port == 0 {
        tunnel.bind_port = local_addr.port();
        if relabel_assigned_port {
            tunnel.label = tunnel_label(
                tunnel.mode,
                &tunnel.bind_host,
                tunnel.bind_port,
                &tunnel.target_host,
                tunnel.target_port,
            );
        }
    }
    let closed = Arc::new(AtomicBool::new(false));
    let metrics = Arc::new(TunnelMetrics::default());
    {
        let connections = state.ssh.lock().map_err(|error| error.to_string())?;
        if connections
            .get(session_id)
            .is_none_or(|runtime| runtime.runtime_id != ssh_runtime_id)
        {
            return Err("SSH runtime changed while creating tunnel".to_string());
        }
        let store = state.store.lock().map_err(|error| error.to_string())?;
        if !store.runtimes.iter().any(|runtime| {
            runtime.session_id == session_id && runtime.status == SessionStatus::Connected
        }) {
            return Err("SSH session disconnected while creating tunnel".to_string());
        }
        let mut tunnels = state.tunnels.lock().map_err(|error| error.to_string())?;
        if tunnels.contains_key(&tunnel.id) {
            return Err(format!("tunnel already running: {}", tunnel.id));
        }
        tunnels.insert(
            tunnel.id.clone(),
            TunnelRuntime {
                session_id: session_id.to_string(),
                ssh_runtime_id: ssh_runtime_id.clone(),
                spec: tunnel.clone(),
                metrics: Arc::clone(&metrics),
                closed: Arc::clone(&closed),
            },
        );
    }

    let session_id = session_id.to_string();
    let store = Arc::clone(&state.store);
    let store_path = state.store_path.clone();
    let tunnel_registry = Arc::clone(&state.tunnels);
    let tunnel_for_task = tunnel.clone();
    let ssh_runtime_id_for_task = ssh_runtime_id;
    tauri::async_runtime::spawn(async move {
        loop {
            if closed.load(Ordering::SeqCst) {
                break;
            }
            match tokio::time::timeout(Duration::from_millis(500), listener.accept()).await {
                Ok(Ok((stream, peer))) => {
                    let handle = handle.clone();
                    let spec = tunnel_for_task.clone();
                    let metrics = Arc::clone(&metrics);
                    let store = Arc::clone(&store);
                    let store_path = store_path.clone();
                    let session_id = session_id.clone();
                    tauri::async_runtime::spawn(async move {
                        metrics.connection_opened();
                        let result = if spec.mode == TunnelMode::Dynamic {
                            handle_dynamic_tunnel_client(handle, stream, peer, Arc::clone(&metrics))
                                .await
                        } else {
                            handle_local_tunnel_client(
                                handle,
                                spec,
                                stream,
                                peer,
                                Arc::clone(&metrics),
                            )
                            .await
                        };
                        match result {
                            Ok(()) => {
                                metrics.clear_error();
                                metrics.connection_closed();
                            }
                            Err(error) => {
                                metrics.record_error(&error);
                                metrics.connection_closed();
                                if let Ok(mut store) = store.lock() {
                                    store.record_system_event(
                                        &session_id,
                                        format!("PortMate: SSH tunnel client failed: {error}"),
                                    );
                                    if let Err(error) = save_store(&store_path, &store) {
                                        eprintln!(
                                            "PortMate: failed to persist tunnel client error: {error}"
                                        );
                                    }
                                }
                            }
                        }
                    });
                }
                Ok(Err(error)) => {
                    let message = format!("SSH tunnel accept failed: {error}");
                    let removed = match fail_tunnel_runtime_if_owned(
                        &tunnel_registry,
                        &tunnel_for_task.id,
                        &ssh_runtime_id_for_task,
                        &message,
                    ) {
                        Ok(Some(_)) => true,
                        Ok(None) => false,
                        Err(registry_error) => {
                            closed.store(true, Ordering::SeqCst);
                            metrics.record_error(&format!("{message}; {registry_error}"));
                            false
                        }
                    };
                    if removed {
                        if let Ok(mut store) = store.lock() {
                            let mut stopped = tunnel_for_task.clone();
                            stopped.enabled = false;
                            mark_tunnel_stopped_in_store(&mut store, &session_id, &stopped);
                            store.record_system_event(&session_id, format!("PortMate: {message}"));
                            let _ = save_store(&store_path, &store);
                        }
                    }
                    break;
                }
                Err(_) => {}
            }
        }
    });

    Ok((tunnel, Some(local_addr)))
}

fn spawn_remote_tunnel_health_monitor(state: AppState, tunnel_id: String, closed: Arc<AtomicBool>) {
    tauri::async_runtime::spawn(async move {
        loop {
            tokio::time::sleep(REMOTE_TUNNEL_HEALTH_INTERVAL).await;
            if closed.load(Ordering::SeqCst) {
                break;
            }
            match check_remote_tunnel_health(&state, &tunnel_id).await {
                Ok(RemoteTunnelHealth::Unsupported) => break,
                Ok(RemoteTunnelHealth::Healthy | RemoteTunnelHealth::Restored) => {}
                Err(error) => {
                    eprintln!("PortMate: remote tunnel health check failed: {error}");
                }
            }
        }
    });
}

async fn check_remote_tunnel_health(
    state: &AppState,
    tunnel_id: &str,
) -> Result<RemoteTunnelHealth, String> {
    let runtime = {
        let tunnels = state.tunnels.lock().map_err(|error| error.to_string())?;
        tunnels
            .get(tunnel_id)
            .cloned()
            .ok_or_else(|| format!("tunnel not found: {tunnel_id}"))?
    };
    if runtime.spec.mode != TunnelMode::Remote {
        return Err(format!("tunnel is not a remote forward: {tunnel_id}"));
    }
    if runtime.closed.load(Ordering::SeqCst) {
        return Err(format!("remote tunnel is closed: {tunnel_id}"));
    }

    let result = probe_remote_tunnel_health(state, &runtime).await;
    match &result {
        Ok(RemoteTunnelHealth::Healthy) => {
            if runtime
                .metrics
                .clear_error_with_prefix(REMOTE_TUNNEL_HEALTH_ERROR_PREFIX)
            {
                record_tunnel_health_event(
                    state,
                    &runtime.session_id,
                    tunnel_id,
                    "remote forward is healthy again",
                );
            }
        }
        Ok(RemoteTunnelHealth::Restored) => {
            runtime
                .metrics
                .clear_error_with_prefix(REMOTE_TUNNEL_HEALTH_ERROR_PREFIX);
            record_tunnel_health_event(
                state,
                &runtime.session_id,
                tunnel_id,
                "remote forward listener was missing and has been restored",
            );
        }
        Ok(RemoteTunnelHealth::Unsupported) => {}
        Err(error) => {
            let message = format!("{REMOTE_TUNNEL_HEALTH_ERROR_PREFIX} {error}");
            if runtime.metrics.record_error_if_changed(&message) {
                record_tunnel_health_event(state, &runtime.session_id, tunnel_id, &message);
            }
        }
    }
    result
}

async fn probe_remote_tunnel_health(
    state: &AppState,
    runtime: &TunnelRuntime,
) -> Result<RemoteTunnelHealth, String> {
    let (handle, remote_forwards) = {
        let connections = state.ssh.lock().map_err(|error| error.to_string())?;
        connections
            .get(&runtime.session_id)
            .filter(|ssh| ssh.runtime_id == runtime.ssh_runtime_id)
            .map(|ssh| (Arc::clone(&ssh.handle), Arc::clone(&ssh.remote_forwards)))
            .ok_or_else(|| format!("SSH runtime is unavailable for {}", runtime.session_id))?
    };

    let mut routing_restored = false;
    {
        let mut forwards = remote_forwards.lock().map_err(|error| error.to_string())?;
        let exact_key = remote_forward_key(&runtime.spec.bind_host, runtime.spec.bind_port);
        let port_key = remote_forward_port_key(runtime.spec.bind_port);
        if !forwards.contains_key(&exact_key) || !forwards.contains_key(&port_key) {
            let target = TunnelForwardTarget {
                spec: runtime.spec.clone(),
                metrics: Arc::clone(&runtime.metrics),
            };
            forwards.insert(exact_key, target.clone());
            forwards.insert(port_key, target);
            routing_restored = true;
        }
    }

    let output = match exec_ssh_command_capture(
        Arc::clone(&handle),
        REMOTE_TUNNEL_PROBE_COMMAND,
        REMOTE_TUNNEL_HEALTH_TIMEOUT,
    )
    .await
    {
        Ok(output) => output,
        Err(error) if error.starts_with("SSH exec 返回非零状态") => {
            return Ok(RemoteTunnelHealth::Unsupported);
        }
        Err(error) => return Err(format!("listener probe failed: {error}")),
    };
    match parse_remote_listener_probe(&output, runtime.spec.bind_port) {
        RemoteListenerProbe::Listening => Ok(if routing_restored {
            RemoteTunnelHealth::Restored
        } else {
            RemoteTunnelHealth::Healthy
        }),
        RemoteListenerProbe::Unsupported => Ok(RemoteTunnelHealth::Unsupported),
        RemoteListenerProbe::Missing => {
            if runtime.closed.load(Ordering::SeqCst) {
                return Err("tunnel closed during listener probe".to_string());
            }
            let returned_port = {
                let handle = handle.lock().await;
                if runtime.closed.load(Ordering::SeqCst) {
                    return Err("tunnel closed before listener restore".to_string());
                }
                handle
                    .tcpip_forward(
                        runtime.spec.bind_host.clone(),
                        u32::from(runtime.spec.bind_port),
                    )
                    .await
                    .map_err(|error| {
                        format!(
                            "listener restore failed {}:{}: {error}",
                            runtime.spec.bind_host, runtime.spec.bind_port
                        )
                    })?
            };
            if returned_port != 0 && returned_port != u32::from(runtime.spec.bind_port) {
                return Err(format!(
                    "listener restore returned unexpected port {returned_port} for {}",
                    runtime.spec.bind_port
                ));
            }
            Ok(RemoteTunnelHealth::Restored)
        }
    }
}

fn parse_remote_listener_probe(output: &str, port: u16) -> RemoteListenerProbe {
    if output.contains("__PORTMATE_UNSUPPORTED__") {
        return RemoteListenerProbe::Unsupported;
    }
    if let Some((_, table)) = output.split_once("__PORTMATE_PROC__") {
        let expected_port = format!("{port:04X}");
        let listening = table.lines().any(|line| {
            let fields = line.split_whitespace().collect::<Vec<_>>();
            fields.len() > 3
                && fields[3] == "0A"
                && fields[1]
                    .rsplit_once(':')
                    .is_some_and(|(_, value)| value.eq_ignore_ascii_case(&expected_port))
        });
        return if listening {
            RemoteListenerProbe::Listening
        } else {
            RemoteListenerProbe::Missing
        };
    }
    if output.contains("__PORTMATE_SOCKSTAT__") {
        let listening = output
            .lines()
            .skip_while(|line| !line.contains("__PORTMATE_SOCKSTAT__"))
            .skip(1)
            .any(|line| {
                !line.to_ascii_uppercase().contains("LOCAL ADDRESS")
                    && line
                        .split_whitespace()
                        .any(|field| socket_endpoint_port(field) == Some(port))
            });
        return if listening {
            RemoteListenerProbe::Listening
        } else {
            RemoteListenerProbe::Missing
        };
    }
    if output.contains("__PORTMATE_SS__")
        || output.contains("__PORTMATE_LSOF__")
        || output.contains("__PORTMATE_NETSTAT__")
    {
        let listening = output.lines().any(|line| {
            line.to_ascii_uppercase().contains("LISTEN")
                && line
                    .split_whitespace()
                    .any(|field| socket_endpoint_port(field) == Some(port))
        });
        return if listening {
            RemoteListenerProbe::Listening
        } else {
            RemoteListenerProbe::Missing
        };
    }
    RemoteListenerProbe::Unsupported
}

fn socket_endpoint_port(endpoint: &str) -> Option<u16> {
    let endpoint = endpoint.trim_matches(|character: char| {
        character == ',' || character == ';' || character == '(' || character == ')'
    });
    endpoint
        .rsplit_once(':')
        .or_else(|| endpoint.rsplit_once('.'))
        .and_then(|(_, port)| port.parse::<u16>().ok())
}

fn record_tunnel_health_event(state: &AppState, session_id: &str, tunnel_id: &str, message: &str) {
    if let Ok(mut store) = state.store.lock() {
        store.record_system_event(
            session_id,
            format!("PortMate: remote tunnel {tunnel_id}: {message}"),
        );
        if let Err(error) = save_store(&state.store_path, &store) {
            eprintln!("PortMate: failed to persist remote tunnel health event: {error}");
        }
    }
}

fn enabled_tunnel_specs(state: &AppState, session_id: &str) -> Result<Vec<TunnelSpec>, String> {
    let store = state.store.lock().map_err(|error| error.to_string())?;
    let profile = store
        .profile(session_id)
        .ok_or_else(|| format!("unknown session: {session_id}"))?;
    let tunnels = match profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => ssh.tunnels,
        _ => Vec::new(),
    };
    Ok(tunnels
        .into_iter()
        .filter(|tunnel| tunnel.enabled)
        .collect())
}

async fn restore_enabled_tunnels(
    state: &AppState,
    session_id: &str,
    runtime_id: &str,
) -> (usize, usize) {
    if !ssh_runtime_connected(state, session_id, runtime_id) {
        return (0, 0);
    }
    let tunnels = match enabled_tunnel_specs(state, session_id) {
        Ok(tunnels) => tunnels,
        Err(error) => {
            record_tunnel_restore_failure(state, session_id, None, &error);
            return (0, 1);
        }
    };
    let mut restored = 0;
    let mut failed = 0;
    for tunnel in tunnels {
        if !ssh_runtime_connected(state, session_id, runtime_id) {
            break;
        }
        let tunnel_id = tunnel.id.clone();
        match start_tunnel_runtime(state, session_id, tunnel, false, Some(runtime_id)).await {
            Ok((tunnel, local_addr)) => {
                if !ssh_runtime_connected(state, session_id, runtime_id) {
                    let _ = fail_tunnel_runtime_if_owned(
                        &state.tunnels,
                        &tunnel_id,
                        runtime_id,
                        "SSH reconnect superseded while restoring tunnel",
                    );
                    break;
                }
                restored += 1;
                if let Err(error) =
                    persist_tunnel_to_profile_and_log(state, session_id, &tunnel, local_addr)
                {
                    record_tunnel_restore_failure(
                        state,
                        session_id,
                        Some(&tunnel_id),
                        &format!("runtime restored but persistence failed: {error}"),
                    );
                }
            }
            Err(error) => {
                if !ssh_runtime_connected(state, session_id, runtime_id) {
                    break;
                }
                failed += 1;
                record_tunnel_restore_failure(state, session_id, Some(&tunnel_id), &error);
            }
        }
    }
    (restored, failed)
}

fn record_tunnel_restore_failure(
    state: &AppState,
    session_id: &str,
    tunnel_id: Option<&str>,
    error: &str,
) {
    let label = tunnel_id.map(|id| format!(" {id}")).unwrap_or_default();
    if let Ok(mut store) = state.store.lock() {
        store.record_system_event(
            session_id,
            format!("PortMate: failed to restore SSH tunnel{label}: {error}"),
        );
        if let Err(save_error) = save_store(&state.store_path, &store) {
            eprintln!("PortMate: failed to persist tunnel restore failure: {save_error}");
        }
    }
}

fn normalize_tunnel_request(
    mut request: CreateTunnelRequest,
) -> Result<CreateTunnelRequest, String> {
    request.session_id = request.session_id.trim().to_string();
    request.bind_host = request.bind_host.trim().to_string();
    request.target_host = request.target_host.trim().to_string();
    request.label = request
        .label
        .as_deref()
        .map(str::trim)
        .filter(|label| !label.is_empty())
        .map(ToOwned::to_owned);

    if request.session_id.is_empty() {
        return Err("tunnel requires a session id".to_string());
    }
    if request.mode != TunnelMode::Remote && request.bind_host.is_empty() {
        return Err("local and dynamic tunnels require a bind host".to_string());
    }
    if request.mode != TunnelMode::Dynamic
        && (request.target_host.is_empty() || request.target_port == 0)
    {
        return Err("local and remote tunnels require a target host and port".to_string());
    }
    if request.mode == TunnelMode::Dynamic {
        request.target_host.clear();
        request.target_port = 0;
    }
    Ok(request)
}

fn list_tunnels_inner(
    state: &AppState,
    session_id: Option<&str>,
) -> Result<Vec<TunnelStatus>, String> {
    let tunnels = state.tunnels.lock().map_err(|error| error.to_string())?;
    let mut statuses = tunnels
        .values()
        .filter(|runtime| {
            !runtime.closed.load(Ordering::SeqCst)
                && match session_id {
                    Some(expected) => runtime.session_id == expected,
                    None => true,
                }
        })
        .map(tunnel_status_from_runtime)
        .collect::<Vec<_>>();
    statuses.sort_by(|left, right| {
        left.spec
            .label
            .cmp(&right.spec.label)
            .then_with(|| left.spec.id.cmp(&right.spec.id))
    });
    Ok(statuses)
}

fn fail_tunnel_runtime_if_owned(
    tunnels: &Arc<Mutex<HashMap<String, TunnelRuntime>>>,
    tunnel_id: &str,
    ssh_runtime_id: &str,
    error: &str,
) -> Result<Option<TunnelRuntime>, String> {
    let mut tunnels = tunnels
        .lock()
        .map_err(|lock_error| lock_error.to_string())?;
    if tunnels
        .get(tunnel_id)
        .is_none_or(|runtime| runtime.ssh_runtime_id != ssh_runtime_id)
    {
        return Ok(None);
    }
    let runtime = tunnels.remove(tunnel_id);
    if let Some(runtime) = &runtime {
        runtime.metrics.record_error(error);
        runtime.closed.store(true, Ordering::SeqCst);
    }
    Ok(runtime)
}

fn fail_session_tunnel_runtimes(
    tunnels: &Arc<Mutex<HashMap<String, TunnelRuntime>>>,
    session_id: &str,
    error: &str,
) -> Result<usize, String> {
    let mut tunnels = tunnels
        .lock()
        .map_err(|lock_error| lock_error.to_string())?;
    let ids = tunnels
        .iter()
        .filter_map(|(id, runtime)| (runtime.session_id == session_id).then_some(id.clone()))
        .collect::<Vec<_>>();
    let mut removed = 0;
    for id in ids {
        if let Some(runtime) = tunnels.remove(&id) {
            runtime.metrics.record_error(error);
            runtime.closed.store(true, Ordering::SeqCst);
            removed += 1;
        }
    }
    Ok(removed)
}

async fn stop_tunnel_inner(state: &AppState, tunnel_id: &str) -> Result<TunnelStatus, String> {
    let runtime = {
        let tunnels = state.tunnels.lock().map_err(|error| error.to_string())?;
        tunnels
            .get(tunnel_id)
            .cloned()
            .ok_or_else(|| format!("tunnel not found: {tunnel_id}"))?
    };

    let mut stopped = runtime.spec.clone();
    stopped.enabled = false;
    runtime.closed.store(true, Ordering::SeqCst);
    let mut warnings = Vec::new();

    if runtime.spec.mode == TunnelMode::Remote {
        let remote_forward = match state.ssh.lock() {
            Ok(connections) => connections
                .get(&runtime.session_id)
                .filter(|ssh| ssh.runtime_id == runtime.ssh_runtime_id)
                .map(|ssh| (Arc::clone(&ssh.handle), Arc::clone(&ssh.remote_forwards))),
            Err(error) => {
                warnings.push(format!(
                    "SSH runtime lock failed during remote cancel: {error}"
                ));
                None
            }
        };
        if let Some((handle, remote_forwards)) = remote_forward {
            let cancel = tokio::time::timeout(REMOTE_TUNNEL_HEALTH_TIMEOUT, async {
                let handle = handle.lock().await;
                handle
                    .cancel_tcpip_forward(
                        runtime.spec.bind_host.clone(),
                        u32::from(runtime.spec.bind_port),
                    )
                    .await
            })
            .await;
            match cancel {
                Ok(Ok(())) => {}
                Ok(Err(error)) => warnings.push(format!(
                    "remote SSH tunnel cancel failed {}:{}: {error}",
                    runtime.spec.bind_host, runtime.spec.bind_port
                )),
                Err(_) => warnings.push(format!(
                    "remote SSH tunnel cancel timed out {}:{}",
                    runtime.spec.bind_host, runtime.spec.bind_port
                )),
            }
            match remote_forwards.lock() {
                Ok(mut forwards) => {
                    forwards.remove(&remote_forward_key(
                        &runtime.spec.bind_host,
                        runtime.spec.bind_port,
                    ));
                    forwards.remove(&remote_forward_port_key(runtime.spec.bind_port));
                }
                Err(error) => {
                    warnings.push(format!("remote forward route cleanup failed: {error}"))
                }
            }
        } else if warnings.is_empty() {
            warnings.push("SSH runtime unavailable during remote cancel".to_string());
        }
    }

    {
        let mut tunnels = state.tunnels.lock().map_err(|error| error.to_string())?;
        tunnels
            .remove(tunnel_id)
            .ok_or_else(|| format!("tunnel not found: {tunnel_id}"))?;
    }

    persist_stopped_tunnel_to_profile_and_log(state, &runtime.session_id, &stopped)?;
    if !warnings.is_empty() {
        let warning = warnings.join("; ");
        runtime.metrics.record_error(&warning);
        record_tunnel_health_event(
            state,
            &runtime.session_id,
            tunnel_id,
            &format!("stopped locally with warning: {warning}"),
        );
    }
    Ok(runtime.metrics.snapshot(stopped))
}

fn tunnel_status_from_runtime(runtime: &TunnelRuntime) -> TunnelStatus {
    runtime.metrics.snapshot(runtime.spec.clone())
}

fn tunnel_label(
    mode: TunnelMode,
    bind_host: &str,
    bind_port: u16,
    target_host: &str,
    target_port: u16,
) -> String {
    match mode {
        TunnelMode::Local => {
            format!("{bind_host}:{bind_port} -> {target_host}:{target_port}")
        }
        TunnelMode::Dynamic => format!("SOCKS5 {bind_host}:{bind_port}"),
        TunnelMode::Remote => {
            format!("remote {bind_host}:{bind_port} -> {target_host}:{target_port}")
        }
    }
}

fn persist_tunnel_to_profile_and_log(
    state: &AppState,
    session_id: &str,
    tunnel: &TunnelSpec,
    local_addr: Option<std::net::SocketAddr>,
) -> Result<(), String> {
    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    if let Some(mut profile) = store.profile(session_id) {
        match &mut profile.connection {
            ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => {
                ssh.tunnels.retain(|item| item.id != tunnel.id);
                ssh.tunnels.push(tunnel.clone());
                let _ = store.upsert_profile(profile);
            }
            _ => {}
        }
    }
    let listen = local_addr
        .map(|addr| addr.to_string())
        .unwrap_or_else(|| format!("{}:{}", tunnel.bind_host, tunnel.bind_port));
    store.record_system_event(
        session_id,
        format!(
            "PortMate: SSH {:?} tunnel listening on {} -> {}:{}",
            tunnel.mode, listen, tunnel.target_host, tunnel.target_port
        ),
    );
    save_store(&state.store_path, &store)
}

fn persist_stopped_tunnel_to_profile_and_log(
    state: &AppState,
    session_id: &str,
    stopped: &TunnelSpec,
) -> Result<(), String> {
    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    mark_tunnel_stopped_in_store(&mut store, session_id, stopped);
    store.record_system_event(
        session_id,
        format!(
            "PortMate: SSH {:?} tunnel stopped on {}:{}",
            stopped.mode, stopped.bind_host, stopped.bind_port
        ),
    );
    save_store(&state.store_path, &store)
}

fn mark_tunnel_stopped_in_store(store: &mut SessionStore, session_id: &str, stopped: &TunnelSpec) {
    if let Some(mut profile) = store.profile(session_id) {
        match &mut profile.connection {
            ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => {
                if let Some(saved) = ssh.tunnels.iter_mut().find(|item| item.id == stopped.id) {
                    saved.enabled = false;
                } else {
                    ssh.tunnels.push(stopped.clone());
                }
                let _ = store.upsert_profile(profile);
            }
            _ => {}
        }
    }
}

fn remote_forward_key(host: &str, port: u16) -> String {
    format!("{}:{}", host, port)
}

fn remote_forward_port_key(port: u16) -> String {
    format!("*:{}", port)
}

async fn handle_local_tunnel_client(
    handle: Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>,
    tunnel: TunnelSpec,
    local_stream: TcpStream,
    peer: std::net::SocketAddr,
    metrics: Arc<TunnelMetrics>,
) -> Result<(), String> {
    let channel = {
        let handle = handle.lock().await;
        handle
            .channel_open_direct_tcpip(
                tunnel.target_host.clone(),
                u32::from(tunnel.target_port),
                peer.ip().to_string(),
                u32::from(peer.port()),
            )
            .await
            .map_err(|error| format!("direct-tcpip open failed: {error}"))?
    };
    let (mut remote_read, remote_write) = channel.split();
    let (mut local_read, mut local_write) = local_stream.into_split();

    let upload_metrics = Arc::clone(&metrics);
    let local_to_remote = async move {
        let mut buffer = vec![0_u8; 16 * 1024];
        loop {
            let size = local_read
                .read(&mut buffer)
                .await
                .map_err(|error| error.to_string())?;
            if size == 0 {
                remote_write
                    .eof()
                    .await
                    .map_err(|error| error.to_string())?;
                break;
            }
            upload_metrics.add_tcp_to_ssh_bytes(size);
            remote_write
                .data(&buffer[..size])
                .await
                .map_err(|error| error.to_string())?;
        }
        Ok::<(), String>(())
    };

    let download_metrics = Arc::clone(&metrics);
    let remote_to_local = async move {
        while let Some(message) = remote_read.wait().await {
            match message {
                ChannelMsg::Data { data } | ChannelMsg::ExtendedData { data, .. } => {
                    download_metrics.add_ssh_to_tcp_bytes(data.len());
                    local_write
                        .write_all(&data)
                        .await
                        .map_err(|error| error.to_string())?;
                }
                ChannelMsg::Eof | ChannelMsg::Close => break,
                _ => {}
            }
        }
        Ok::<(), String>(())
    };

    tokio::try_join!(local_to_remote, remote_to_local)
        .map(|_| ())
        .map_err(|error| format!("local tunnel pipe failed ({}): {error}", tunnel.label))
}

async fn handle_remote_tunnel_client(
    channel: Channel<client::Msg>,
    tunnel: TunnelSpec,
    originator_address: String,
    originator_port: u16,
    metrics: Arc<TunnelMetrics>,
) -> Result<(), String> {
    let local_stream =
        match TcpStream::connect((tunnel.target_host.clone(), tunnel.target_port)).await {
            Ok(stream) => stream,
            Err(error) => {
                let _ = channel.eof().await;
                let _ = channel.close().await;
                return Err(format!(
                    "remote tunnel target connect failed {}:{} for {}:{}: {error}",
                    tunnel.target_host, tunnel.target_port, originator_address, originator_port
                ));
            }
        };
    pipe_ssh_channel_to_tcp(channel, local_stream, tunnel, metrics).await
}

async fn handle_dynamic_tunnel_client(
    handle: Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>,
    mut local_stream: TcpStream,
    peer: std::net::SocketAddr,
    metrics: Arc<TunnelMetrics>,
) -> Result<(), String> {
    let (target_host, target_port) = read_socks5_connect_request(&mut local_stream).await?;

    let channel = {
        let handle = handle.lock().await;
        handle
            .channel_open_direct_tcpip(
                target_host.clone(),
                u32::from(target_port),
                peer.ip().to_string(),
                u32::from(peer.port()),
            )
            .await
    };
    let channel = match channel {
        Ok(channel) => channel,
        Err(error) => {
            let _ = local_stream.write_all(&socks5_reply(5)).await;
            return Err(format!("dynamic direct-tcpip open failed: {error}"));
        }
    };

    local_stream
        .write_all(&socks5_reply(0))
        .await
        .map_err(|error| format!("SOCKS5 success response failed: {error}"))?;

    let spec = TunnelSpec {
        id: "dynamic-client".to_string(),
        label: format!("SOCKS5 -> {target_host}:{target_port}"),
        mode: TunnelMode::Dynamic,
        bind_host: String::new(),
        bind_port: 0,
        target_host,
        target_port,
        enabled: true,
    };
    pipe_ssh_channel_to_tcp(channel, local_stream, spec, metrics).await
}

async fn read_socks5_connect_request(
    local_stream: &mut TcpStream,
) -> Result<(String, u16), String> {
    let mut header = [0_u8; 2];
    local_stream
        .read_exact(&mut header)
        .await
        .map_err(|error| format!("SOCKS5 handshake read failed: {error}"))?;
    if header[0] != 5 {
        let _ = local_stream.write_all(&[5, 0xff]).await;
        return Err("only SOCKS5 is supported for dynamic tunnel".to_string());
    }
    let mut methods = vec![0_u8; header[1] as usize];
    local_stream
        .read_exact(&mut methods)
        .await
        .map_err(|error| format!("SOCKS5 methods read failed: {error}"))?;
    if !methods.contains(&0) {
        local_stream
            .write_all(&[5, 0xff])
            .await
            .map_err(|error| format!("SOCKS5 method rejection failed: {error}"))?;
        return Err("SOCKS5 client did not offer no-authentication method".to_string());
    }
    local_stream
        .write_all(&[5, 0])
        .await
        .map_err(|error| format!("SOCKS5 method response failed: {error}"))?;

    let mut request = [0_u8; 4];
    local_stream
        .read_exact(&mut request)
        .await
        .map_err(|error| format!("SOCKS5 request read failed: {error}"))?;
    if request[0] != 5 || request[2] != 0 {
        let _ = local_stream.write_all(&socks5_reply(1)).await;
        return Err("invalid SOCKS5 CONNECT request header".to_string());
    }
    if request[1] != 1 {
        local_stream.write_all(&socks5_reply(7)).await.ok();
        return Err("only SOCKS5 CONNECT is supported".to_string());
    }

    let target_host = match request[3] {
        1 => {
            let mut addr = [0_u8; 4];
            local_stream
                .read_exact(&mut addr)
                .await
                .map_err(|error| format!("SOCKS5 IPv4 read failed: {error}"))?;
            std::net::Ipv4Addr::from(addr).to_string()
        }
        3 => {
            let mut len = [0_u8; 1];
            local_stream
                .read_exact(&mut len)
                .await
                .map_err(|error| format!("SOCKS5 domain length read failed: {error}"))?;
            if len[0] == 0 {
                let _ = local_stream.write_all(&socks5_reply(8)).await;
                return Err("SOCKS5 domain name cannot be empty".to_string());
            }
            let mut name = vec![0_u8; len[0] as usize];
            local_stream
                .read_exact(&mut name)
                .await
                .map_err(|error| format!("SOCKS5 domain read failed: {error}"))?;
            match String::from_utf8(name) {
                Ok(name) => name,
                Err(_) => {
                    let _ = local_stream.write_all(&socks5_reply(8)).await;
                    return Err("SOCKS5 domain name is not valid UTF-8".to_string());
                }
            }
        }
        4 => {
            let mut addr = [0_u8; 16];
            local_stream
                .read_exact(&mut addr)
                .await
                .map_err(|error| format!("SOCKS5 IPv6 read failed: {error}"))?;
            std::net::Ipv6Addr::from(addr).to_string()
        }
        other => {
            let _ = local_stream.write_all(&socks5_reply(8)).await;
            return Err(format!("unsupported SOCKS5 address type: {other}"));
        }
    };
    let mut port_bytes = [0_u8; 2];
    local_stream
        .read_exact(&mut port_bytes)
        .await
        .map_err(|error| format!("SOCKS5 port read failed: {error}"))?;
    let target_port = u16::from_be_bytes(port_bytes);
    if target_port == 0 {
        let _ = local_stream.write_all(&socks5_reply(1)).await;
        return Err("SOCKS5 target port cannot be zero".to_string());
    }
    Ok((target_host, target_port))
}

fn socks5_reply(code: u8) -> [u8; 10] {
    [5, code, 0, 1, 0, 0, 0, 0, 0, 0]
}

async fn pipe_ssh_channel_to_tcp(
    channel: Channel<client::Msg>,
    local_stream: TcpStream,
    tunnel: TunnelSpec,
    metrics: Arc<TunnelMetrics>,
) -> Result<(), String> {
    let (mut remote_read, remote_write) = channel.split();
    let (mut local_read, mut local_write) = local_stream.into_split();

    let upload_metrics = Arc::clone(&metrics);
    let local_to_remote = async move {
        let mut buffer = vec![0_u8; 16 * 1024];
        loop {
            let size = local_read
                .read(&mut buffer)
                .await
                .map_err(|error| error.to_string())?;
            if size == 0 {
                remote_write
                    .eof()
                    .await
                    .map_err(|error| error.to_string())?;
                break;
            }
            upload_metrics.add_tcp_to_ssh_bytes(size);
            remote_write
                .data(&buffer[..size])
                .await
                .map_err(|error| error.to_string())?;
        }
        Ok::<(), String>(())
    };

    let download_metrics = Arc::clone(&metrics);
    let remote_to_local = async move {
        while let Some(message) = remote_read.wait().await {
            match message {
                ChannelMsg::Data { data } | ChannelMsg::ExtendedData { data, .. } => {
                    download_metrics.add_ssh_to_tcp_bytes(data.len());
                    local_write
                        .write_all(&data)
                        .await
                        .map_err(|error| error.to_string())?;
                }
                ChannelMsg::Eof | ChannelMsg::Close => break,
                _ => {}
            }
        }
        Ok::<(), String>(())
    };

    tokio::try_join!(local_to_remote, remote_to_local)
        .map(|_| ())
        .map_err(|error| format!("tunnel pipe failed ({}): {error}", tunnel.label))
}

async fn open_ssh_session(
    state: &AppState,
    profile: SessionProfile,
    password: Option<String>,
    passphrase: Option<String>,
) -> Result<SessionSummary, String> {
    if let Some(existing) = {
        let mut connections = state.ssh.lock().map_err(|error| error.to_string())?;
        connections.remove(&profile.id)
    } {
        existing.closed.store(true, Ordering::SeqCst);
        let handle = existing.handle.lock().await;
        let _ = handle
            .disconnect(Disconnect::ByApplication, "PortMate reconnect", "en")
            .await;
        for jump_handle in existing.jump_handles {
            let handle = jump_handle.lock().await;
            let _ = handle
                .disconnect(Disconnect::ByApplication, "PortMate reconnect jump", "en")
                .await;
        }
    }

    let established = establish_ssh_runtime(state, &profile, password, passphrase).await?;
    let one_time_cleanup_error = take_one_time_host_keys(state, &profile.id).err();
    let EstablishedSshRuntime {
        runtime_id,
        runtime,
        tap,
        read_half,
        auth_method,
        closed,
    } = established;
    {
        let mut connections = state.ssh.lock().map_err(|error| error.to_string())?;
        connections.insert(profile.id.clone(), runtime);
    }

    tauri::async_runtime::spawn(read_ssh_channel(SshReadTask {
        state: state.clone(),
        profile: profile.clone(),
        runtime_id,
        tap,
        read_half,
        closed,
    }));

    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    let _ = store.record_auth_success(&profile.id, auth_method);
    store.record_system_event(
        &profile.id,
        format!("PortMate: SSH authentication succeeded via {auth_method:?}"),
    );
    if let Some(error) = one_time_cleanup_error {
        store.record_system_event(
            &profile.id,
            format!("PortMate: failed to consume one-time host key trust: {error}"),
        );
    }
    let summary = store.open_session(&profile.id)?;
    save_store(&state.store_path, &store)?;
    Ok(summary)
}

async fn establish_ssh_runtime(
    state: &AppState,
    profile: &SessionProfile,
    password: Option<String>,
    passphrase: Option<String>,
) -> Result<EstablishedSshRuntime, String> {
    establish_ssh_runtime_with_timeout_mode(
        state,
        profile,
        password,
        passphrase,
        SSH_CONNECT_TIMEOUT,
        None,
        false,
    )
    .await
}

async fn establish_ssh_reconnect_runtime(
    state: &AppState,
    profile: &SessionProfile,
) -> Result<EstablishedSshRuntime, String> {
    establish_ssh_runtime_with_timeout_mode(
        state,
        profile,
        None,
        None,
        SSH_CONNECT_TIMEOUT,
        None,
        true,
    )
    .await
}

#[cfg(test)]
async fn establish_ssh_runtime_with_timeout(
    state: &AppState,
    profile: &SessionProfile,
    password: Option<String>,
    passphrase: Option<String>,
    connect_timeout: Duration,
    agent_socket_path: Option<PathBuf>,
) -> Result<EstablishedSshRuntime, String> {
    establish_ssh_runtime_with_timeout_mode(
        state,
        profile,
        password,
        passphrase,
        connect_timeout,
        agent_socket_path,
        false,
    )
    .await
}

async fn establish_ssh_runtime_with_timeout_mode(
    state: &AppState,
    profile: &SessionProfile,
    password: Option<String>,
    passphrase: Option<String>,
    connect_timeout: Duration,
    agent_socket_path: Option<PathBuf>,
    enforce_profile_snapshot: bool,
) -> Result<EstablishedSshRuntime, String> {
    let mut ssh = match &profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => ssh.clone(),
        _ => return Err("profile is not SSH-backed".to_string()),
    };
    ssh.normalize_health_settings();

    let host = ssh.endpoint.host.trim().to_string();
    if host.is_empty() {
        return Err("SSH 主机不能为空".to_string());
    }
    let username = ssh.username.trim().to_string();
    if username.is_empty() {
        return Err("SSH 用户名不能为空；PortMate 不读取系统 ssh_config 的默认用户名".to_string());
    }

    let mut host_keys = {
        let store = state.store.lock().map_err(|error| error.to_string())?;
        store.host_keys.clone()
    };
    host_keys.keys.extend(ssh.trusted_host_keys.clone());
    let one_time_host_keys = one_time_host_keys_snapshot(state, &profile.id)?;
    host_keys.keys.extend(one_time_host_keys.clone());

    let observed_key = Arc::new(Mutex::new(None));
    let host_key_error = Arc::new(Mutex::new(None));
    let remote_forwards = Arc::new(Mutex::new(HashMap::new()));

    let config = Arc::new(ssh_client_config(&ssh));

    let (mut session, jump_handles) = connect_ssh_target(
        SshConnectRequest {
            config: Arc::clone(&config),
            store: Arc::clone(&state.store),
            store_path: state.store_path.clone(),
            profile,
            ssh: &ssh,
            host_keys,
            one_time_host_keys: one_time_host_keys.clone(),
            observed_key: Arc::clone(&observed_key),
            host_key_error: Arc::clone(&host_key_error),
            remote_forwards: Arc::clone(&remote_forwards),
            password: password.as_deref(),
            passphrase: passphrase.as_deref(),
            enforce_profile_snapshot,
        },
        connect_timeout,
        agent_socket_path.as_deref(),
    )
    .await?;

    let auth_method = authenticate_ssh_with_agent_socket(
        &mut session,
        ssh.clone(),
        username.clone(),
        password,
        passphrase,
        agent_socket_path,
    )
    .await
    .map_err(|error| format!("SSH 目标认证失败 {host}:{}: {error}", ssh.endpoint.port))?;

    persist_observed_host_key(
        &state.store,
        HostKeyPersistenceGuard {
            profile_id: &profile.id,
            expected_profile: enforce_profile_snapshot.then_some(profile),
        },
        &observed_key,
        &one_time_host_keys,
    )?;
    persist_store_arc(&state.store_path, &state.store)?;

    let channel = session
        .channel_open_session()
        .await
        .map_err(|error| format!("SSH 打开 session channel 失败: {error}"))?;
    channel
        .request_pty(
            true,
            &profile.terminal.term,
            u32::from(profile.terminal.cols),
            u32::from(profile.terminal.rows),
            0,
            0,
            &[],
        )
        .await
        .map_err(|error| format!("SSH 请求 PTY 失败: {error}"))?;
    apply_ssh_terminal_color_env(&channel).await;
    if ssh.agent_policy.forwarding {
        let _ = channel.agent_forward(false).await;
    }
    channel
        .request_shell(true)
        .await
        .map_err(|error| format!("SSH 请求 shell 失败: {error}"))?;

    let runtime_id = Uuid::new_v4().to_string();
    let (read_half, write_half) = channel.split();
    let writer = Arc::new(tokio::sync::Mutex::new(write_half));
    let (tap, _) = broadcast::channel(1024);
    let closed = Arc::new(AtomicBool::new(false));

    if matches!(profile.connection, ConnectionConfig::Tmux(_)) {
        let writer = writer.lock().await;
        writer
            .data(&b"tmux new-session -A -s portmate\r"[..])
            .await
            .map_err(|error| format!("Tmux attach 命令发送失败: {error}"))?;
    }

    Ok(EstablishedSshRuntime {
        runtime_id: runtime_id.clone(),
        runtime: SshRuntime {
            runtime_id: runtime_id.clone(),
            handle: Arc::new(tokio::sync::Mutex::new(session)),
            jump_handles,
            writer,
            tap: tap.clone(),
            remote_forwards,
            closed: Arc::clone(&closed),
        },
        tap,
        read_half,
        auth_method,
        closed,
    })
}

fn ssh_client_config(ssh: &SshConnection) -> client::Config {
    client::Config {
        keepalive_interval: ssh
            .keepalive_enabled
            .then(|| Duration::from_secs(ssh.keepalive_interval_seconds)),
        keepalive_max: ssh.keepalive_max_missed as usize,
        nodelay: true,
        ..Default::default()
    }
}

async fn connect_ssh_target(
    request: SshConnectRequest<'_>,
    connect_timeout: Duration,
    agent_socket_path: Option<&Path>,
) -> Result<
    (
        client::Handle<PortMateSshHandler>,
        Vec<Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>>,
    ),
    String,
> {
    let SshConnectRequest {
        config,
        store,
        store_path,
        profile,
        ssh,
        host_keys,
        one_time_host_keys,
        observed_key,
        host_key_error,
        remote_forwards,
        password,
        passphrase,
        enforce_profile_snapshot,
    } = request;
    let one_time_host_key_ids = one_time_host_keys
        .iter()
        .map(|key| key.id.clone())
        .collect::<Vec<_>>();

    let target_host = ssh.endpoint.host.trim().to_string();
    if target_host.is_empty() {
        return Err("SSH 主机不能为空".to_string());
    }
    if ssh.endpoint.port == 0 {
        return Err("SSH 端口必须在 1-65535 之间".to_string());
    }

    let target_handler = ssh_handler_for_endpoint(SshHandlerParams {
        profile_id: profile.id.clone(),
        host: target_host.clone(),
        port: ssh.endpoint.port,
        alias: ssh
            .host_key_policy
            .alias
            .clone()
            .filter(|value| !value.trim().is_empty())
            .or_else(|| Some(profile.id.clone())),
        policy: ssh.host_key_policy.clone(),
        host_keys: host_keys.clone(),
        one_time_host_key_ids: one_time_host_key_ids.clone(),
        observed_key: Arc::clone(&observed_key),
        host_key_error: Arc::clone(&host_key_error),
        remote_forwards: Arc::clone(&remote_forwards),
    });

    if ssh.jumps.is_empty() {
        let session = connect_ssh_transport(
            config,
            &target_host,
            ssh.endpoint.port,
            &ssh.proxy,
            target_handler,
            connect_timeout,
            "SSH",
        )
        .await;
        let session = match session {
            Ok(session) => session,
            Err(SshTransportConnectError::Timeout) => {
                return Err(format!("SSH 连接超时: {target_host}:{}", ssh.endpoint.port));
            }
            Err(SshTransportConnectError::Transport(error)) => return Err(error),
            Err(SshTransportConnectError::Handshake(error)) => {
                return Err(host_key_error
                    .lock()
                    .ok()
                    .and_then(|reason| reason.clone())
                    .unwrap_or_else(|| format!("SSH 握手失败: {error}")));
            }
        };
        return Ok((session, Vec::new()));
    }

    let mut jump_sessions: Vec<client::Handle<PortMateSshHandler>> = Vec::new();
    for (index, jump) in ssh.jumps.iter().enumerate() {
        let (jump_host, jump_port, jump_username) = jump_endpoint_details(jump, index)?;
        let jump_policy = jump_host_key_policy(ssh, jump);
        let observed_jump_key = Arc::new(Mutex::new(None));
        let jump_key_error = Arc::new(Mutex::new(None));
        let jump_ssh = jump_ssh_connection(ssh, jump, jump_policy.clone());
        let jump_handler = ssh_handler_for_endpoint(SshHandlerParams {
            profile_id: profile.id.clone(),
            host: jump_host.clone(),
            port: jump_port,
            alias: jump_policy.alias.clone(),
            policy: jump_ssh.host_key_policy.clone(),
            host_keys: host_keys.clone(),
            one_time_host_key_ids: one_time_host_key_ids.clone(),
            observed_key: Arc::clone(&observed_jump_key),
            host_key_error: Arc::clone(&jump_key_error),
            remote_forwards: Arc::new(Mutex::new(HashMap::new())),
        });
        let mut jump_session = if let Some(previous_jump) = jump_sessions.last_mut() {
            let jump_channel = match previous_jump
                .channel_open_direct_tcpip(jump_host.clone(), u32::from(jump_port), "127.0.0.1", 0)
                .await
            {
                Ok(channel) => channel,
                Err(error) => {
                    disconnect_jump_sessions(jump_sessions, "PortMate jump chain channel failed")
                        .await;
                    return Err(format!(
                        "Jump Host 第 {} 跳打开 direct-tcpip 到 {jump_host}:{jump_port} 失败: {error}",
                        index + 1
                    ));
                }
            };
            match tokio::time::timeout(
                connect_timeout,
                client::connect_stream(config.clone(), jump_channel.into_stream(), jump_handler),
            )
            .await
            {
                Ok(Ok(session)) => session,
                Err(_) => {
                    disconnect_jump_sessions(jump_sessions, "PortMate jump chain connect timeout")
                        .await;
                    return Err(format!(
                        "Jump Host 第 {} 跳连接超时: {jump_host}:{jump_port}",
                        index + 1
                    ));
                }
                Ok(Err(error)) => {
                    let reason = jump_key_error
                        .lock()
                        .ok()
                        .and_then(|reason| reason.clone())
                        .unwrap_or_else(|| error.to_string());
                    disconnect_jump_sessions(jump_sessions, "PortMate jump chain handshake failed")
                        .await;
                    return Err(format!(
                        "Jump Host 第 {} 跳 SSH 握手失败 {jump_host}:{jump_port}: {reason}",
                        index + 1
                    ));
                }
            }
        } else {
            let jump_transport_label = format!("Jump Host 第 {} 跳", index + 1);
            match connect_ssh_transport(
                config.clone(),
                &jump_host,
                jump_port,
                &ssh.proxy,
                jump_handler,
                connect_timeout,
                &jump_transport_label,
            )
            .await
            {
                Ok(session) => session,
                Err(SshTransportConnectError::Timeout) => {
                    return Err(format!(
                        "Jump Host 第 {} 跳连接超时: {jump_host}:{jump_port}",
                        index + 1
                    ));
                }
                Err(SshTransportConnectError::Transport(error)) => return Err(error),
                Err(SshTransportConnectError::Handshake(error)) => {
                    let reason = jump_key_error
                        .lock()
                        .ok()
                        .and_then(|reason| reason.clone())
                        .unwrap_or(error);
                    return Err(format!(
                        "Jump Host 第 {} 跳 SSH 握手失败 {jump_host}:{jump_port}: {reason}",
                        index + 1
                    ));
                }
            }
        };

        if let Err(error) = authenticate_ssh_with_agent_socket(
            &mut jump_session,
            jump_ssh,
            jump_username,
            jump_runtime_credential(password, jump.password_secret_ref.as_deref()),
            jump_runtime_credential(passphrase, jump.passphrase_secret_ref.as_deref()),
            agent_socket_path.map(Path::to_path_buf),
        )
        .await
        {
            disconnect_jump_sessions(jump_sessions, "PortMate jump authentication failed").await;
            let _ = jump_session
                .disconnect(
                    Disconnect::ByApplication,
                    "PortMate jump authentication failed",
                    "en",
                )
                .await;
            return Err(format!(
                "Jump Host 第 {} 跳认证失败 {jump_host}:{jump_port}: {error}",
                index + 1
            ));
        }
        if let Err(error) = persist_observed_host_key_with_policy(
            &store,
            &store_path,
            HostKeyPersistenceGuard {
                profile_id: &profile.id,
                expected_profile: enforce_profile_snapshot.then_some(profile),
            },
            &jump_policy,
            &observed_jump_key,
            &one_time_host_keys,
            &format!("Jump Host #{}", index + 1),
        ) {
            disconnect_jump_sessions(jump_sessions, "PortMate jump host key rejected").await;
            let _ = jump_session
                .disconnect(
                    Disconnect::ByApplication,
                    "PortMate jump host key rejected",
                    "en",
                )
                .await;
            return Err(format!(
                "Jump Host 第 {} 跳 host key 处理失败 {jump_host}:{jump_port}: {error}",
                index + 1
            ));
        }
        jump_sessions.push(jump_session);
    }

    let jump_channel = match jump_sessions
        .last_mut()
        .expect("non-empty jumps should create jump sessions")
        .channel_open_direct_tcpip(
            target_host.clone(),
            u32::from(ssh.endpoint.port),
            "127.0.0.1",
            0,
        )
        .await
    {
        Ok(channel) => channel,
        Err(error) => {
            disconnect_jump_sessions(jump_sessions, "PortMate jump target channel failed").await;
            return Err(format!(
                "Jump Host 打开 direct-tcpip 到 {target_host}:{} 失败: {error}",
                ssh.endpoint.port
            ));
        }
    };
    let target_session = match tokio::time::timeout(
        connect_timeout,
        client::connect_stream(config, jump_channel.into_stream(), target_handler),
    )
    .await
    {
        Ok(Ok(session)) => session,
        Err(_) => {
            disconnect_jump_sessions(jump_sessions, "PortMate jump target connect timeout").await;
            return Err(format!(
                "SSH 经 Jump Host 连接超时: {target_host}:{}",
                ssh.endpoint.port
            ));
        }
        Ok(Err(error)) => {
            disconnect_jump_sessions(jump_sessions, "PortMate jump target handshake failed").await;
            return Err(host_key_error
                .lock()
                .ok()
                .and_then(|reason| reason.clone())
                .unwrap_or_else(|| format!("SSH 经 Jump Host 握手失败: {error}")));
        }
    };

    Ok((
        target_session,
        jump_sessions
            .into_iter()
            .map(|session| Arc::new(tokio::sync::Mutex::new(session)))
            .collect(),
    ))
}

fn jump_endpoint_details(
    jump: &portmate_core::JumpHop,
    index: usize,
) -> Result<(String, u16, String), String> {
    let label = format!("Jump Host 第 {} 跳", index + 1);
    let host = jump.host.trim().to_string();
    if host.is_empty() {
        return Err(format!("{label} 主机不能为空"));
    }
    if jump.port == 0 {
        return Err(format!("{label} 端口必须在 1-65535 之间"));
    }
    let username = jump.username.trim().to_string();
    if username.is_empty() {
        return Err(format!("{label} 用户名不能为空"));
    }
    Ok((host, jump.port, username))
}

async fn disconnect_jump_sessions(
    jump_sessions: Vec<client::Handle<PortMateSshHandler>>,
    reason: &str,
) {
    for session in jump_sessions {
        let _ = session
            .disconnect(Disconnect::ByApplication, reason, "en")
            .await;
    }
}

fn ssh_handler_for_endpoint(params: SshHandlerParams) -> PortMateSshHandler {
    PortMateSshHandler {
        profile_id: params.profile_id,
        host: params.host,
        port: params.port,
        alias: params.alias,
        policy: params.policy,
        host_keys: params.host_keys,
        one_time_host_key_ids: params.one_time_host_key_ids,
        observed_key: params.observed_key,
        host_key_error: params.host_key_error,
        remote_forwards: params.remote_forwards,
    }
}

fn trusted_host_key_allowed(
    policy: &portmate_core::HostKeyPolicy,
    matched_key_id: &str,
    one_time_host_key_ids: &[String],
) -> bool {
    policy.mode != HostKeyMode::AskEveryTime
        || one_time_host_key_ids
            .iter()
            .any(|key_id| key_id == matched_key_id)
}

fn jump_host_key_policy(
    ssh: &SshConnection,
    jump: &portmate_core::JumpHop,
) -> portmate_core::HostKeyPolicy {
    let default_alias = format!("jump:{}:{}", jump.host.trim(), jump.port);
    let mut policy = if let Some(custom) = jump.host_key_policy.clone() {
        custom
    } else {
        let mut inherited = ssh.host_key_policy.clone();
        inherited.alias = Some(default_alias.clone());
        inherited.trust_scope = HostKeyScope::Profile;
        inherited
    };
    policy.alias = policy
        .alias
        .as_deref()
        .map(str::trim)
        .filter(|alias| !alias.is_empty())
        .map(str::to_string)
        .or(Some(default_alias));
    policy
}

fn jump_ssh_connection(
    ssh: &SshConnection,
    jump: &portmate_core::JumpHop,
    host_key_policy: portmate_core::HostKeyPolicy,
) -> SshConnection {
    let mut identity_refs = ssh.identity_refs.clone();
    if let Some(identity_ref) = jump
        .identity_ref
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        identity_refs.retain(|identity| identity.id == identity_ref);
    }
    SshConnection {
        endpoint: portmate_core::HostEndpoint {
            host: jump.host.trim().to_string(),
            port: jump.port,
        },
        username: jump.username.trim().to_string(),
        reconnect: ssh.reconnect,
        reconnect_delay_ms: ssh.reconnect_delay_ms,
        keepalive_enabled: ssh.keepalive_enabled,
        keepalive_interval_seconds: ssh.keepalive_interval_seconds,
        keepalive_max_missed: ssh.keepalive_max_missed,
        proxy: ssh.proxy.clone(),
        password_secret_ref: jump
            .password_secret_ref
            .as_ref()
            .map(|value| value.trim())
            .filter(|value| !value.is_empty())
            .map(str::to_string)
            .or_else(|| ssh.password_secret_ref.clone()),
        passphrase_secret_ref: jump
            .passphrase_secret_ref
            .as_ref()
            .map(|value| value.trim())
            .filter(|value| !value.is_empty())
            .map(str::to_string)
            .or_else(|| ssh.passphrase_secret_ref.clone()),
        host_key_policy,
        trusted_host_keys: Vec::new(),
        identity_policy: ssh.identity_policy.clone(),
        identity_refs,
        agent_policy: ssh.agent_policy.clone(),
        jumps: Vec::new(),
        tunnels: Vec::new(),
    }
}

fn jump_runtime_credential(
    inherited: Option<&str>,
    jump_secret_ref: Option<&str>,
) -> Option<String> {
    if jump_secret_ref.is_some_and(|value| !value.trim().is_empty()) {
        None
    } else {
        inherited
            .filter(|value| !value.is_empty())
            .map(str::to_string)
    }
}

fn open_shell_session(state: &AppState, profile: SessionProfile) -> Result<SessionSummary, String> {
    let shell = match &profile.connection {
        ConnectionConfig::Shell(shell) => shell.clone(),
        _ => return Err("profile is not shell-backed".to_string()),
    };
    let program = if shell.program.trim().is_empty() {
        default_shell_program()
    } else {
        shell.program.trim().to_string()
    };

    if let Some(existing) = {
        let mut connections = state.shell.lock().map_err(|error| error.to_string())?;
        connections.remove(&profile.id)
    } {
        existing.closed.store(true, Ordering::SeqCst);
        if let Ok(mut child) = existing.child.lock() {
            let _ = child.kill();
        }
    }

    let pty_system = native_pty_system();
    let pair = pty_system
        .openpty(PtySize {
            rows: profile.terminal.rows,
            cols: profile.terminal.cols,
            pixel_width: 0,
            pixel_height: 0,
        })
        .map_err(|error| format!("Shell PTY 打开失败: {error}"))?;

    let mut command = CommandBuilder::new(&program);
    command.args(shell.args.iter());
    apply_shell_terminal_color_env(&mut command, profile.terminal.term.as_str());
    if let Some(cwd) = shell
        .cwd
        .as_deref()
        .filter(|value| !value.trim().is_empty())
    {
        command.cwd(cwd);
    }

    let child = pair
        .slave
        .spawn_command(command)
        .map_err(|error| format!("Shell 启动失败 {program}: {error}"))?;
    drop(pair.slave);

    let reader = pair
        .master
        .try_clone_reader()
        .map_err(|error| format!("Shell PTY reader 创建失败: {error}"))?;
    let writer = pair
        .master
        .take_writer()
        .map_err(|error| format!("Shell PTY writer 创建失败: {error}"))?;

    let runtime_id = Uuid::new_v4().to_string();
    let closed = Arc::new(AtomicBool::new(false));
    let (tap, _) = broadcast::channel(1024);
    let child = Arc::new(Mutex::new(child));
    let master = Arc::new(Mutex::new(pair.master));
    let writer = Arc::new(Mutex::new(writer));
    {
        let mut connections = state.shell.lock().map_err(|error| error.to_string())?;
        connections.insert(
            profile.id.clone(),
            ShellRuntime {
                runtime_id: runtime_id.clone(),
                master,
                writer,
                tap: tap.clone(),
                child: Arc::clone(&child),
                closed: Arc::clone(&closed),
            },
        );
    }

    if let Err(error) = std::thread::Builder::new()
        .name(format!("portmate-shell-{}", profile.id))
        .spawn(read_shell_pty(ShellReadTask {
            io: state.session_io(),
            session_id: profile.id.clone(),
            runtime_id,
            program: program.clone(),
            tap,
            closed,
            child,
            reader,
        }))
    {
        let mut connections = state.shell.lock().map_err(|error| error.to_string())?;
        connections.remove(&profile.id);
        return Err(format!("Shell PTY 读取线程启动失败: {error}"));
    }

    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    store.record_system_event(&profile.id, format!("PortMate: shell started ({program})"));
    let summary = store.open_session(&profile.id)?;
    save_store(&state.store_path, &store)?;
    Ok(summary)
}

fn tcp_connection_details(
    profile: &SessionProfile,
) -> Result<(TcpConnection, &'static str), String> {
    let (mut tcp, label) = match &profile.connection {
        ConnectionConfig::Tcp(tcp) => (tcp.clone(), "TCP"),
        ConnectionConfig::Telnet(tcp) => (tcp.clone(), "Telnet"),
        _ => return Err("profile is not TCP/Telnet-backed".to_string()),
    };
    tcp.host = tcp.host.trim().to_string();
    tcp.normalize_health_settings();
    if tcp.host.is_empty() {
        return Err(format!("{label} 主机不能为空"));
    }
    if tcp.port == 0 {
        return Err(format!("{label} 端口不能为空"));
    }
    Ok((tcp, label))
}

fn tcp_reconnect_enabled(profile: &SessionProfile) -> bool {
    match &profile.connection {
        ConnectionConfig::Tcp(tcp) | ConnectionConfig::Telnet(tcp) => tcp.reconnect,
        _ => false,
    }
}

fn tcp_reconnect_attempt_matches_profile(
    attempt: &SessionProfile,
    latest: &SessionProfile,
) -> bool {
    let attempt = normalize_session_profile(attempt.clone());
    let latest = normalize_session_profile(latest.clone());
    tcp_reconnect_enabled(&latest)
        && attempt.connection == latest.connection
        && attempt.terminal == latest.terminal
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TcpReconnectProfileState {
    Current,
    Changed,
    Disabled,
}

fn tcp_reconnect_profile_state(
    store: &SessionStore,
    session_id: &str,
    attempt: &SessionProfile,
) -> TcpReconnectProfileState {
    let Some(latest) = store.profile(session_id).map(normalize_session_profile) else {
        return TcpReconnectProfileState::Disabled;
    };
    if !tcp_reconnect_enabled(&latest) {
        return TcpReconnectProfileState::Disabled;
    }
    if !tcp_reconnect_attempt_matches_profile(attempt, &latest) {
        return TcpReconnectProfileState::Changed;
    }
    TcpReconnectProfileState::Current
}

fn latest_tcp_reconnect_profile(
    state: &AppState,
    session_id: &str,
) -> Result<Option<SessionProfile>, String> {
    let store = state.store.lock().map_err(|error| error.to_string())?;
    let Some(profile) = store.profile(session_id) else {
        return Ok(None);
    };
    let profile = normalize_session_profile(profile);
    Ok(tcp_reconnect_enabled(&profile).then_some(profile))
}

async fn connect_tcp_socket(tcp: &TcpConnection, label: &str) -> Result<TcpStream, String> {
    let stream = tokio::time::timeout(
        Duration::from_secs(15),
        connect_target_stream(&tcp.host, tcp.port, &tcp.proxy, label),
    )
    .await
    .map_err(|_| format!("{label} 连接超时: {}:{}", tcp.host, tcp.port))??;
    configure_tcp_socket(&stream, label, tcp)?;
    Ok(stream)
}

fn configure_tcp_socket(
    stream: &TcpStream,
    label: &str,
    tcp: &TcpConnection,
) -> Result<(), String> {
    stream
        .set_nodelay(true)
        .map_err(|error| format!("{label} 设置 TCP_NODELAY 失败: {error}"))?;
    let socket = SockRef::from(stream);
    if !tcp.keepalive_enabled {
        return socket
            .set_keepalive(false)
            .map_err(|error| format!("{label} 关闭 TCP keepalive 失败: {error}"));
    }
    socket
        .set_tcp_keepalive(&tcp_keepalive_config(tcp))
        .map_err(|error| format!("{label} 设置 TCP keepalive 失败: {error}"))
}

fn tcp_keepalive_config(tcp: &TcpConnection) -> TcpKeepalive {
    let keepalive = TcpKeepalive::new().with_time(Duration::from_secs(tcp.keepalive_idle_seconds));
    #[cfg(any(
        target_os = "android",
        target_os = "dragonfly",
        target_os = "freebsd",
        target_os = "fuchsia",
        target_os = "illumos",
        target_os = "ios",
        target_os = "visionos",
        target_os = "linux",
        target_os = "macos",
        target_os = "netbsd",
        target_os = "tvos",
        target_os = "watchos",
        target_os = "windows",
        target_os = "cygwin",
        all(target_os = "wasi", not(target_env = "p1")),
    ))]
    let keepalive = keepalive.with_interval(Duration::from_secs(tcp.keepalive_interval_seconds));
    #[cfg(any(
        target_os = "android",
        target_os = "dragonfly",
        target_os = "freebsd",
        target_os = "fuchsia",
        target_os = "illumos",
        target_os = "ios",
        target_os = "visionos",
        target_os = "linux",
        target_os = "macos",
        target_os = "netbsd",
        target_os = "tvos",
        target_os = "watchos",
        target_os = "windows",
        target_os = "cygwin",
        all(target_os = "wasi", not(target_env = "p1")),
    ))]
    let keepalive = keepalive.with_retries(tcp.keepalive_retries);
    keepalive
}

fn tcp_reconnect_delay(profile: &SessionProfile) -> Duration {
    match &profile.connection {
        ConnectionConfig::Tcp(tcp) | ConnectionConfig::Telnet(tcp) => {
            Duration::from_millis(tcp.reconnect_delay_ms)
        }
        _ => Duration::from_millis(portmate_core::DEFAULT_TCP_RECONNECT_DELAY_MS),
    }
}

async fn open_tcp_session(
    state: &AppState,
    profile: SessionProfile,
) -> Result<SessionSummary, String> {
    let (tcp, label) = tcp_connection_details(&profile)?;
    if let Some(existing) = {
        let mut connections = state.tcp.lock().map_err(|error| error.to_string())?;
        connections.remove(&profile.id)
    } {
        existing.closed.store(true, Ordering::SeqCst);
        let mut writer = existing.writer.lock().await;
        let _ = writer.shutdown().await;
    }

    let stream = connect_tcp_socket(&tcp, label).await?;

    let runtime_id = Uuid::new_v4().to_string();
    let (read_half, write_half) = stream.into_split();
    let writer = Arc::new(tokio::sync::Mutex::new(write_half));
    let (tap, _) = broadcast::channel(1024);
    let closed = Arc::new(AtomicBool::new(false));
    let telnet = TelnetRuntimeState::from_profile(&profile);
    {
        let mut connections = state.tcp.lock().map_err(|error| error.to_string())?;
        connections.insert(
            profile.id.clone(),
            TcpRuntime {
                runtime_id: runtime_id.clone(),
                writer: Arc::clone(&writer),
                tap: tap.clone(),
                closed: Arc::clone(&closed),
                telnet: telnet.as_ref().map(Arc::clone),
            },
        );
    }

    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    store.record_system_event(&profile.id, format!("PortMate: {label} socket connected"));
    let summary = store.open_session(&profile.id)?;
    save_store(&state.store_path, &store)?;
    drop(store);

    tauri::async_runtime::spawn(read_tcp_stream(TcpReadTask {
        state: state.clone(),
        profile,
        runtime_id,
        label: label.to_string(),
        tap,
        writer,
        read_half,
        closed,
        telnet,
    }));
    Ok(summary)
}

fn serial_connection_details(
    profile: &SessionProfile,
) -> Result<(portmate_core::SerialConnection, String), String> {
    let mut serial = match &profile.connection {
        ConnectionConfig::Serial(serial) => serial.clone(),
        _ => return Err("profile is not serial-backed".to_string()),
    };
    serial.normalize_health_settings();
    let port_name = serial.port.trim().to_string();
    if port_name.is_empty() {
        return Err("串口不能为空".to_string());
    }
    Ok((serial, port_name))
}

fn serial_reconnect_delay(profile: &SessionProfile) -> Duration {
    match &profile.connection {
        ConnectionConfig::Serial(serial) => Duration::from_millis(serial.reconnect_delay_ms.clamp(
            portmate_core::MIN_SERIAL_RECONNECT_DELAY_MS,
            portmate_core::MAX_SERIAL_RECONNECT_DELAY_MS,
        )),
        _ => Duration::from_millis(portmate_core::DEFAULT_SERIAL_RECONNECT_DELAY_MS),
    }
}

fn serial_reconnect_enabled(profile: &SessionProfile) -> bool {
    match &profile.connection {
        ConnectionConfig::Serial(serial) => serial.reconnect,
        _ => false,
    }
}

fn serial_reconnect_attempt_matches_profile(
    attempt: &SessionProfile,
    latest: &SessionProfile,
) -> bool {
    let attempt = normalize_session_profile(attempt.clone());
    let latest = normalize_session_profile(latest.clone());
    serial_reconnect_enabled(&latest) && attempt.connection == latest.connection
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SerialReconnectProfileState {
    Current,
    Changed,
    Disabled,
}

fn serial_reconnect_profile_state(
    store: &SessionStore,
    session_id: &str,
    attempt: &SessionProfile,
) -> SerialReconnectProfileState {
    let Some(latest) = store.profile(session_id).map(normalize_session_profile) else {
        return SerialReconnectProfileState::Disabled;
    };
    if !serial_reconnect_enabled(&latest) {
        return SerialReconnectProfileState::Disabled;
    }
    if !serial_reconnect_attempt_matches_profile(attempt, &latest) {
        return SerialReconnectProfileState::Changed;
    }
    SerialReconnectProfileState::Current
}

fn latest_serial_reconnect_profile(
    io: &SessionIo,
    session_id: &str,
) -> Result<Option<SessionProfile>, String> {
    let store = io.store.lock().map_err(|error| error.to_string())?;
    let Some(profile) = store.profile(session_id) else {
        return Ok(None);
    };
    let profile = normalize_session_profile(profile);
    Ok(serial_reconnect_enabled(&profile).then_some(profile))
}

fn open_configured_serial_port(
    serial: &portmate_core::SerialConnection,
    port_name: &str,
) -> Result<SerialPortPair, String> {
    let mut port = serialport::new(port_name, serial.baud_rate)
        .data_bits(serial_data_bits(serial.data_bits))
        .stop_bits(serial_stop_bits(serial.stop_bits))
        .parity(serial_parity(&serial.parity))
        .flow_control(serial_flow_control(&serial.flow_control))
        .timeout(Duration::from_millis(100))
        .open()
        .map_err(|error| format!("串口打开失败 {port_name}: {error}"))?;
    if let Err(error) = port.write_data_terminal_ready(serial.dtr) {
        if serial.dtr {
            return Err(format!("设置 DTR 失败: {error}"));
        }
        eprintln!("PortMate: serial device does not support clearing DTR: {error}");
    }
    if let Err(error) = port.write_request_to_send(serial.rts) {
        if serial.rts {
            return Err(format!("设置 RTS 失败: {error}"));
        }
        eprintln!("PortMate: serial device does not support clearing RTS: {error}");
    }

    let reader = port
        .try_clone()
        .map_err(|error| format!("串口 reader 克隆失败: {error}"))?;
    Ok((port, reader))
}

fn open_serial_session(
    state: &AppState,
    profile: SessionProfile,
) -> Result<SessionSummary, String> {
    let (serial, port_name) = serial_connection_details(&profile)?;

    if let Some(existing) = {
        let mut connections = state.serial.lock().map_err(|error| error.to_string())?;
        connections.remove(&profile.id)
    } {
        existing.closed.store(true, Ordering::SeqCst);
    }

    let (port, reader) = open_configured_serial_port(&serial, &port_name)?;
    let runtime_id = Uuid::new_v4().to_string();
    let closed = Arc::new(AtomicBool::new(false));
    let (tap, _) = broadcast::channel(1024);
    let writer = Arc::new(Mutex::new(port));
    let capture = serial_capture_for_session(&state.serial_captures, &profile.id)?;
    {
        let mut connections = state.serial.lock().map_err(|error| error.to_string())?;
        connections.insert(
            profile.id.clone(),
            SerialRuntime {
                runtime_id: runtime_id.clone(),
                writer: Some(writer),
                tap: tap.clone(),
                closed: Arc::clone(&closed),
                capture: Arc::clone(&capture),
            },
        );
    }

    if let Err(error) = spawn_serial_reader(SerialReadTask {
        io: state.session_io(),
        profile: profile.clone(),
        runtime_id,
        port_name: port_name.clone(),
        tap,
        closed,
        reader,
        capture,
        receive_idle_timeout: serial
            .receive_idle_timeout_enabled
            .then(|| Duration::from_secs(serial.receive_idle_timeout_seconds)),
    }) {
        let mut connections = state.serial.lock().map_err(|error| error.to_string())?;
        connections.remove(&profile.id);
        return Err(format!("串口读取线程启动失败: {error}"));
    }

    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    store.record_system_event(
        &profile.id,
        format!(
            "PortMate: serial port connected ({port_name}, {} baud)",
            serial.baud_rate
        ),
    );
    let summary = store.open_session(&profile.id)?;
    save_store(&state.store_path, &store)?;
    Ok(summary)
}

async fn authenticate_ssh(
    session: &mut client::Handle<PortMateSshHandler>,
    ssh: SshConnection,
    username: String,
    password: Option<String>,
    passphrase: Option<String>,
) -> Result<AuthMethod, String> {
    authenticate_ssh_with_agent_socket(session, ssh, username, password, passphrase, None).await
}

async fn authenticate_ssh_with_agent_socket(
    session: &mut client::Handle<PortMateSshHandler>,
    ssh: SshConnection,
    username: String,
    password: Option<String>,
    passphrase: Option<String>,
    agent_socket_path: Option<PathBuf>,
) -> Result<AuthMethod, String> {
    let auth_order = ordered_auth_methods(&ssh);
    let mut attempted = Vec::new();
    let mut key_errors = Vec::new();
    let saved_password = if password
        .as_deref()
        .filter(|value| !value.is_empty())
        .is_none()
    {
        read_optional_secret_ref(ssh.password_secret_ref.as_deref(), "SSH password")?
    } else {
        None
    };
    let saved_passphrase = if passphrase
        .as_deref()
        .filter(|value| !value.is_empty())
        .is_none()
    {
        read_optional_secret_ref(
            ssh.passphrase_secret_ref.as_deref(),
            "SSH private-key passphrase",
        )?
    } else {
        None
    };
    let effective_password = password
        .filter(|value| !value.is_empty())
        .or(saved_password);
    let effective_passphrase = passphrase
        .filter(|value| !value.is_empty())
        .or(saved_passphrase);
    let mut agent_attempted = false;

    for method in auth_order {
        match method {
            AuthMethod::PublicKey => {
                if ssh.agent_policy.enabled
                    && !agent_attempted
                    && !ssh.identity_policy.identities_only
                    && ssh.agent_policy.offer_mode
                        == portmate_core::AgentOfferMode::BeforeProfileKeys
                {
                    attempted.push("agent(before-profile-keys)");
                    agent_attempted = true;
                    match authenticate_with_agent(
                        session,
                        username.clone(),
                        ssh.identity_policy.identities_only,
                        ssh.agent_policy.offer_mode,
                        ssh.identity_refs.clone(),
                        agent_socket_path.clone(),
                    )
                    .await
                    {
                        Ok(true) => return Ok(AuthMethod::PublicKey),
                        Ok(false) => {}
                        Err(error) => key_errors.push(error),
                    }
                }

                let identities = ssh
                    .identity_refs
                    .iter()
                    .filter(|identity| {
                        matches!(
                            identity.source,
                            IdentitySource::SystemFile | IdentitySource::ProfileVault
                        )
                    })
                    .collect::<Vec<_>>();
                if !identities.is_empty() {
                    attempted.push("publickey");
                    let rsa_hash = session
                        .best_supported_rsa_hash()
                        .await
                        .map_err(|error| {
                            format!("SSH publickey 认证准备失败，无法查询 RSA 签名算法: {error}")
                        })?
                        .flatten();
                    for identity in identities {
                        let label = identity.label.clone();
                        let key = match load_identity_private_key(
                            identity,
                            effective_passphrase.as_deref(),
                        ) {
                            Ok(Some(key)) => key,
                            Ok(None) => continue,
                            Err(error) => {
                                key_errors.push(format!("{label}: {error}"));
                                continue;
                            }
                        };
                        let result = match session
                            .authenticate_publickey(
                                username.clone(),
                                PrivateKeyWithHashAlg::new(Arc::new(key), rsa_hash),
                            )
                            .await
                        {
                            Ok(result) => result,
                            Err(error) => {
                                key_errors.push(format!("{label}: 认证请求失败: {error}"));
                                break;
                            }
                        };
                        if result.success() {
                            return Ok(AuthMethod::PublicKey);
                        }
                        key_errors.push(format!("{label}: 被服务器拒绝"));
                    }
                }

                if ssh.agent_policy.enabled
                    && !agent_attempted
                    && (ssh.agent_policy.offer_mode
                        == portmate_core::AgentOfferMode::AfterProfileKeys
                        || ssh
                            .identity_refs
                            .iter()
                            .any(|identity| identity.source == IdentitySource::Agent))
                    && (!ssh.identity_policy.identities_only
                        || ssh
                            .identity_refs
                            .iter()
                            .any(|identity| identity.source == IdentitySource::Agent))
                {
                    attempted.push("agent(after-profile-keys)");
                    agent_attempted = true;
                    match authenticate_with_agent(
                        session,
                        username.clone(),
                        ssh.identity_policy.identities_only,
                        ssh.agent_policy.offer_mode,
                        ssh.identity_refs.clone(),
                        agent_socket_path.clone(),
                    )
                    .await
                    {
                        Ok(true) => return Ok(AuthMethod::PublicKey),
                        Ok(false) => {}
                        Err(error) => key_errors.push(error),
                    }
                }
            }
            AuthMethod::KeyboardInteractive => {
                let Some(password) = effective_password.clone() else {
                    continue;
                };
                attempted.push("keyboard-interactive");
                if authenticate_keyboard_interactive(session, username.clone(), password).await? {
                    return Ok(AuthMethod::KeyboardInteractive);
                }
            }
            AuthMethod::Password => {
                let Some(password) = effective_password.clone() else {
                    continue;
                };
                attempted.push("password");
                let result = session
                    .authenticate_password(username.clone(), password)
                    .await
                    .map_err(|error| format!("SSH password 认证失败: {error}"))?;
                if result.success() {
                    return Ok(AuthMethod::Password);
                }
            }
            AuthMethod::None => {
                attempted.push("none");
                let result = session
                    .authenticate_none(username.clone())
                    .await
                    .map_err(|error| format!("SSH none 认证失败: {error}"))?;
                if result.success() {
                    return Ok(AuthMethod::None);
                }
            }
            AuthMethod::GssapiWithMic => {
                attempted.push("gssapi-with-mic(unsupported)");
            }
        }
    }

    let mut message = if attempted.is_empty() {
        "SSH 认证失败：没有可尝试的认证方式。请配置 identityRefs 或在连接时输入密码。".to_string()
    } else {
        format!("SSH 认证失败，已尝试: {}", attempted.join(", "))
    };
    if !key_errors.is_empty() {
        message.push_str(&format!("；密钥详情: {}", key_errors.join(" | ")));
    }
    if ssh.agent_policy.enabled && ssh.identity_policy.identities_only {
        message.push_str("；当前按 IdentitiesOnly 处理，不会遍历系统 ssh-agent 的全部密钥");
    }
    Err(message)
}

async fn authenticate_with_agent(
    session: &mut client::Handle<PortMateSshHandler>,
    username: String,
    identities_only: bool,
    offer_mode: portmate_core::AgentOfferMode,
    identity_refs: Vec<IdentityRef>,
    agent_socket_path: Option<PathBuf>,
) -> Result<bool, String> {
    if offer_mode == portmate_core::AgentOfferMode::Disabled {
        return Ok(false);
    }

    let agent_refs = identity_refs
        .into_iter()
        .filter(|identity| identity.source == IdentitySource::Agent)
        .map(|identity| AgentIdentityFilter {
            label: identity.label,
            fingerprint_sha256: identity.fingerprint_sha256,
            path: identity.path,
        })
        .collect::<Vec<_>>();
    let allow_unfiltered_agent = !identities_only && agent_refs.is_empty();
    let identities = list_ssh_agent_identities_on_thread(agent_socket_path.clone()).await?;
    if identities.is_empty() {
        return Ok(false);
    }

    let rsa_hash = session
        .best_supported_rsa_hash()
        .await
        .map_err(|error| format!("SSH 查询 RSA 签名算法失败: {error}"))?
        .flatten();
    let mut tried = 0_usize;
    let max_agent_attempts = if allow_unfiltered_agent {
        6
    } else {
        usize::MAX
    };
    let mut signer = PortMateAgentSigner {
        socket_path: agent_socket_path,
    };

    for identity in identities {
        if !allow_unfiltered_agent && !agent_identity_matches(&identity, &agent_refs) {
            continue;
        }
        if tried >= max_agent_attempts {
            break;
        }
        tried += 1;
        let public_key = identity.public_key().into_owned();
        let result = session
            .authenticate_publickey_with(username.clone(), public_key, rsa_hash, &mut signer)
            .await
            .map_err(|error| format!("ssh-agent 认证失败: {error}"))?;
        if result.success() {
            return Ok(true);
        }
    }

    Ok(false)
}

async fn list_ssh_agent_identities_on_thread(
    socket_path: Option<PathBuf>,
) -> Result<Vec<AgentIdentity>, String> {
    let (sender, receiver) = tokio::sync::oneshot::channel();
    std::thread::Builder::new()
        .name("portmate-ssh-agent-list".to_string())
        .spawn(move || {
            let result = run_agent_runtime(async {
                let mut agent = connect_ssh_agent(socket_path.as_deref()).await?;
                agent
                    .request_identities()
                    .await
                    .map_err(|error| format!("读取 ssh-agent identities 失败: {error}"))
            });
            let _ = sender.send(result);
        })
        .map_err(|error| format!("启动 ssh-agent 查询线程失败: {error}"))?;
    receiver
        .await
        .map_err(|error| format!("ssh-agent 查询线程未返回: {error}"))?
}

async fn sign_with_ssh_agent_on_thread(
    identity: AgentIdentity,
    hash_alg: Option<HashAlg>,
    data: Vec<u8>,
    socket_path: Option<PathBuf>,
) -> Result<Vec<u8>, String> {
    let (sender, receiver) = tokio::sync::oneshot::channel();
    std::thread::Builder::new()
        .name("portmate-ssh-agent-sign".to_string())
        .spawn(move || {
            let result = run_agent_runtime(async {
                let mut agent = connect_ssh_agent(socket_path.as_deref()).await?;
                agent
                    .sign_request(&identity, hash_alg, data)
                    .await
                    .map_err(|error| format!("ssh-agent 签名失败: {error}"))
            });
            let _ = sender.send(result);
        })
        .map_err(|error| format!("启动 ssh-agent 签名线程失败: {error}"))?;
    receiver
        .await
        .map_err(|error| format!("ssh-agent 签名线程未返回: {error}"))?
}

fn run_agent_runtime<T>(
    future: impl std::future::Future<Output = Result<T, String>>,
) -> Result<T, String> {
    tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .map_err(|error| format!("创建 ssh-agent runtime 失败: {error}"))?
        .block_on(future)
}

fn agent_identity_matches(identity: &AgentIdentity, refs: &[AgentIdentityFilter]) -> bool {
    let comment = identity.comment();
    let public_key = identity.public_key();
    let fingerprint = compute_ssh_sha256_fingerprint(&public_key.public_key_base64()).ok();
    refs.iter().any(|identity_ref| {
        if let Some(expected) = identity_ref
            .fingerprint_sha256
            .as_deref()
            .map(str::trim)
            .filter(|expected| !expected.is_empty())
        {
            return fingerprint.as_deref() == Some(expected);
        }
        if let Some(path) = identity_ref
            .path
            .as_deref()
            .map(str::trim)
            .filter(|path| !path.is_empty())
        {
            return path == comment;
        }
        !identity_ref.label.trim().is_empty() && identity_ref.label == comment
    })
}

async fn connect_ssh_agent(
    socket_path: Option<&Path>,
) -> Result<AgentClient<Box<dyn AgentStream + Send + Unpin + 'static>>, String> {
    #[cfg(unix)]
    {
        if let Some(path) = socket_path {
            return AgentClient::connect_uds(path)
                .await
                .map(|client| client.dynamic())
                .map_err(|error| format!("无法连接 SSH agent socket {}: {error}", path.display()));
        }
        AgentClient::connect_env()
            .await
            .map(|client| client.dynamic())
            .map_err(|error| format!("无法连接 SSH_AUTH_SOCK: {error}"))
    }

    #[cfg(windows)]
    {
        if let Some(path) = socket_path {
            return AgentClient::connect_named_pipe(path)
                .await
                .map(|client| client.dynamic())
                .map_err(|error| {
                    format!("无法连接 Windows OpenSSH agent {}: {error}", path.display())
                });
        }
        if let Ok(path) = std::env::var("SSH_AUTH_SOCK") {
            if !path.trim().is_empty() {
                return AgentClient::connect_named_pipe(path)
                    .await
                    .map(|client| client.dynamic())
                    .map_err(|error| format!("无法连接 Windows OpenSSH agent: {error}"));
            }
        }
        AgentClient::connect_pageant()
            .await
            .map(|client| client.dynamic())
            .map_err(|error| format!("无法连接 Pageant: {error}"))
    }

    #[cfg(not(any(unix, windows)))]
    {
        Err("当前平台不支持 ssh-agent".to_string())
    }
}

async fn authenticate_keyboard_interactive(
    session: &mut client::Handle<PortMateSshHandler>,
    username: String,
    password: String,
) -> Result<bool, String> {
    let mut response = session
        .authenticate_keyboard_interactive_start(username, None::<String>)
        .await
        .map_err(|error| format!("SSH keyboard-interactive 启动失败: {error}"))?;

    for _ in 0..8 {
        match response {
            KeyboardInteractiveAuthResponse::Success => return Ok(true),
            KeyboardInteractiveAuthResponse::Failure { .. } => return Ok(false),
            KeyboardInteractiveAuthResponse::InfoRequest { prompts, .. } => {
                let responses = prompts
                    .iter()
                    .map(|prompt| {
                        if prompt.echo {
                            String::new()
                        } else {
                            password.clone()
                        }
                    })
                    .collect::<Vec<_>>();
                response = session
                    .authenticate_keyboard_interactive_respond(responses)
                    .await
                    .map_err(|error| format!("SSH keyboard-interactive 响应失败: {error}"))?;
            }
        }
    }

    Err("SSH keyboard-interactive 认证轮次过多，已中止".to_string())
}

fn ordered_auth_methods(ssh: &SshConnection) -> Vec<AuthMethod> {
    let mut ordered = Vec::new();
    if let Some(last) = ssh.identity_policy.last_successful {
        ordered.push(last);
    }
    for method in &ssh.identity_policy.auth_order {
        if !ordered.contains(method) {
            ordered.push(*method);
        }
    }
    if ordered.is_empty() {
        ordered.extend([
            AuthMethod::PublicKey,
            AuthMethod::KeyboardInteractive,
            AuthMethod::Password,
        ]);
    }
    ordered
}

fn load_identity_private_key(
    identity: &IdentityRef,
    passphrase: Option<&str>,
) -> Result<Option<ssh_key::PrivateKey>, String> {
    match identity.source {
        IdentitySource::SystemFile => {
            let Some(path) = identity
                .path
                .as_deref()
                .map(str::trim)
                .filter(|path| !path.is_empty())
            else {
                return Ok(None);
            };
            load_secret_key(expand_identity_path(path), passphrase)
                .map(Some)
                .map_err(|error| format!("system-file {}: {error}", path))
        }
        IdentitySource::ProfileVault => {
            let Some(secret_ref) = identity
                .secret_ref
                .as_deref()
                .map(str::trim)
                .filter(|secret_ref| !secret_ref.is_empty())
            else {
                return Err("profile-vault identity 缺少 secretRef".to_string());
            };
            let private_key = read_secret_from_store(secret_ref)?;
            decode_secret_key(&private_key, passphrase)
                .map(Some)
                .map_err(|error| format!("profile-vault {secret_ref}: {error}"))
        }
        IdentitySource::Agent | IdentitySource::PublicKeyOnly => Ok(None),
    }
}

fn ssh_connection(profile: &SessionProfile) -> Result<&SshConnection, String> {
    match &profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => Ok(ssh),
        _ => Err(format!("Profile {} 不是 SSH/Tmux 会话", profile.id)),
    }
}

fn ssh_connection_mut(profile: &mut SessionProfile) -> Result<&mut SshConnection, String> {
    match &mut profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => Ok(ssh),
        _ => Err(format!("Profile {} 不是 SSH/Tmux 会话", profile.id)),
    }
}

fn profile_proxy(profile: &SessionProfile) -> Option<&ProxyConfig> {
    match &profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => Some(&ssh.proxy),
        ConnectionConfig::Tcp(tcp) | ConnectionConfig::Telnet(tcp) => Some(&tcp.proxy),
        ConnectionConfig::Serial(_) | ConnectionConfig::Shell(_) => None,
    }
}

fn profile_proxy_mut(profile: &mut SessionProfile) -> Option<&mut ProxyConfig> {
    match &mut profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => Some(&mut ssh.proxy),
        ConnectionConfig::Tcp(tcp) | ConnectionConfig::Telnet(tcp) => Some(&mut tcp.proxy),
        ConnectionConfig::Serial(_) | ConnectionConfig::Shell(_) => None,
    }
}

fn find_client_identity(
    store: &SessionStore,
    profile_id: &str,
    identity_id: &str,
) -> Result<IdentityRef, String> {
    let profile = store
        .profiles
        .iter()
        .find(|profile| profile.id == profile_id)
        .ok_or_else(|| format!("unknown session: {profile_id}"))?;
    let ssh = ssh_connection(profile)?;
    let matches = ssh
        .identity_refs
        .iter()
        .filter(|identity| identity.id == identity_id)
        .collect::<Vec<_>>();
    match matches.as_slice() {
        [identity] => Ok((*identity).clone()),
        [] => Err(format!("unknown client identity: {identity_id}")),
        _ => Err(format!(
            "Profile {profile_id} 中存在重复 identity id: {identity_id}"
        )),
    }
}

fn validate_profile_client_identity_ids(profile: &SessionProfile) -> Result<(), String> {
    let Ok(ssh) = ssh_connection(profile) else {
        return Ok(());
    };
    let mut ids = HashSet::new();
    for identity in &ssh.identity_refs {
        if identity.id.trim().is_empty() {
            return Err(format!("Profile {} 包含空 identity id", profile.id));
        }
        if !ids.insert(identity.id.as_str()) {
            return Err(format!(
                "Profile {} 中存在重复 identity id: {}",
                profile.id, identity.id
            ));
        }
    }
    Ok(())
}

fn normalize_client_identity<F>(
    expected_id: &str,
    mut identity: IdentityRef,
    check_secret: F,
) -> Result<IdentityRef, String>
where
    F: FnOnce(&str) -> Result<(), String>,
{
    if identity.id != expected_id || identity.id.trim().is_empty() {
        return Err("identity id 不可修改且不能为空".to_string());
    }
    identity.label = identity.label.trim().to_string();
    if identity.label.is_empty() {
        return Err("identity label 不能为空".to_string());
    }
    identity.fingerprint_sha256 = identity
        .fingerprint_sha256
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned);
    identity.path = identity
        .path
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned);
    identity.secret_ref = identity
        .secret_ref
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned);

    match identity.source {
        IdentitySource::ProfileVault => {
            let secret_ref = identity
                .secret_ref
                .as_deref()
                .ok_or_else(|| "Profile Vault identity 必须包含 secretRef".to_string())?;
            check_secret(secret_ref)?;
            identity.path = None;
        }
        IdentitySource::SystemFile => {
            if identity.path.is_none() {
                return Err("System File identity 必须包含私钥路径".to_string());
            }
            identity.secret_ref = None;
        }
        IdentitySource::Agent | IdentitySource::PublicKeyOnly => {
            identity.secret_ref = None;
        }
    }
    Ok(identity)
}

fn replace_client_identity(
    store: &mut SessionStore,
    profile_id: &str,
    identity_id: &str,
    identity: IdentityRef,
) -> Result<(SessionSummary, Option<String>), String> {
    let profile = store
        .profiles
        .iter_mut()
        .find(|profile| profile.id == profile_id)
        .ok_or_else(|| format!("unknown session: {profile_id}"))?;
    let ssh = ssh_connection_mut(profile)?;
    let matching = ssh
        .identity_refs
        .iter()
        .enumerate()
        .filter(|(_, identity)| identity.id == identity_id)
        .map(|(index, _)| index)
        .collect::<Vec<_>>();
    let index = match matching.as_slice() {
        [index] => *index,
        [] => return Err(format!("unknown client identity: {identity_id}")),
        _ => {
            return Err(format!(
                "Profile {profile_id} 中存在重复 identity id: {identity_id}"
            ));
        }
    };
    let old_secret_ref = ssh.identity_refs[index].secret_ref.clone();
    ssh.identity_refs[index] = identity;
    let summary = store
        .summaries()
        .into_iter()
        .find(|summary| summary.profile.id == profile_id)
        .ok_or_else(|| format!("session summary is missing: {profile_id}"))?;
    Ok((summary, old_secret_ref))
}

fn remove_client_identity(
    store: &mut SessionStore,
    profile_id: &str,
    identity_id: &str,
) -> Result<(SessionSummary, Option<String>), String> {
    let current = find_client_identity(store, profile_id, identity_id)?;
    let profile = store
        .profiles
        .iter_mut()
        .find(|profile| profile.id == profile_id)
        .ok_or_else(|| format!("unknown session: {profile_id}"))?;
    let ssh = ssh_connection_mut(profile)?;
    if ssh
        .jumps
        .iter()
        .any(|jump| jump.identity_ref.as_deref() == Some(identity_id))
    {
        return Err("identity 正被 Jump Host 使用，无法移除".to_string());
    }
    ssh.identity_refs
        .retain(|identity| identity.id != identity_id);
    let summary = store
        .summaries()
        .into_iter()
        .find(|summary| summary.profile.id == profile_id)
        .ok_or_else(|| format!("session summary is missing: {profile_id}"))?;
    Ok((summary, current.secret_ref))
}

fn canonical_secret_ref(secret_ref: &str) -> Option<String> {
    let secret_ref = secret_ref.trim();
    if secret_ref.is_empty() || secret_ref.contains('\0') {
        return None;
    }
    if let Some(account) = secret_ref.strip_prefix("stronghold:") {
        return (!account.is_empty()).then(|| format!("stronghold:{account}"));
    }
    let account = secret_ref.strip_prefix("keychain:").unwrap_or(secret_ref);
    (!account.is_empty()).then(|| format!("keychain:{account}"))
}

fn secret_ref_usage_count(store: &SessionStore, secret_ref: &str) -> usize {
    let Some(expected) = canonical_secret_ref(secret_ref) else {
        return 0;
    };
    let profile_count = store
        .profiles
        .iter()
        .flat_map(profile_secret_ref_occurrences)
        .filter(|secret_ref| secret_ref == &expected)
        .count();
    let one_key_count = store
        .one_keys
        .iter()
        .flat_map(one_key_secret_refs)
        .filter(|secret_ref| secret_ref == &expected)
        .count();
    profile_count + one_key_count
}

fn profile_secret_refs(profile: &SessionProfile) -> HashSet<String> {
    profile_secret_ref_occurrences(profile)
        .into_iter()
        .collect()
}

