        assert_eq!(
            validate_sysmon_history_query_limit(None).unwrap(),
            DEFAULT_SYSMON_HISTORY_QUERY_LIMIT
        );
        assert_eq!(validate_sysmon_history_query_limit(Some(1)).unwrap(), 1);
