        assert!(command.contains("part=\"${target%/*}/${target##*/}.portmate-part\""));
        assert!(command.contains("tail -c +$((offset + 1)) -- \"$src\" >> \"$part\""));
        assert!(command.contains("mv -f -- \"$part\" \"$target\""));
